    "title": "에덴동산의 무화과나무 잎 치마(창 3:7)와 하나님이 지어 입히신 가죽옷(코트노트 오르, 창 3:21)",
    "origTitle": "Garments of Skin (Kotnot Or) vs Fig Leaves",
    "scriptures": "창 3:7; 3:21",
    "hook": "아담과 하와가 무화과나무 잎을 엮어 치마로 삼은 본문 기록(창 3:7)과 여호와 하나님이 가죽옷을 지어 입히신 기록(창 3:21)을 살펴보고, 본문 사실과 이를 대속의 예표로 읽는 신학적 해석을 구분하여 정리합니다.",
    "visualGuide": "시들어 부서지는 무화과 잎사귀와 대조되는 따뜻한 양가죽 통옷(최초의 대속 피 흘림 상징)",
    "dossierMd": "■ [B001] 에덴동산의 무화과나무 잎 치마(창 3:7)와 가죽옷(코트노트 오르, 창 3:21)\n• 분류: 구약 01_창조·원역사 | T01_언약·구속사\n• 본문: 창세기 3:7, 21\n• 핵심 인물·장소: P001(아담), P002(하와) | 에덴동산 | E003\n\n1. 성경 본문의 기록 (창세기 3:7, 21)\n• 창세기 3장 7절: '이에 그들의 눈이 밝아져 자기들이 벗은 줄을 알고 무화과나무 잎을 엮어 치마로 삼았더라.'\n• 창세기 3장 21절: '여호와 하나님이 아담과 그의 아내를 위하여 가죽옷을 지어 입히시니라.'\n• 본문 확인: 성경 본문은 아담과 하와가 무화과나무 잎으로 치마(히브리어 '하고로트', 허리 가리개)를 만든 일과, 여호와 하나님이 그들을 위해 가죽옷(히브리어 '코트노트 오르', כָּתְנוֹת עוֹר)을 지어 입히셨다는 사실을 간결하게 기록합니다. 하나님이 무화과 치마를 벗기셨다는 장면이나 동물을 잡아 희생제사를 드리셨다는 언급은 본문에 직접 명시되어 있지 않습니다.\n\n2. 어원·문화적 배경\n• 무화과나무 잎 치마('하고로트'): 팔레스타인 무화과나무 잎은 넓지만 수분이 마르면 쉽게 오그라들고 부서져 오래 입을 수 없는 임시 가리개입니다.\n• 가죽옷('코트노트 오르'): '케토네트(속옷·긴 겉옷)'는 어깨부터 무릎까지 덮는 옷으로, 후대 출애굽기 28:40에서 제사장의 속옷을 가리킬 때도 같은 단어가 쓰입니다.\n\n3. 신학적 해석 (본문 기록과 예표론적 해석의 구분)\n• 본문 자체는 에덴동산에서 추방되어 거친 땅을 경작해야 할 아담과 하와를 여전히 돌보시고 보호하시는 하나님의 긍휼을 보여 줍니다.\n• 나아가 기독교 신학 전통(교부들과 종교개혁 주석 전통)은 이 장면을 예표론적으로 해석하여, 인간의 자구책(무화과 잎)으로는 죄의 수치를 온전히 가릴 수 없으며 하나님이 친히 입혀 주시는 은총—궁극적으로 예수 그리스도의 십자가 대속과 의의 옷(롬 13:14; 갈 3:27)—을 미리 가리키는 구속사적 예표로 읽습니다.",
