    "title": "아브라함의 쪼갠 고기 사이로 홀로 지나가신 타는 횃불 언약",
    "origTitle": "Smoking Firepot & Flaming Torch Passing Between the Pieces",
    "scriptures": "창 15:9~18; 렘 34:18",
    "hook": "왜 고대 근동 언약법과 달리 아브라함은 잠들고 하나님(타는 횃불)만 홀로 피 묻은 고기 사이를 지나가셨을까?",
    "visualGuide": "밤하늘 별 아래 양옆으로 쪼개진 제물 사이를 홀로 통과하는 타는 횃불과 연기 나는 풀무",
    "dossierMd": "■ B003 | 아브라함의 쪼갠 고기 사이로 왜 '타는 횃불'만 홀로 지나갔을까?\n• 분류: 구약 · 02_족장시대 | 테마: T02_문화·관습 · T08_구속사·모형\n• 핵심 성경 본문: 창세기 15:9~18 (참조: 예레미야 34:18~19)\n• 삼각 연동 코드: 인물 P004(아브라함) | 사건 E006(아브라함 횃불 언약과 믿음의 칭의)\n• 호기심 질문 (The Hook): \"고대 근동에서 동물을 반으로 쪼개 마주 놓는 의식은 무슨 뜻이었으며, 왜 아브라함은 잠들고 하나님(연기 나는 풀무와 타는 횃불)만 홀로 그 피의 통로를 걸어가셨을까?\"\n• 표면적 읽기 vs 행간의 진짜 배경: 표면적 읽기: 하나님이 아브라함에게 땅을 주겠다는 약속의 표시로 신비한 불꽃 기적을 보여주신 것으로만 이해합니다.\n• 행간의 진실: 고대 근동(메소포타미아 마리 문서 및 렘 34:18)에서 히브리어 '언약을 맺다(카라트 베리트, כָּרַת בְּרִית)'의 직역은 \"언약을 쪼개다/자르다\"입니다. 종주국 왕과 봉신(신하)이 조약을 맺을 때 짐승을 반으로 쪼개 양옆에 벌려 놓고, 약속을 지켜야 할 아랫사람(또는 쌍방)이 피가 흥건한 그 사이를 걸어가며 \"만일 내가 이 언약을 어기면 이 쪼개진 짐승처럼 내 몸이 쪼개져도 좋습니다\"라고 목숨을 건 맹세를 하는 살벌한 법적 의식이었습니다.\n• 깊이 읽는 비하인드 스토리텔링: 원래 고대 관습대로라면 아브라함이 그 쪼갠 고기 사이를 걸어가야 했습니다. 그러나 연약한 인간 아브라함은 언약을 어길 수밖에 없는 존재임을 하나님은 아셨습니다. 그래서 하나님은 아브라함을 깊은 잠에 빠뜨려 옆에 눕혀 두시고, 하나님 자신을 상징하는 '연기 나는 풀무와 타는 횃불'이 홀로 그 피 묻은 고기 사이를 지나가셨습니다!\n• 이는 \"아브라함아, 내가 약속을 어기면 내 몸이 쪼개질 뿐 아니라, 네가 나중에 약속을 어기더라도 그 쪼개지는 저주와 죽음까지 내가 대신 다 짊어지겠다\"라는 일방적 은혜의 선언이었습니다. 그리고 실제로 2천 년 뒤, 골고다 십자가에서 성자 예수님의 몸이 쪼개지심으로 이 횃불 언약의 대가를 친히 지불하셨습니다.\n• 구속사적 울림 & 『꿈바온』 한 줄 묵상:\n\"내가 어긴 약속의 대가까지 주님이 홀로 걸어가시며 지불하셨기에, 하나님의 언약은 나의 흔들림과 상관없이 영원히 안전합니다.\"\n• 시각 고증 및 장면 가이드: 캄캄한 밤하늘의 무수한 별 아래, 양쪽으로 쪼개어 놓은 제물 사이로 타오르는 횃불과 연기가 홀로 지나가고 바위 곁에 깊이 잠든 아브라함.",
