    "hook": "왜 창세기 22장 19절에는 산에서 내려올 때 이삭의 이름이 사라지고 신부 리브가를 맞이하는 24장에야 다시 등장할까?",
    "visualGuide": "모리아산 번제단 옆 수풀에 걸린 숫양과 브엘라해로이 저녁 들녘에서 리브가를 맞이하는 이삭",
    "dossierMd": "■ B004 | 모리아산에 함께 올라간 아브라함과 이삭, 내려올 때는 왜 '아브라함만' 내려왔을까?\n• 분류: 구약 · 02_족장시대 | 테마: T03_행간·인물관계 · T08_구속사·모형\n• 핵심 성경 본문: 창세기 22:5~8, 22:19, 24:62~63\n• 삼각 연동 코드: 인물 P004(아브라함), P006(이삭) | 사건 E009(모리아산 이삭 번제 시험과 여호와 이레)\n• 호기심 질문 (The Hook): \"창세기 22장 6절과 8절에는 분명 '두 사람이 함께(야흐다우) 갔더라'고 두 번이나 강조하는데, 19절에 산에서 내려올 때는 왜 이삭의 이름이 사라지고 '아브라함이 종들에게로 돌아왔더라'고만 기록되었을까?\"\n• 표면적 읽기 vs 행간의 진짜 배경: 표면적 읽기: 당연히 둘이 같이 내려왔는데 성경 기자가 아브라함만 대표로 적었겠거니 하고 넘어갑니다.\n• 행간의 진실: 히브리 본문은 놀라울 만큼 정교합니다. 산에 오를 때는 \"두 사람이 함께(야흐다우) 갔더라\"(6, 8절)고 거듭 강조하던 본문이, 19절에서는 단수 동사(와야솨브 아브라함, 아브라함이 돌아왔더라)를 써서 아브라함 혼자 사환들에게 내려와 브엘세바로 간 것처럼 기록합니다. 그리고 이삭은 창세기 23장(어머니 사라의 헤브론 죽음과 매장)에도 전혀 모습을 드러내지 않다가, 창세기 24장 62절(브엘라해로이 들녘에서 저물 때 묵상하며 리브가를 맞이하는 장면)에야 비로소 다시 등장합니다!\n• 깊이 읽는 비하인드 스토리텔링: 유대 랍비 전승(미드라쉬)과 구속사적 주석가들은 이 행간의 침묵 속에서 두 가지 깊은 비하인드를 읽어냅니다. 첫째, 100세 노인 아브라함이 장성한 청년 이삭을 결박할 수 있었던 것은 이삭의 자발적 순종 때문이었습니다. 번제단 위에서 죽음과 부활을 간접 체험한 이삭은 그 후 브엘라해로이('나를 감찰하시는 살아계신 이의 우물')에서 깊은 기도와 묵상의 사람으로 성숙해졌습니다.\n• 둘째, 구속사적 모형론(Typology)에서 모리아산의 이삭은 죽기까지 순종하신 독생자 예수 그리스도의 예표입니다. 갈보리 제단에 오르신 어린양 예수님은 승천하신 뒤, 성령을 통해 준비된 신부(교회 = 리브가)를 맞이하기까지 아버지 집에서 기다리십니다. 이삭이 모리아산 제단 사건 이후 신부 리브가를 맞이하는 날(창 24장)까지 본문 표면에서 감추어져 있는 것은, 제단에서 드려진 아들이 신부를 맞이할 신랑으로 다시 나타나는 구속사의 그림자입니다.\n• 구속사적 울림 & 『꿈바온』 한 줄 묵상:\n\"제단 위에서 아버지의 뜻에 자신을 묶으셨던 순종의 아들은, 마침내 저무는 들녘에서 사랑하는 신부를 맞이하는 신랑으로 걸어오십니다.\"\n• 시각 고증 및 장면 가이드: 모리아산 제단 옆 수풀에 걸린 숫양과 밝아오는 아침 햇살, 그리고 브엘라해로이 저녁 들녘에서 낙타를 타고 오는 리브가를 바라보며 묵상하는 이삭의 교차 구도.",
