    "hook": "고관절이 빠져 절뚝거리게 된 야곱에게 왜 하나님은 '네가 하나님과 겨루어 이겼다'고 선언하셨을까?",
    "visualGuide": "브니엘 새벽빛 아래 절뚝거리면서도 하나님의 사자의 목을 눈물로 끌어안고 매달리는 야곱",
    "dossierMd": "■ B005 | 왜 야곱은 얍복강 나루에서 천사에게 허벅지 관절이 위골되고도 '내가 이겼다'고 했을까?\n• 분류: 구약 · 02_족장시대 | 테마: T01_원어·언어유희 · T02_문화·관습\n• 핵심 성경 본문: 창세기 32:22~32 (참조: 호세아 12:3~4)\n• 삼각 연동 코드: 인물 P007(야곱) | 사건 E010(얍복강 씨름과 이스라엘 개명)\n• 호기심 질문 (The Hook): \"사람이 허벅지 관절(고관절)이 빠져 절뚝거리게 되면 씨름에서 진 것인데, 왜 하나님은 오히려 야곱에게 '네가 하나님과 겨루어 이겼다(이스라엘)'고 선언하셨을까?\"\n• 표면적 읽기 vs 행간의 진짜 배경: 표면적 읽기: 야곱이 체력이 대단해서 밤새 천사를 힘으로 제압해 이겼다고 생각하기 쉽습니다.\n• 행간의 진실: 창세기 32장 24~25절 원문에는 야곱(Ya'aqob) - 얍복(Yabboq) - 씨름하다(Ye'abeq)라는 3중 히브리어 소리 중첩 언어유희가 깔려 있습니다. 평생 남의 발뒤꿈치를 잡고 자기 잔꾀와 다리 힘으로 살아온 야곱의 가장 강한 중심축(허벅지 관절, 대퇴골두)을 하나님의 사자가 손끝 하나로 살짝 '만지시매(와이가)' 그 즉시 어긋나 버렸습니다. 즉, 힘으로 이긴 것이 전혀 아닙니다!\n• 깊이 읽는 비하인드 스토리텔링: 고관절이 탈구되면 성인 남성은 자기 힘으로 서 있을 수도 없고, 더 이상 공격 기술을 쓸 수도 없습니다. 그때부터 야곱이 할 수 있는 유일한 행동은 무너진 몸으로 상대방의 목을 죽기 살기로 끌어안고 매달리는 것뿐이었습니다. 호세아 12장 4절은 그 순간의 비하인드를 이렇게 폭로합니다. \"천사와 힘을 겨루어 이기고 울며 그에게 간구하였으며...\"\n• 하나님 나라의 역설이 여기에 있습니다. 야곱이 자기 다리 힘으로 버틸 때는 하나님을 이길 수 없었지만, 자기 힘의 근원(허벅지 관절)이 완전히 꺾여 눈물로 하나님께 매달릴 때, 하나님은 비로소 \"네가 나를 이겼다(이스라엘)!\"라고 손을 들어주셨습니다. 성도의 승리는 내 힘으로 버티는 것이 아니라, 내 고집이 꺾인 자리에서 주님의 옷자락에 매달리는 것입니다.\n• 구속사적 울림 & 『꿈바온』 한 줄 묵상:\n\"하나님은 나의 가장 강한 고집의 뼈를 꺾으심으로, 평생 주님만 의지하며 걷는 '이스라엘'의 지팡이를 선물하십니다.\"\n• 시각 고증 및 장면 가이드: 브니엘의 동터 오는 붉은 새벽빛, 얍복강 물가에서 절뚝거리면서도 하나님의 사자를 눈물로 꼭 끌어안고 놓지 않는 야곱의 모습.",
