    "scriptures": "출 7:14~12:30; 12:12",
    "hook": "왜 하나님은 애굽을 치실 때 무작위 재난이 아니라 정확히 이집트인들이 섬기던 10대 신의 영역을 하나씩 무너뜨리셨을까?",
    "visualGuide": "금이 가며 무너지는 이집트 10대 우상 부조와 어린양의 피가 발린 고센 땅 히브리 가옥의 등불",
    "dossierMd": "■ B006 | 출애굽 열 가지 재앙은 왜 무작위 재난이 아니라 '이집트 10대 신(神)들의 공개 처형'이었을까?\n• 분류: 구약 · 03_출애굽·광야 | 테마: T06_역사·고고학 · T02_문화·관습\n• 핵심 성경 본문: 출애굽기 7:14~12:30 (참조: 출애굽기 12:12, 민수기 33:4)\n• 삼각 연동 코드: 인물 P009(모세), P010(아론), 출애굽 바로 | 사건 E012(출애굽과 열 재앙·유월절)\n• 호기심 질문 (The Hook): \"피·개구리·이·파리·가축 돌림병·악성 종기·우박·메뚜기·흑암·장자 죽음 — 왜 하나님은 하필 이 열 가지 항목을 골라 애굽을 치셨을까?\"\n• 표면적 읽기 vs 행간의 진짜 배경: 표면적 읽기: 바로가 말을 안 들으니까 점점 더 무서운 자연재해를 보내어 항복을 받아내신 사건으로만 봅니다.\n• 행간의 진실: 출애굽기 12장 12절에서 하나님은 열 재앙의 진짜 목적을 명확히 밝히십니다. \"내가 애굽의 모든 신(神)들에게 벌을 내리리라 나는 여호와라!\" 즉, 열 가지 재앙은 이집트 사람들이 목숨처럼 숭배하던 이집트 판테온의 10대 주신(主神)들을 일대일로 지목하여 무력화시킨 영적 공개 재판이었습니다.\n• 깊이 읽는 비하인드 스토리텔링 (10대 재앙 vs 이집트 신 대조):\n1. 나일강 피 재앙: 나일강의 범람과 풍요의 신 하피(Hapi) & 나일강 수호신 크눔(Khnum) 심판\n2. 개구리 재앙: 다산과 부활을 상징하는 개구리 머리의 여신 헤케트(Heqet) 심판 (이집트 법상 개구리를 죽이는 것이 금지되어 있어 스스로 치우지도 못함!)\n3. 이(티끌) 재앙: 대지(땅)의 신 게브(Geb) 심판 (요술사들이 '이는 하나님의 권능(손가락)이니이다' 항복)\n4. 파리 재앙: 부활과 태양의 상징인 풍뎅이/파리 신 케프리(Khepri) 심판 (고센 땅 구별 시작)\n5. 가축 돌림병: 성스러운 황소 신 아피스(Apis)와 암소 여신 하토르(Hathor) 심판\n6. 악성 종기(독종): 의술과 치유의 신 임호테프(Imhotep)와 역병의 여신 세크메트(Sekhmet) 심판 (제사장들이 부정하게 되어 신전에 들어가지 못함)\n7. 우박과 불덩이: 하늘의 여신 누트(Nut)와 폭풍의 신 세트(Seth) 심판\n8. 메뚜기 재앙: 곡물의 수호신 네프리와 세라피스 심판\n9. 사흘간의 흑암: 이집트 최고 태양신 라(Ra / 아문-라)의 완전한 굴복\n10. 장자의 죽음과 유월절: 스스로를 '호루스/태양신의 아들(현인신)'이라 부르던 파라오 왕권 자체에 대한 최종 심판과 어린양의 피로 구원받는 구속의 계시!\n• 구속사적 울림 & 『꿈바온』 한 줄 묵상:\n\"세상이 신처럼 의지하는 돈과 권력과 풍요의 우상들이 무너질 때, 오직 여호와 한 분만이 참 하나님이심이 드러납니다.\"\n• 시각 고증 및 장면 가이드: 이집트 신전 벽화의 우상들(하피, 헤케트, 아피스, 태양신 라)이 금이 가며 무너지고, 인방과 문설주에 어린양의 피를 바른 히브리인의 집만 따뜻한 등불이 켜진 대비 인포그래픽.",
