    "title": "유월절 어린양의 피를 문지방(바닥)에는 절대 바르지 말고 인방과 문설주에만 바른 이유",
    "origTitle": "Blood on the Lintel and Two Doorposts Never Underfoot on the Threshold",
    "scriptures": "출 12:7; 12:22; 히 10:29",
    "hook": "왜 문틀 네 면 중 위쪽 인방과 양옆 문설주 세 곳에만 피를 바르고 바닥 문지방에는 바르지 말라고 하셨을까?",
    "visualGuide": "우슬초로 인방과 좌우 문설주에 바른 핏자국이 십자가 형상을 이루고 대속의 피를 발로 밟지 않는 구조",
    "dossierMd": "■ B007 | 유월절 어린양의 피를 왜 '문지방(바닥)'에는 절대 바르지 말고 인방과 문설주에만 바르라 하셨을까?\n• 분류: 구약 · 03_출애굽·광야 | 테마: T04_사물·생활사 · T08_구속사·모형\n• 핵심 성경 본문: 출애굽기 12:7, 12:22 (참조: 히브리서 10:29)\n• 삼각 연동 코드: 인물 P009(모세) | 사건 E012(출애굽과 열 재앙·유월절), E027(예수 그리스도의 십자가 대속)\n• 호기심 질문 (The Hook): \"집 문틀은 네 면인데, 왜 하나님은 위쪽 가로대(인방)와 양옆 기둥(좌우 문설주) 세 곳에만 피를 바르고 아래쪽 문지방에는 바르지 말라고 하셨을까?\"\n• 표면적 읽기 vs 행간의 진짜 배경: 표면적 읽기: 밖에서 잘 보이는 문 위쪽과 옆쪽에만 바르라고 하신 단순한 위치 지시로 보입니다.\n• 행간의 진실: 문을 둘러싼 4면 중 바닥에 있는 문지방(Threshold)에 피를 바르면, 집을 드나드는 사람들이 대속의 피를 발로 밟고 지나가게 됩니다! 히브리서 10장 29절이 \"하물며 하나님의 아들을 짓밟고 자기를 거룩하게 한 언약의 피를 부정한 것으로 여기고...\"라고 경고하듯, 생명을 살린 거룩한 보혈은 결코 인간의 발아래 짓밟힐 수 없는 보배로운 피였기 때문입니다.\n• 깊이 읽는 비하인드 스토리텔링: 더 나아가, 양푼(사프)에 담긴 어린양의 피를 우슬초 묶음에 적셔 위쪽 인방(머리)을 찍고, 좌우 문설주(양손)에 바를 때, 인방에서 흘러내린 핏방울이 문 밑바닥으로 떨어지며 문틀 전체에 어떤 형상이 그려졌을까요? 바로 양팔을 벌리고 머리와 발에서 피 흘리시는 예수 그리스도의 십자가 형상입니다!\n• 또한 히브리어 '유월하다(파사흐, פָּסַח)'(출 12:13)는 단순히 '건너뛰어 지나가다(Pass over)'라는 뜻만 있는 것이 아닙니다. 이사야 31장 5절에서 새가 날개를 펴서 새끼를 덮어 보호할 때 쓰인 단어처럼, \"여호와께서 피 묻은 문 위를 날개로 덮어(Hovering over) 죽음의 사자로부터 직접 막아 서셨다\"는 감격적인 원어적 의미를 품고 있습니다.\n• 구속사적 울림 & 『꿈바온』 한 줄 묵상:\n\"집 안에 있던 장자가 잘나서 산 것이 아니라, 문밖의 피를 보시고 주님이 친히 문 앞을 막아 서 주셨기에 우리가 살았습니다.\"\n• 시각 고증 및 장면 가이드: 우슬초 묶음으로 문 위 인방과 좌우 문설주에 바른 붉은 핏자국이 은은한 십자가의 빛으로 이어지고, 집 안에서는 허리에 띠를 띠고 지팡이를 짚은 채 양고기를 먹는 가족.",
