    "dossierMd": "■ B009 | 보아스는 왜 베들레헴 성문 재판석에서 '신발 한 짝'을 벗어 들었을까?\n• 분류: 구약 · 04_가나안정복·사사 | 테마: T02_문화·관습 · T08_구속사·모형\n• 핵심 성경 본문: 룻기 4:1~10 (참조: 신명기 25:7~10)\n• 삼각 연동 코드: 인물 P017(룻), P245(보아스), P244(나오미) | 사건 E017(룻과 보아스의 기업 무름과 다윗 계보)\n• 호기심 질문 (The Hook): \"보아스보다 순위가 앞섰던 익명의 친족('아무개')이 룻과 결혼하기를 포기하며 신발을 벗어 보아스에게 건넨 행동은 고대 이스라엘에서 어떤 법적 의미를 가졌을까?\"\n• 표면적 읽기 vs 행간의 진짜 배경: 표면적 읽기: 옛날 사람들의 특이한 계약 서명 방식 정도로만 가볍게 읽고 지나갑니다.\n• 행간의 진실: 고대 근동(누지 문서)과 이스라엘 사회에서 '신발(나알, נַעַל)'은 단순한 신발이 아니라 \"그 땅을 밟고 다스릴 수 있는 소유권과 가장의 책임\"을 상징했습니다(시 60:8 \"에돔에는 내 신발을 던지리라\"). 원래 신명기 25장 9절의 계대혼 규례에서는 형제의 기업 무르기를 거부한 비겁한 사람의 신발을 과부가 직접 벗기고 얼굴에 침을 뱉어 '신 벗김 받은 자의 집'이라는 수치를 안겼습니다.\n• 깊이 읽는 비하인드 스토리텔링: 룻기 4장에 등장하는 1순위 기업 무를 자는 히브리어 원문에서 이름조차 기록되지 않은 채 '플로니 알모니(פְּלֹנִי אַלְמֹנִי, 아무개 씨)'(룻 4:1)라고 불립니다. 그는 나오미의 밭은 탐냈지만, 이방 여인 룻을 아내로 맞아 죽은 자의 이름으로 아들을 낳아주어야 한다는 말을 듣자 \"내 기업에 손해가 날까 하여\" 스스로 신발을 벗어 던지고 권리를 포기했습니다. 자기 이익과 계산을 앞세운 그는 성경 역사에서 이름조차 남지 않는 '아무개'로 사라졌습니다.\n• 반면 보아스는 아무런 대가도 바라지 않고 기꺼이 그 벗겨진 신발을 넘겨받아 모압 여인 룻의 수치를 덮어주었고, 그 희생적인 사랑의 결실로 오벳 → 이새 → 다윗 왕 → 예수 그리스도로 이어지는 구속사 최고의 족보에 영원히 이름을 남겼습니다. 우리의 진정한 고엘(기업 무를 자)이신 예수 그리스도 역시 우리가 갚을 수 없는 죄의 빚을 대신 지시고 십자가에서 모든 권리를 회복해 주셨습니다.\n• 구속사적 울림 & 『꿈바온』 한 줄 묵상:\n\"손익을 계산하며 신발을 벗어 던진 이는 '아무개'로 잊혔으나, 손해를 감수하며 사랑을 택한 보아스는 메시아의 조상이 되었습니다.\"\n• 시각 고증 및 장면 가이드: 베들레헴 성문 돌 의자에 앉은 열 명의 장로들 앞에서 가죽 샌들 한 짝을 높이 들어 증언하는 보아스와 성문 곁에서 감격스레 바라보는 나오미와 룻.",
