    "title": "다윗이 골리앗의 머리를 가져간 '예루살렘'(삼상 17:54)과 예수님의 '골고다(해골의 곳)'의 연결고리",
    "origTitle": "Goliath's Head Taken to Jerusalem & Golgotha (Golyat-Gulgolet)",
    "scriptures": "삼상 17:49~54; 창 3:15; 마 27:33",
    "hook": "왜 소년 다윗은 비늘 갑옷 입은 골리앗의 머리를 예루살렘으로 가져갔으며 골고다 언덕과 어떻게 포개질까?",
    "visualGuide": "청동 비늘 갑옷 입은 골리앗을 쓰러뜨린 다윗 너머로 중첩되는 예루살렘 골고다 언덕의 십자가",
    "dossierMd": "■ B010 | 다윗이 골리앗의 머리를 베어 간 곳('예루살렘')과 예수님의 '골고다(해골의 곳)'에 숨겨진 소름 돋는 연결고리\n• 분류: 구약 · 05_통일왕국 | 테마: T08_구속사·모형 · T01_원어·언어유희\n• 핵심 성경 본문: 사무엘상 17:49~54 (참조: 창세기 3:15, 마태복음 27:33)\n• 삼각 연동 코드: 인물 P021(다윗), P249(골리앗), P026(예수 그리스도) | 사건 E018(다윗과 골리앗의 엘라 골짜기 전투), E027(예수 그리스도의 십자가 대속)\n• 호기심 질문 (The Hook): \"소년 다윗이 엘라 골짜기에서 골리앗을 쓰러뜨린 직후, 왜 아직 여부스 족속의 땅이었던 '예루살렘'으로 골리앗의 머리를 가져갔다고(삼상 17:54) 기록되어 있을까?\"\n• 표면적 읽기 vs 행간의 진짜 배경: 표면적 읽기: 전투가 끝난 뒤 골리앗의 머리를 전리품으로 들고 돌아왔다는 단순한 후일담으로 읽힙니다.\n• 행간의 진실: 사무엘상 17장 54절은 \"다윗은 그 블레셋 사람의 머리를 예루살렘으로 가져가고...\"라고 놀라운 단서를 남깁니다. 당시 골리앗은 히브리어로 '비늘 갑옷(시르욘 카스카심, שִׁרְיוֹן קַשְׂקַשִּׂים)'(삼상 17:5)을 입고 있었는데, 이는 뱀이나 물고기의 비늘을 뜻하는 단어입니다. 즉, 온몸을 청동 비늘 갑옷으로 두르고 하나님의 군대를 모욕하던 골리앗은 창세기 3장 15절의 '여자의 후손이 네 머리를 상하게 할 것이요'라는 원시복음 속 '옛 뱀(사탄)'의 시각적 화신이었습니다.\n• 깊이 읽는 비하인드 스토리텔링: 기름 부음 받은 목자 다윗은 물맷돌로 그 비늘 입은 거인 골리앗의 '이마(머리)'를 정확히 박아 쓰러뜨리고, 그 잘린 머리(해골)를 후일 자신이 점령하게 될 예루살렘으로 가져가 묻었습니다.\n• 그리고 천 년 뒤, '다윗의 자손'으로 오신 참된 왕 예수 그리스도께서 예루살렘 성문 밖 언덕에서 십자가에 못 박히셨는데, 그 언덕의 아람어 이름이 바로 '골고다(Golgotha, 히브리어 굴골레트 גֻּלְגֹּלֶת — 해골의 곳)'입니다! 고대 기독교 전승과 어원학자들은 바로 이 골리앗(Golyat)의 굴골레트(해골)가 묻힌 언덕이라는 데서 골고다라는 지명이 유래했을 가능성에 주목합니다. 다윗이 예루살렘에서 거인의 머리를 밟았듯, 예수님은 바로 그 해골의 언덕(골고다)에서 십자가로 사망과 사탄의 머리를 영원히 박살 내셨습니다!\n• 구속사적 울림 & 『꿈바온』 한 줄 묵상:\n\"엘라 골짜기에서 거인의 이마를 무너뜨린 다윗의 물맷돌은, 골고다 언덕에서 사탄의 머리를 깨뜨리신 그리스도의 십자가를 가리키고 있었습니다.\"\n• 시각 고증 및 장면 가이드: 비늘 갑옷을 입은 골리앗을 쓰러뜨린 소년 다윗의 실루엣 너머로, 예루살렘 골고다 언덕의 십자가가 중첩되는 구속사 브릿지 일러스트.",
