    "title": "3년 반 가뭄 끝 갈멜산 꼭대기 제단에 엘리야가 쏟아부은 '물 열두 통'의 수원과 언약적 의미",
    "origTitle": "Twelve Jars of Water Poured on the Twelve-Stone Altar at Mount Carmel",
    "scriptures": "왕상 18:30~38",
    "hook": "3년 반 동안 비 한 방울 안 온 가뭄 끝자락에 엘리야는 그 귀한 물 열두 통을 어디서 구해 왜 제단에 쏟아부었을까?",
    "visualGuide": "갈멜산 정상 열두 돌 제단 주위 도랑에 물이 가득 고인 가운데 하늘에서 수직으로 내리는 응답의 불",
    "dossierMd": "■ B012 | 왜 엘리야는 갈멜산에서 불이 내리기 직전, 말라붙은 산꼭대기 제단에 '물 열두 통'을 쏟아부었을까?\n• 분류: 구약 · 06_분열왕국 | 테마: T05_지리·생태 · T02_문화·관습\n• 핵심 성경 본문: 열왕기상 18:30~38\n• 삼각 연동 코드: 인물 P023(엘리야), P057(아합) | 사건 E020(갈멜산 850대 1 영적 대결과 불 응답)\n• 호기심 질문 (The Hook): \"3년 반 동안 비 한 방울 오지 않아 온 나라가 갈증에 허덕이던 가뭄 끝자락에, 엘리야는 갈멜산 꼭대기에서 그 귀한 물 열두 통을 어디서 구해 왜 제단 위에 쏟아부었을까?\"\n• 표면적 읽기 vs 행간의 진짜 배경: 표면적 읽기: 불이 잘 안 붙는 조건에서도 하나님이 불을 내리신다는 기적의 난이도를 높이려고 물을 부었다고만 생각합니다.\n• 행간의 진실: 당시 가나안 사람들이 섬기던 바알(Baal Hadad)은 번개와 폭풍우와 비를 다스리는 신이었고, 갈멜산은 바알 숭배의 핵심 성지였습니다. 바알 선지자들은 종일 춤추고 칼로 몸을 베며 피를 흘렸으나 바알은 번개 한 줄기 내리지 못했습니다. 그때 엘리야가 행한 일련의 동작은 철저한 언약 회복 예식이었습니다.\n• 깊이 읽는 비하인드 스토리텔링: 첫째, 엘리야는 먼저 무너진 여호와의 제단을 수축하되, 북이스라엘(10지파)과 남유다(2지파)로 쪼개진 현실에도 불구하고 야곱의 아들들의 수대로 '열두 돌'(왕상 18:31)을 취해 쌓았습니다. 하나님 앞에서는 여전히 열두 지파가 하나의 언약 공동체임을 선포한 것입니다.\n• 둘째, 갈멜산 중턱에는 3년 반의 극심한 가뭄 속에서도 마르지 않는 석회암 지하 용천수('엘 무라카' 인근의 항구적 샘 또는 지중해 바닷물)가 있었습니다. 엘리야는 가뭄 속에서 금보다 귀한 물 네 통을 세 번(총 12통 = 12지파 상징) 제단과 도랑에 넘치도록 부어 '물 부음의 제사(수제, Water Libation)'를 드렸습니다. 이는 훗날 초막절마다 실로암 물을 길어 제단에 부으며 성령과 구원의 생수를 갈망하던 예식의 원형이자, \"우리가 생명처럼 아끼는 마지막 물까지 주님께 다 쏟아부을 때, 하늘의 불과 큰비(왕상 18:45)가 임한다\"는 믿음의 결단이었습니다.\n• 구속사적 울림 & 『꿈바온』 한 줄 묵상:\n\"무너진 열두 돌 제단을 다시 쌓고 내게 남은 가장 귀한 물까지 아낌없이 부어 드릴 때, 하늘의 응답의 불이 내립니다.\"\n• 시각 고증 및 장면 가이드: 지중해가 내려다보이는 갈멜산 정상, 열두 개의 자연석으로 쌓은 제단 주위 도랑에 물이 흥건히 고인 가운데 저녁 소제 시간에 하늘로부터 수직으로 떨어지는 거룩한 불기둥.",
