    "hook": "나침반도 없던 기원전 701년 유다 석공들은 어떻게 지하 암반 533m를 양쪽 끝에서 동시에 파 들어와 정중앙에서 만났을까?",
    "visualGuide": "지하 암반 터널 중앙에서 곡괭이를 맞부딪치며 만나는 석공들과 벽면에 새겨진 고대 히브리 실로암 비문",
    "dossierMd": "■ B013 | 히스기야 터널 한가운데 새겨진 '실로암 비문' — 곡괭이 소리를 듣고 양쪽에서 파 들어오다 만난 기적의 고고학\n• 분류: 구약 · 06_분열왕국 | 테마: T06_역사·고고학 · T05_지리·생태\n• 핵심 성경 본문: 열왕기하 20:20, 역대하 32:2~4, 32:30 (참조: 요한복음 9:7)\n• 삼각 연동 코드: 인물 P043(히스기야), P024(이사야), P287(산헤립) | 사건 E021(히스기야의 기도와 앗수르 18만 5천 격퇴), E084(히스기야의 종교개혁과 실로암 수로 건설)\n• 호기심 질문 (The Hook): \"나침반도 GPS도 없던 기원전 701년, 히스기야의 기술자들은 어떻게 지하 암반 533미터를 S자 곡선으로 양쪽 끝에서 동시에 파 들어와 정중앙에서 정확히 만날 수 있었을까?\"\n• 표면적 읽기 vs 행간의 진짜 배경: 표면적 읽기: 역대하 32장 30절에 \"히스기야가 또 기혼의 윗샘물을 막아 그 아래로부터 다윗 성 서쪽으로 곧게 인도하였으니\"라고 한 줄로 적혀 있어 단순한 도랑 공사로 생각하기 쉽습니다.\n• 행간의 진실: 예루살렘의 유일한 식수원인 기혼 샘(Gihon Spring)은 성벽 바깥 기드론 골짜기에 노출되어 있었습니다. 앗수르 산헤립 대군의 포위 공격이 임박하자, 히스기야는 적군이 물을 쓰지 못하게 기혼 샘 입구를 돌로 위장해 막고, 지하 단단한 석회암 암반을 뚫어 성안 남서쪽 실로암 연못(Pool of Siloam, '보냄을 받았다'는 뜻)까지 총길이 533m(직선거리는 320m이나 지하 단층과 균열을 따라 S자로 굴착)의 암반 터널을 뚫었습니다!\n• 깊이 읽는 비하인드 스토리텔링: 전쟁이 코앞이라 한쪽에서만 파면 시간이 두 배로 걸리므로, 기술자들은 기혼 샘 쪽(북동쪽)과 실로암 못 쪽(남서쪽) 양쪽 끝에서 동시에 곡괭이로 암반을 파 들어가는 초고난도 공법을 택했습니다.\n• 1880년 한 소년이 실로암 터널 출구에서 6m 지점 벽면에서 우연히 발견한 고대 히브리어 비문('실로암 비문', 기원전 701년경)에는 당시 인부들이 암흑 속에서 서로의 정 소리를 듣고 마침내 벽이 뚫리던 순간의 벅찬 감격이 생생히 새겨져 있습니다:\n\"굴이 뚫리던 날의 상황은 이러하다. 아직 석공들이 서로 마주 보며 곡괭이를 들고 찍어 들어갈 때, 뚫어야 할 암벽이 세 규빗(약 1.35m)쯤 남았을 때 한 사람이 상대방을 부르는 소리가 들렸다... 마침내 굴이 뚫리던 날, 석공들은 서로 마주 보고 곡괭이와 곡괭이를 맞부딪쳤고, 샘물에서부터 못까지 1,200규빗에 걸쳐 물이 흘러 들어갔다!\"\n• 그리고 700년 뒤, '세상의 빛'이자 아버지께로부터 '보냄을 받으신(실로암)' 예수님께서 날 때부터 맹인 된 자의 눈에 진흙을 발라 바로 이 실로암 못(요 9:7)에 가서 씻으라 하심으로 영육의 눈을 뜨게 하셨습니다.\n• 구속사적 울림 & 『꿈바온』 한 줄 묵상:\n\"절체절명의 포위 속에서도 바위 밑으로 생수의 길을 내신 하나님은, 오늘도 막힌 현실 아래로 '보냄을 받은 실로암'의 물줄기를 흐르게 하십니다.\"\n• 시각 고증 및 장면 가이드: 횃불을 든 고대 유다 석공들이 지하 암반 터널 중앙에서 마지막 바위를 깨뜨리고 서로 얼싸안는 장면과 발밑으로 콸콸 쏟아져 흐르는 기혼 샘물, 그리고 벽면에 새겨진 고대 히브리 문자(실로암 비문).",
