    "title": "바벨론 벨사살 왕이 다니엘에게 '둘째'가 아닌 '셋째 통치자'(단 5:29) 자리를 준 이유 — 나보니두스 원통 비문!",
    "origTitle": "Belshazzar the Co-Regent & the Third Ruler in the Kingdom",
    "scriptures": "단 5:7; 5:16; 5:29",
    "hook": "왜 바벨론의 벨사살 왕은 손글씨를 해석한 다니엘에게 2인자가 아닌 '나라의 셋째 통치자' 자리를 주었을까?",
    "visualGuide": "분벽의 손글씨 현장과 대영박물관 소장 나보니두스 원통 비문(제1왕 나보니두스·제2섭정왕 벨사살·제3통치자 다니엘)",
    "dossierMd": "■ B014 | 왜 바벨론의 벨사살 왕은 손글씨를 해석한 다니엘에게 '둘째'가 아니라 '셋째 통치자' 자리를 주었을까?\n• 분류: 구약 · 07_포로시대 | 테마: T06_역사·고고학\n• 핵심 성경 본문: 다니엘 5:7, 5:16, 5:29\n• 삼각 연동 코드: 인물 P025(다니엘), P268(벨사살) | 사건 E099(벨사살 왕의 연회와 메네 메네 데겔 우바르신)\n• 호기심 질문 (The Hook): \"애굽의 바로 왕은 요셉에게 '둘째 치리자(총리)' 자리를 주었는데, 왜 바벨론의 벨사살 왕은 다니엘에게 '나라의 셋째 통치자(단 5:7, 16, 29)'를 삼겠다고 세 번이나 반복했을까?\"\n• 표면적 읽기 vs 행간의 진짜 배경: 표면적 읽기: 1등은 왕이고 2등은 왕비라서 3등을 주었나 보다 하고 추측하거나, 과거 자유주의 비평가들은 바벨론 마지막 왕은 나보니두스인데 성경이 '벨사살'이라는 가공의 인물을 지어냈다고 공격했습니다.\n• 행간의 진실: 1854년 고대 우르(Ur) 유적지에서 발굴된 '나보니두스 원통 비문(Nabonidus Cylinder)'과 '나보니두스 연대기'가 발견되면서 2천 년간의 미스터리가 단번에 풀렸습니다! 신바벨론 제국의 마지막 정식 황제였던 나보니두스(Nabonidus)는 기원전 553년부터 아라비아 사막의 오아시스 도시 테마(Tema)로 원정을 떠나 10년 동안 수도 바벨론을 비우면서, 자신의 장남 벨사살(Bel-shar-usur)에게 왕권을 위임하여 '공동 섭정왕(Co-regent, 제2통치자)'으로 세웠던 것입니다!\n• 깊이 읽는 비하인드 스토리텔링: 즉, 기원전 539년 10월 바벨론 성이 무너지던 그날 밤, 바벨론 제국의 서열 1위는 부왕 나보니두스, 서열 2위는 수도 바벨론을 지키던 섭정왕 벨사살이었습니다. 그렇기 때문에 벨사살이 누군가에게 줄 수 있는 제국 내 최고 관직은 '둘째'가 아니라 '셋째 통치자(탈티 바으 마르쿠타, תַּלְתִּי בְּמַלְכוּתָא)'일 수밖에 없었던 것입니다!\n• 후대 역사가인 헤로도토스조차 잊어버렸던 바벨론 왕실의 이중 통치 구조를 다니엘서 5장은 정확히 세 번(7, 16, 29절)이나 '셋째 통치자'라는 단어로 기록하고 있었으며, 이는 다니엘서가 당시 바벨론 궁정 현장에 직접 있었던 목격자의 생생한 역사 기록임을 입증하는 결정적 고고학 증거가 되었습니다.\n• 구속사적 울림 & 『꿈바온』 한 줄 묵상:\n\"세상 제국의 1인자와 2인자가 성전 그릇으로 술을 마시며 교만을 떨던 그 밤에도, 역사의 저울('데겔')을 쥐신 진짜 통치자는 오직 하나님 한 분이셨습니다.\"\n• 시각 고증 및 장면 가이드: 바벨론 궁전 촛대 맞은편 분벽에 손가락이 나타나 메네 메네 데겔 우바르신을 쓰는 장면과, 대영박물관 소장 '나보니두스 원통 비문' 및 제1왕 나보니두스 → 제2왕 벨사살 → 제3통치자 다니엘 서열 인포그래픽.",
