    "hook": "성격 급한 하만이 1월에 유대인 학살 주사위(부르)를 던졌는데 왜 하필 11개월 뒤인 12월 13일이 뽑혔을까?",
    "visualGuide": "고대 페르시아 정육면체 점토 주사위(부르 Pur)와 11개월의 골든타임 동안 펼쳐진 에스더·모르드개의 구원 타임라인",
    "dossierMd": "■ B015 | 왜 하만은 유대인 학살 날짜를 뽑을 때 '제비(부르)'를 뽑았고, 그 11개월의 시차가 어떻게 구원이 되었을까?\n• 분류: 구약 · 08_포로귀환시대 | 테마: T02_문화·관습 · T08_구속사·모형\n• 핵심 성경 본문: 에스더 3:7, 9:24~26 (참조: 잠언 16:33)\n• 삼각 연동 코드: 인물 P117(에스더), P118(모르드개), P119(하만) | 사건 E023(에스더의 죽으면 죽으리이다와 부림절 구원)\n• 호기심 질문 (The Hook): \"성격 급한 권력자 하만이 당장 유대인을 죽이지 않고 왜 1월(니산월)에 주사위(부르)를 던져 하필 11개월 뒤인 12월(아달월)을 거사일로 잡았을까?\"\n• 표면적 읽기 vs 행간의 진짜 배경: 표면적 읽기: 행정 준비 기간이 필요해서 연말로 날짜를 잡았나 보다 하고 넘어갑니다.\n• 행간의 진실: 고대 메소포타미아와 페르시아 귀족들은 중대한 거사를 앞두고 점성술사들을 불러 정육면체 점술 주사위인 '부르(Pur, 아카드어 푸루 puru — 돌/주사위)'를 던져 길일(吉日)을 택했습니다. 하만은 아하수에로 왕 제12년 첫째 달(니산월, 3~4월경)에 주사위를 던지기 시작했는데, 공교롭게도 주사위가 한 해의 가장 마지막 달인 열두째 달(아달월) 13일에 떨어졌습니다!\n• 깊이 읽는 비하인드 스토리텔링: 만약 주사위가 첫째 달이나 둘째 달로 나왔다면, 인도와 구스까지 127지방에 흩어진 유대인들은 에스더가 왕 앞에 나아가 손을 써보기도 전에 속수무책으로 전멸당했을 것입니다. 그러나 잠언 16장 33절 말씀대로 \"제비는 사람이 뽑으나 모든 일을 작정하기는 여호와께 있느니라\"였습니다!\n• 하만이 미신적인 주사위('부르')를 던졌을 때, 보이지 않는 하나님의 손이 그 주사위를 가장 먼 11개월 뒤(12월 13일)로 굴려 놓으셨고, 바로 그 11개월의 골든타임 동안 에스더의 3일 금식기도, 왕의 잠 못 이루는 밤과 역대 일기책 낭독, 하만의 몰락, 그리고 모르드개의 반격 조서 발송이 완벽하게 이루어졌습니다! 유대인들이 구원의 날을 '부림절(Purim, 주사위들의 날)'이라 부른 것은 \"원수가 우리를 죽이려고 던진 운명의 주사위(부르)를 하나님께서 구원의 시간표로 뒤집으셨다\"는 찬양의 고백이었습니다.\n• 구속사적 울림 & 『꿈바온』 한 줄 묵상:\n\"세상은 우연의 주사위를 던지지만, 그 주사위가 멈추는 자리와 시간표를 주관하시는 분은 졸지도 주무시지도 않는 우리의 하나님이십니다.\"\n• 시각 고증 및 장면 가이드: 수산궁 어두운 방에서 점성술 주사위(고대 아카드식 점토 주사위 Pur)를 던지는 하만과, 창밖 별빛 아래 금식하며 기도하는 에스더, 그리고 왕의 잠 못 이루는 밤에 펼쳐진 역대 일기책 두루마리.",
