    "hook": "왜 천사가 '강보에 싸여 구유에 뉘어 있는 아기'를 표적이라 했을 때 베들레헴 목자들은 주소도 묻지 않고 단번에 찾아갔을까?",
    "visualGuide": "베들레헴 석회암 동굴의 파낸 돌 구유 안에 성전 제사용 어린양처럼 세마포 강보로 감싸인 아기 예수님",
    "dossierMd": "■ B016 | 천사가 베들레헴 목자들에게 알려준 표적 — 왜 하필 '강보에 싸여 구유에 뉘어 있는 아기'였을까?\n• 분류: 신약 · 10_예수그리스도공생애 | 테마: T02_문화·관습 · T08_구속사·모형\n• 핵심 성경 본문: 누가복음 2:8~16 (참조: 미가 4:8)\n• 삼각 연동 코드: 인물 P026(예수 그리스도), P142(마리아), P156(요셉), P304(베들레헴 목자들) | 사건 E024(예수 그리스도의 탄생과 목자들의 경배)\n• 호기심 질문 (The Hook): \"천사가 밤에 양 떼를 지키던 베들레헴 목자들에게 '너희가 강보에 싸여 구유에 뉘어 있는 아기를 보리니 이것이 너희에게 표적이니라(눅 2:12)'고 했을 때, 왜 목자들은 주소도 묻지 않고 단번에 찾아갔을까?\"\n• 표면적 읽기 vs 행간의 진짜 배경: 표면적 읽기: 여관에 방이 없어서 마구간 나무 여물통에 아기를 눕힌 가난하고 애처로운 성탄절 풍경으로만 생각합니다.\n• 행간의 진실: 유대 미쉬나(세겔림 7:4) 기록에 따르면, 예루살렘에서 남쪽으로 불과 8km 떨어진 베들레헴 들녘에는 예루살렘 성전에서 매일 아침저녁 상번제와 유월절 제사로 바쳐질 '흠 없는 제사용 어린양'들을 전문적으로 기르던 제사장 직속 목자들이 있었습니다. 그들이 양을 치던 베들레헴 북쪽 망대의 이름이 바로 미가 선지자가 예언한 '믹달 에델(Migdal Eder, 양 떼의 망대 — 미 4:8 \"양 떼의 망대여... 첫 권세가 네게로 오리니\")'이었습니다!\n• 깊이 읽는 비하인드 스토리텔링: 이 제사용 어린양을 돌보는 목자들은 어미 양이 출산할 때 망대 아래의 정결한 동굴 여물통(나무가 아니라 석회암을 파서 만든 돌 구유)으로 데려갔습니다. 그리고 갓 태어난 어린양이 발버둥 치다 돌에 부딪혀 상처가 나면 성전 제물로 쓸 수 없기 때문에(레 22:20 '흠 없는 양'), 태어나는 즉시 세마포 띠('강보')로 어린양의 몸을 단단히 감싸 돌 구유 안에 눕혀 보호했습니다!\n• 그러니 천사가 베들레헴 목자들에게 \"너희가 강보에 싸여 구유에 뉘어 있는 아기를 보리니 이것이 표적이니라\"라고 말했을 때, 목자들은 전율할 수밖에 없었습니다! 매일 밤 자신들이 성전 제물용 어린양을 강보에 싸서 돌 구유에 눕히던 바로 그 자리에, 세상 죄를 지고 가는 진짜 '하나님의 어린양'이 똑같이 강보에 싸여 돌 구유에 누워 계셨던 것입니다!\n• 구속사적 울림 & 『꿈바온』 한 줄 묵상:\n\"성전 제단에 오를 어린양처럼 강보에 싸여 차가운 돌 구유에 누우신 아기 예수님은, 태어나시는 첫 순간부터 우리를 위한 화목제물이셨습니다.\"\n• 시각 고증 및 장면 가이드: 서양식 나무 외양간이 아닌 1세기 유대 베들레헴의 석회암 동굴과 정교하게 파낸 돌 구유(Manger), 그 안에 세마포 강보로 감싸인 아기 예수님과 무릎 꿇은 목자들.",
