    "dossierMd": "■ B017 | 왜 세례 요한은 광야에서 하필 '메뚜기와 석청'을 먹고 낙타털 옷을 입었을까?\n• 분류: 신약 · 10_예수그리스도공생애 | 테마: T04_사물·생활사 · T02_문화·관습\n• 핵심 성경 본문: 마태복음 3:4, 마가복음 1:6 (참조: 열왕기하 1:8, 레위기 11:22)\n• 삼각 연동 코드: 인물 P027(세례 요한), P023(엘리야) | 사건 E123(세례 요한의 광야 외침과 예수님의 수세)\n• 호기심 질문 (The Hook): \"제사장 사가랴의 외아들로 태어나 성전에서 편히 먹고살 수 있었던 세례 요한은, 왜 유대 율법상 가장 역설적인 '메뚜기와 석청'을 주식으로 삼았을까?\"\n• 표면적 읽기 vs 행간의 진짜 배경: 표면적 읽기: 돈이 없어서 광야에서 아무거나 주워 먹는 극빈자나 기인(奇人)의 식단으로 오해하기 쉽습니다.\n• 행간의 진실: 첫째, 그가 입은 '낙타털 옷과 허리의 가죽띠'(마 3:4)는 구약 열왕기하 1장 8절이 묘사한 선지자 엘리야의 상징 복식(\"그는 털이 많은 사람인데 허리에 가죽띠를 띠었더이다\") 그대로였습니다. 즉, 옷차림 자체가 \"말라기 4장 5절이 예언한 '주의 길을 예비하는 엘리야'가 바로 나다\"라는 시각적 선포였습니다.\n• 깊이 읽는 비하인드 스토리텔링: 둘째, '메뚜기(아크리스)'와 '석청(야생 벌꿀, 멜리 아그리온)'은 당시 부패한 예루살렘 성전 귀족들의 사치스러운 식탁을 거부하고, 인간의 손이나 부정한 거래가 전혀 닿지 않는 광야의 '최고 정결식(Kosher)'을 택한 나실인의 결단이었습니다.\n• 레위기 11장 21~22절에서 곤충 중 유일하게 정결하여 먹어도 된다고 허락된 것이 '뛰는 다리가 있는 메뚜기 종류'였으며, 유대 광야 바위틈에서 채취하는 야생 꿀(석청)은 광야에서 하나님이 직접 공급하시는 천연 양식(신 32:13 \"반석에서 꿀을 빨게 하시며\")이었습니다. 제사장 가문의 특권을 스스로 버리고 광야에서 오직 하나님이 주시는 순전한 양식만 먹으며 외친 요한의 삶이 있었기에, 그의 \"회개하라!\"는 외침 앞에는 헤롯 왕도, 바리새인도, 세리와 군인들도 가슴을 치며 무릎을 꿇었습니다.\n• 구속사적 울림 & 『꿈바온』 한 줄 묵상:\n\"세상의 화려한 식탁을 내려놓고 광야의 정결함을 택한 한 사람의 목소리가, 주님이 걸어오실 곧은 길을 닦았습니다.\"\n• 시각 고증 및 장면 가이드: 유대 광야 요단강 가, 거친 낙타털 외투에 넓은 가죽띠를 묶은 세례 요한과 바위틈의 야생 벌집(석청).",
