    "hook": "왜 예수님은 마당 구석에 놓인 '정결 예식용 석회암 돌항아리 여섯 개'에 아구까지 물을 채우라고 하셨을까?",
    "visualGuide": "1세기 유대 고고학 유물 형태의 흰 석회암 통돌 항아리 6개(율법의 불완전수 6)에 가득 채워진 물이 붉은 새 포도주로 변하는 장면",
    "dossierMd": "■ B018 | 가나 혼인 잔치의 '돌항아리 여섯 개' — 왜 물이 포도주로 변한 첫 표적에 하필 '유대인의 정결 예식용 돌항아리'가 쓰였을까?\n• 분류: 신약 · 10_예수그리스도공생애 | 테마: T04_사물·생활사 · T08_구속사·모형\n• 핵심 성경 본문: 요한복음 2:1~11\n• 삼각 연동 코드: 인물 P026(예수 그리스도), P142(마리아) | 사건 E025(가나 혼인 잔치의 첫 표적)\n• 호기심 질문 (The Hook): \"예수님은 빈 포도주 가죽 부대에 바로 포도주를 채워주실 수도 있었는데, 왜 마당 구석에 놓인 '정결 예식용 돌항아리 여섯 개'에 아구까지 물을 채우라고 하셨을까?\"\n• 표면적 읽기 vs 행간의 진짜 배경: 표면적 읽기: 잔칫집에 물 담을 큰 그릇이 그것밖에 없어서 임시로 사용하셨다고 생각합니다.\n• 행간의 진실: 1세기 유대인들은 토기(흙그릇)는 부정한 것이 닿으면 부정해져서 깨뜨려야 하지만(레 11:33), 석회암 통돌을 깎아 만든 '돌항아리(칼랄, Kallal)'는 율법상 절대 부정해지지 않는다고 믿어 손을 씻는 정결 예식용으로만 썼습니다(예루살렘 구시가지 고고학 발굴에서도 1세기 유대 귀족 가옥마다 이 석회암 돌항아리가 출토됨).\n• 깊이 읽는 비하인드 스토리텔링: 요한복음 2장 6절은 이 돌항아리가 '유대인의 정결 예식을 따라 두세 통(약 80~120리터) 드는 돌항아리 여섯 개'라고 콕 집어 기록합니다. 성경에서 숫자 '6'은 완전수 '7'에서 하나가 모자란 인간의 수고와 율법의 불완전함을 상징합니다. 손발의 겉모습만 씻어낼 뿐 영혼의 죄와 기쁨의 고갈을 해결하지 못한 채 텅 비어 있던 유대 율법주의의 차가운 돌항아리 6개!\n• 그곳에 일곱 번째 완전수로 오신 예수님께서 \"아구까지(끝까지, 헤오스 아노)\" 물을 채우라 하셨을 때, 율법의 맹물이 복음과 성령의 기쁨을 상징하는 최상급 새 포도주(약 600리터 이상!)로 변했습니다! 이는 겉만 씻는 옛 언약(돌판의 율법)의 시대가 끝나고, 그리스도의 피로 속사람을 새롭게 하는 새 언약의 혼인 잔치가 시작되었음을 알리는 첫 표적(세메이온)이었습니다.\n• 구속사적 울림 & 『꿈바온』 한 줄 묵상:\n\"인간의 기쁨이 바닥난 자리에서, 주님은 율법의 차가운 돌항아리를 은혜의 새 포도주로 아구까지 채우십니다.\"\n• 시각 고증 및 장면 가이드: 1세기 유대 고고학 유물 형태의 깎아 만든 흰 석회암 돌항아리 6개에 하인들이 아구까지 물을 붓고, 바가지로 떠낼 때 붉고 향기로운 포도주로 빛나는 장면.",
