    "hook": "왜 의사 누가는 베드로 장모의 열병을 고치실 때 바람과 바다와 귀신을 잠잠케 하신 동사 '꾸짖으시니'를 사용했을까?",
    "visualGuide": "침상 머리맡에 우뚝 서셔서 열병을 꾸짖으시는 예수님과 그 즉시 일어나 수종드는 베드로의 장모",
    "dossierMd": "■ B019 | 왜 예수님은 베드로의 장모가 앓던 열병을 고치실 때, 귀신을 쫓아낼 때 쓰는 단어 '꾸짖으시니(에피티마오)'를 쓰셨을까?\n• 분류: 신약 · 10_예수그리스도공생애 | 테마: T01_원어·언어유희\n• 핵심 성경 본문: 누가복음 4:38~39 (참조: 누가복음 4:35, 8:24)\n• 삼각 연동 코드: 인물 P026(예수 그리스도), P029(베드로) | 사건 E128(가버나움 안식일 귀신 축사와 베드로 장모 치유)\n• 호기심 질문 (The Hook): \"의사였던 누가는 베드로 장모의 열병 치유를 기록하면서 왜 일반 치료 동사가 아니라, 바람과 바다와 귀신을 잠잠케 할 때 쓰는 권위 있는 명령어 '꾸짖으시니(에피티마오)'를 사용했을까?\"\n• 표면적 읽기 vs 행간의 진짜 배경: 표면적 읽기: 예수님이 열이 빨리 내리도록 기도해 주셨다는 일반적인 병 고침 이야기로 읽습니다.\n• 행간의 진실: 누가복음의 저자 누가는 당대 헬라 의학 용어에 정통한 의사(골 4:14)였습니다. 마태와 마가는 그냥 '열병(퓌레토스)'이라고만 적었지만, 의사 누가는 당시 고대 의학(갈레노스 학파)의 중증 분류 용어인 '큰 열병(퓌레토 메갈로, πυρετῷ μεγάλῳ — 갈릴리 습지대의 치명적인 말라리아성 고열)'(눅 4:38)이라고 정확히 진단명을 기록했습니다!\n• 깊이 읽는 비하인드 스토리텔링: 더 놀라운 점은 39절입니다. \"예수께서 가까이 서서 열병을 꾸짖으시니(에페티메센, ἐπετίμησεν — 원형 에피티마오) 병이 떠나고...\"\n• 바로 직전 가버나움 회당에서 더러운 귀신을 향해 '꾸짖어(에페티메센)'(눅 4:35) 쫓아내셨고, 훗날 갈릴리 호수의 광풍을 향해 '꾸짖으시매(에페티메센)'(눅 8:24) 잠잠케 하셨던 똑같은 단어를 열병에게 쓰신 것입니다! 또한 '가까이 서서(에피스타스)'는 주인이 종 위에 우뚝 서서 명령하는 자세를 뜻합니다. 창조주이신 예수님 앞에서는 귀신도, 폭풍도, 죽음의 질병도 감히 하나님의 자녀를 괴롭히지 못하고 즉시 물러가야 하는 피조물에 불과함을 보여주신 것입니다. 열병이 물러가자 보통 사람은 며칠간 탈진해 누워 있어야 하지만, 베드로의 장모는 그 즉시 일어나('파라크레마') 예수님과 제자들을 수종들기까지 온전히 회복되었습니다.\n• 구속사적 울림 & 『꿈바온』 한 줄 묵상:\n\"우리를 쓰러뜨리는 인생의 큰 열병과 풍랑 위로 주님이 가까이 서서 한 말씀만 꾸짖으시면, 즉시 평안과 섬김의 힘이 찾아옵니다.\"\n• 시각 고증 및 장면 가이드: 가버나움 현무암 가옥 안, 침상 머리맡에 우뚝 서셔서 손을 내밀어 명령하시는 예수님과 즉시 밝은 얼굴로 일어나는 베드로의 장모.",
