    "hook": "왜 강도 만난 자는 '예루살렘에서 여리고로 내려가다가' 습격을 당했으며 왜 하필 제사장과 레위인이 그 길을 지나가고 있었을까?",
    "visualGuide": "해발 +760m 예루살렘에서 -250m 여리고(사제 거주 도시)로 급강하하는 붉은 바위 협곡 '아둠밈 비탈길'에서 상처에 기름과 포도주를 붓는 사마리아인",
    "dossierMd": "■ B020 | 왜 선한 사마리아인 비유 속 강도 만난 자는 '예루살렘에서 여리고로 내려가는 길'에서 습격을 당했을까?\n• 분류: 신약 · 10_예수그리스도공생애 | 테마: T05_지리·생태 · T02_문화·관습\n• 핵심 성경 본문: 누가복음 10:30~37\n• 삼각 연동 코드: 인물 P026(예수 그리스도) | 사건 E146(선한 사마리아인의 비유)\n• 호기심 질문 (The Hook): \"예수님이 비유를 시작하시며 말씀하신 '예루살렘에서 여리고로 내려가다가'라는 한마디에 왜 당시 청중들은 설명을 듣기도 전에 고개를 끄덕이며 긴장했을까?\"\n• 표면적 읽기 vs 행간의 진짜 배경: 표면적 읽기: 예수님이 비유를 위해 지어내신 가상의 길 이름 정도로 생각하기 쉽습니다.\n• 행간의 진실: 예루살렘(해발 +760m)에서 여리고(해수면 아래 -250m)로 가는 길은 직선거리 약 27km 사이에 무려 표고차 1,000m 이상이 급격히 떨어지는 험준한 유대 광야 협곡 길입니다! 그래서 성경은 언제나 예루살렘에서 여리고로 갈 때 '내려가다(카타바이노)'라고 표현합니다.\n• 깊이 읽는 비하인드 스토리텔링: 특히 이 길의 중간 고개는 산화철 성분이 섞인 붉은 바위와 피비린내 나는 강도 사건 때문에 구약 여호수아 15장 7절 때부터 '아둠밈 비탈길(Ma'ale Adummim — 피의 고개)'이라 불렸습니다. 좁은 와디(건천) 협곡 양옆으로 수많은 석회암 동굴이 뚫려 있어 강도떼가 숨어 있다가 행인을 덮치기에 최적의 지형이었습니다.\n• 게다가 여리고는 당대 예루살렘 성전에서 봉사하는 제사장과 레위인 수천 명이 교대 근무(반차)가 끝나면 내려가 쉬던 대표적 사제 거주 도시(종려나무 성읍)였습니다! 즉, 성전에서 거룩하게 예배를 집전하고 여리고 자택으로 퇴근하던 제사장과 레위인이, 피 흘리며 죽어가는 동족을 보고 시체에 닿아 정결 규례가 깨질까 봐(레 21:1) 길 건너편으로 피해 지나갔다는 예수님의 묘사는 당시 종교 지도자들의 위선을 찌르는 가장 현실적인 현장이었습니다. 반면 유대인들이 상종도 않던 사마리아인은 자기가 마실 포도주(알코올 소독)와 감람유(진정 연고)를 상처에 붓고 자기 짐승에 태워 주막까지 데려간 참된 이웃(그리스도의 자기희생)을 보여주었습니다.\n• 구속사적 울림 & 『꿈바온』 한 줄 묵상:\n\"율법과 체면은 강도 만난 죄인을 피하여 지나갔으나, 참된 선한 사마리아인이신 예수님은 피의 고개로 찾아와 자신의 생명과 기름을 부어 살리셨습니다.\"\n• 시각 고증 및 장면 가이드: 붉은 바위 절벽이 깎아지른 유대 광야 '아둠밈 비탈길', 멀리 피하여 내려가는 제사장·레위인과 달리 나귀에서 내려와 다친 사람의 상처에 기름과 포도주를 붓는 사마리아인.",
