    "title": "탕자의 아버지가 옷자락을 걷어 올리고 마을 어귀로 전력 질주한 이유 — 유대 마을의 항아리 깨기 추방 의식 '케자자(Kezazah)'!",
    "origTitle": "The Running Father & the Jewish Kezazah Ceremony at the Village Gate",
    "scriptures": "눅 15:20~24",
    "hook": "왜 고대 가부장 아버지는 맨다리가 드러나는 수치를 무릅쓰고 동네 사람들보다 먼저 아들에게 달려가 목을 끌어안았을까?",
    "visualGuide": "마을 사람들이 정죄의 토기 항아리(케자자)를 깨뜨리기 전에 긴 겉옷을 걷어쥐고 맨발로 달려가 아들을 품에 안는 아버지",
    "dossierMd": "■ B021 | 왜 탕자의 아버지는 동네 어귀에서 '옷자락을 걷어 올리고' 아들에게 달려가 목을 안았을까? — '케자자(Kezazah)' 의식의 비밀\n• 분류: 신약 · 10_예수그리스도공생애 | 테마: T02_문화·관습 · T08_구속사·모형\n• 핵심 성경 본문: 누가복음 15:20~24\n• 삼각 연동 코드: 인물 P026(예수 그리스도) | 사건 E148(돌아온 탕자와 아버지의 사랑 비유)\n• 호기심 질문 (The Hook): \"고대 중동에서 나이 든 가부장이 맨다리를 드러내며 달리는 것은 극도의 수치였는데, 왜 아버지는 체면을 버리고 마을 사람들보다 먼저 아들에게 전력 질주했을까?\"\n• 표면적 읽기 vs 행간의 진짜 배경: 표면적 읽기: 아들이 너무 보고 싶고 반가워서 한시라도 빨리 안아주려고 뛰어가셨다는 감정적 장면으로만 읽습니다.\n• 행간의 진실: 물론 아버지의 뜨거운 사랑이지만, 1세기 유대 마을 공동체의 무서운 관습이었던 '케자자(Kezazah, קְצָצָה — 단절/절교 의식)'를 알면 아버지가 왜 목숨 걸고 뛰었는지 눈물 없이 볼 수 없습니다!\n• 깊이 읽는 비하인드 스토리텔링: 당시 유대 사회에서 부모가 살아 있는데 유산을 미리 달라고 요구하는 것(눅 15:12)은 \"아버지, 빨리 죽으십시오\"라는 패륜과 같았습니다. 더구나 유대인이 물려받은 가문의 땅을 팔아 이방인들에게 가서 탕진하고(돼지 치는 곳까지 추락) 빈털터리로 돌아오면, 마을 장로들과 동네 사람들은 마을 입구에 모여 볶은 곡식을 담은 큰 토기 항아리를 그 아들의 발 앞에 패대기쳐 깨뜨리며 \"아무개는 우리 백성에게서 영원히 끊어졌다(케자자)!\"라고 외치고 침을 뱉어 마을에서 영구 추방했습니다.\n• 거지꼴이 된 둘째 아들이 맨발(종이나 죄인의 상징)로 마을 어귀에 나타났을 때, 만약 마을 사람들이 먼저 아들을 발견하면 아들은 돌과 조롱을 맞고 영원히 쫓겨날 판이었습니다. 그래서 매일 마을 입구를 바라보던 아버지는 아들의 그림자가 보이자마자, 마을 사람들이 항아리를 들고나와 아들을 정죄하기 전에 먼저 아들을 감싸 안으려고 긴 겉옷 자락을 허리춤에 걷어 올리고 맨다리가 드러나는 수치를 감수한 채 전력 질주한 것입니다!\n• 아버지가 아들의 목을 끌어안고 입을 맞추며 제일 먼저 \"제일 좋은 옷(아버지의 예복)과 손가락 가락지와 발에 신(자유인 아들의 신분)\"을 입히라 명령하자, 뒤따라 나온 마을 사람들은 감히 항아리를 깨뜨릴 수 없었습니다. 아들이 받아야 할 마을 어귀의 수치(케자자)를 아버지가 달리기와 포옹으로 대신 덮어버리신 것입니다!\n• 구속사적 울림 & 『꿈바온』 한 줄 묵상:\n\"율법과 세상이 정죄의 항아리를 깨뜨리기 전에, 하나님 아버지는 십자가에서 수치를 무릅쓰고 달려와 나를 먼저 품에 안으셨습니다.\"\n• 시각 고증 및 장면 가이드: 유대 마을 돌담 어귀, 남루한 아들을 향해 긴 겉옷 자락을 걷어쥐고 맨발로 달려가 품에 안는 백발의 아버지와, 뒤편에서 멈춰 선 마을 사람들.",
