    "hook": "왜 부활하신 예수님은 갈릴리 새벽 바닷가에서 장작불이 아닌 '숯불(안트라키아)'을 피워놓고 베드로를 기다리셨을까?",
    "visualGuide": "대제사장 뜰의 배신의 숯불(요 18:18)과 디베랴 새벽 해변에서 생선과 떡을 구우며 상처를 치유하시는 사랑의 숯불(요 21:9) 대조",
    "dossierMd": "■ B022 | 왜 요한복음 전체에서 '숯불(안트라키아)'이라는 단어는 베드로의 배신과 회복 단 두 장면에서만 등장할까?\n• 분류: 신약 · 10_예수그리스도공생애 | 테마: T01_원어·언어유희 · T03_행간·인물관계\n• 핵심 성경 본문: 요한복음 18:18, 21:9, 21:15~17\n• 삼각 연동 코드: 인물 P029(베드로), P026(예수 그리스도), P122(사도 요한) | 사건 E154(겟세마네 체포와 베드로의 세 번 부인), E157(디베랴 바닷가 153마리 만선과 베드로의 회복)\n• 호기심 질문 (The Hook): \"심리학에서 특정 냄새가 과거의 강렬한 기억을 소환하는 현상을 '프루스트 효과'라고 하는데, 왜 예수님은 부활 후 갈릴리 바닷가에서 장작불이 아닌 '숯불(안트라키아)'을 피워놓고 베드로를 기다리셨을까?\"\n• 표면적 읽기 vs 행간의 진짜 배경: 표면적 읽기: 해변에서 생선을 구우려고 불을 피우셨다는 일상적인 조반 준비 장면으로 읽습니다.\n• 행간의 진실: 신약성경 전체(요한복음 포함)에서 헬라어 '안트라키아(ἀνθρακιά, 숯불)'라는 단어는 오직 딱 두 번만 등장합니다!\n1. 요한복음 18장 18절: 대제사장 안나스·가야바의 관정 뜰에서 종들과 아랫사람들이 추위를 피하려 피워놓은 '숯불(안트라키아)' — 베드로가 그 숯불을 쬐며 예수님을 세 번 저주하며 부인했던 실패의 현장입니다.\n2. 요한복음 21장 9절: 부활하신 예수님이 디베랴 바닷가 새벽 해변에 친히 피워놓으신 '숯불(안트라키아)' — 베드로에게 \"네가 나를 사랑하느냐\" 세 번 물으시며 사명을 회복시키신 은혜의 현장입니다!\n• 깊이 읽는 비하인드 스토리텔링: 새벽 고기잡이를 마치고 해변으로 헤엄쳐 나온 베드로의 코끝에 매캐하고도 익숙한 '숯불 냄새'가 스쳤을 때, 베드로의 가슴은 덜컥 내려앉았을 것입니다. 불과 며칠 전 대제사장의 뜰에서 그 숯불 냄새를 맡으며 주님을 모른다고 세 번 부인하고 통곡했던 트라우마의 현장이었기 때문입니다.\n• 그러나 예수님은 그 실패의 기억을 덮어두고 모른 척하신 것이 아니라, 베드로가 무너졌던 바로 그 '숯불(안트라키아)'을 다시 피우시고, 그 위에서 따뜻한 생선과 떡으로 아침상을 차려 먹이신 뒤, 세 번의 부인을 세 번의 사랑 고백(\"주님, 내가 주님을 사랑하는 줄 주께서 아시나이다\")으로 완전히 덮어 치유해 주셨습니다. 주님은 우리의 실패의 냄새가 배어 있는 상처의 자리를 사명의 자리로 바꾸시는 분입니다.\n• 구속사적 울림 & 『꿈바온』 한 줄 묵상:\n\"내가 주님을 부인하던 차가운 밤의 숯불을, 주님은 새벽 바닷가에서 나를 먹이시고 다시 세우시는 사랑의 숯불로 바꾸어 놓으셨습니다.\"\n• 시각 고증 및 장면 가이드: 대제사장 뜰의 어두운 숯불(요 18:18)과 디베랴 새벽 해변에서 생선과 떡이 구워지는 따뜻한 숯불(요 21:9)이 대조되며 예수님과 눈을 맞추는 베드로.",
