    "hook": "왜 사도 요한은 십자가 아래서 예수님의 속옷이 '바늘로 꿰매지 않고 위에서부터 통으로 짠 옷'임을 그토록 강조했을까?",
    "visualGuide": "절대 찢어지지 않도록 한 통으로 직조된 영원한 대제사장의 속옷(키톤)과 위로부터 아래까지 둘로 찢어진 성전 휘장의 대비",
    "dossierMd": "■ B023 | 왜 로마 군병들은 예수님의 겉옷은 네 조각으로 찢어 나누면서, 속옷('키톤')은 찢지 않고 제비를 뽑았을까?\n• 분류: 신약 · 10_예수그리스도공생애 | 테마: T04_사물·생활사 · T08_구속사·모형\n• 핵심 성경 본문: 요한복음 19:23~24 (참조: 출애굽기 28:31~32, 레위기 21:10, 시편 22:18)\n• 삼각 연동 코드: 인물 P026(예수 그리스도), P122(사도 요한) | 사건 E027(예수 그리스도의 십자가 대속과 부활)\n• 호기심 질문 (The Hook): \"십자가 아래 있던 사도 요한은 왜 예수님의 속옷이 '호지 아니하고 위에서부터 통으로 짠 것'이라는 바느질 방식까지 그렇게 자세히 기록했을까?\"\n• 표면적 읽기 vs 행간의 진짜 배경: 표면적 읽기: 어머니 마리아가 정성껏 통짜로 짜준 좋은 옷이라서 군인들이 찢기 아까워 제비를 뽑았다고만 생각합니다.\n• 행간의 진실: 첫째는 다윗이 1천 년 전에 예언한 시편 22편 18절(\"그들이 내 겉옷을 나누며 내 속옷을 제비 뽑나이다\")의 문자적 성취입니다(겉옷 히마티아는 실제로 네 조각으로 찢어 나눴고, 속옷 키톤만 제비를 뽑음!). 둘째는 대제사장의 거룩한 예복 규례와의 놀라운 일치입니다!\n• 깊이 읽는 비하인드 스토리텔링: 일반 유대인의 속옷(키톤)은 앞판과 뒤판 두 폭의 천을 어깨와 옆구리에서 바늘로 꿰매어(호아서) 만듭니다. 그러나 유대 역사가 요세푸스(『유대고대사』 3.7.4)의 증언과 출애굽기 28장 32절에 따르면, 오직 이스라엘 대제사장이 입는 에봇 받침 겉옷과 속옷만은 바늘로 꿰맨 솔기(이음매)가 전혀 없이 목 부분부터 발끝까지 한 통으로 직조(통으로 짠 옷)하여, 절대 찢어지지 않도록 제작되었습니다!\n• 또한 레위기 21장 10절은 \"대제사장은 어떤 슬픔이나 상황에서도 자기의 옷을 찢지 말라\"고 엄격히 명령했습니다(가야바는 예수님을 심문하며 분노에 차 자기 옷을 찢음으로 대제사장 자격을 스스로 상실함 — 마 26:65). 반면 십자가에 달리신 참된 영원한 대제사장 예수 그리스도의 속옷은 솔기 없이 위에서부터 통으로 짠 옷이었기에 로마 군병들의 손에 의해서도 끝내 찢어지지 않았고, 그 대신 성전의 휘장이 위로부터 아래까지 둘로 찢어졌습니다(마 27:51)!\n• 구속사적 울림 & 『꿈바온』 한 줄 묵상:\n\"찢어지지 않는 통으로 짠 대제사장의 옷을 입으셨던 주님은, 십자가에서 자신의 육체라는 휘장을 찢으사 우리가 하나님께 나아갈 새롭고 산 길을 여셨습니다.\"\n• 시각 고증 및 장면 가이드: 골고다 십자가 아래 이음매 없이 위에서부터 한 통으로 짠 흰 세마포 속옷(키톤)과, 같은 시각 예루살렘 성전에서 위에서 아래로 찢어지는 굵은 청색·자색·홍색 휘장의 대조.",
