    "hook": "왜 예수님은 못 박히실 때 준 몰약 탄 포도주는 거절하시고 운명 직전 우슬초에 꿴 신 포도주는 받으신 후 '다 이루었다(테텔레스타이)' 외치셨을까?",
    "visualGuide": "출애굽 유월절 어린양 피를 발랐던 우슬초 줄기 끝에 매달린 해면과 헬라어 완불 도장 '테텔레스타이(다 이루었다)'",
    "dossierMd": "■ B024 | 예수님이 십자가에서 '내가 목마르다' 하셨을 때, 왜 신 포도주를 적신 해면을 '우슬초(히쏘포)'에 꿰어 올렸을까?\n• 분류: 신약 · 10_예수그리스도공생애 | 테마: T04_사물·생활사 · T08_구속사·모형\n• 핵심 성경 본문: 요한복음 19:28~30 (참조: 마태복음 27:34, 출애굽기 12:22)\n• 삼각 연동 코드: 인물 P026(예수 그리스도) | 사건 E027(예수 그리스도의 십자가 대속과 부활)\n• 호기심 질문 (The Hook): \"예수님은 십자가에 못 박히실 때 군병들이 준 '몰약(쓸개) 탄 포도주'는 한 모금도 마시지 않고 거절하셨는데(마 27:34), 왜 운명하시기 직전에는 우슬초에 꿴 '신 포도주'를 받으신 후 '다 이루었다!' 외치셨을까?\"\n• 표면적 읽기 vs 행간의 진짜 배경: 표면적 읽기: 처음엔 안 마시려다가 나중에 너무 목이 말라서 마셨다고 오해하거나, 풀 줄기인 우슬초로 어떻게 해면을 들어 올렸냐며 성경의 오류라고 의심하기도 합니다.\n• 행간의 진실: 십자가 위에서 건네진 두 번의 포도주는 목적과 성분이 완전히 다릅니다!\n1. 첫 번째 포도주(마 27:34; 막 15:23, 못 박히실 때): 고통을 마비시키는 마취제인 '몰약(쓸개즙)을 탄 포도주'였습니다. 예수님은 인류의 죄 값을 치르는 십자가의 고통을 마취제로 흐리지 않고 맨정신으로 온전히 다 감당하시기 위해 이를 거절하셨습니다!\n2. 두 번째 포도주(요 19:29~30, 운명 직전): 로마 군병들이 갈증 해소용으로 마시던 값싼 식초 섞인 물인 '포스카(Posca, 신 포도주)'였습니다. 예수님은 모든 구속 사역을 마치신 뒤, 타들어 가는 성대를 적셔 온 세상이 듣도록 마지막 한마디 — \"테텔레스타이(Τετέλεσται, 다 이루었다 / 값을 완불했다)!\" — 를 똑똑히 선포하시기 위해 이 신 포도주를 받으셨습니다.\n• 깊이 읽는 비하인드 스토리텔링: 더욱 감격스러운 것은 사도 요한만 유일하게 기록한 '우슬초(휘쏘포스, ὕσσωπος)'(요 19:29)라는 단어입니다! 중동의 시리아 우슬초(Origanum syriacum)는 줄기가 목질화되어 50~90cm까지 단단하게 자라므로 로마 군인의 창대 끝에 묶어 해면을 올리기에 충분했습니다.\n• 무엇보다 구약 출애굽기 12장 22절, 첫 번째 유월절 밤에 어린양의 피를 인방과 문설주에 바를 때 썼던 도구가 바로 '우슬초 묶음'이었습니다! 출애굽의 유월절이 우슬초에 묻은 어린양의 피로 시작되었듯, 인류 구원의 진짜 유월절인 골고다 십자가의 구속 역시 유월절 양 잡는 시각(오후 3시)에 우슬초가 예수님의 입술에 닿으며 \"다 이루었다!\"로 완성된 것입니다.\n• 구속사적 울림 & 『꿈바온』 한 줄 묵상:\n\"고통을 덜어줄 마취의 잔은 거절하시고 구속을 선포할 마지막 한 모금만 받으신 주님의 '테텔레스타이'가 나의 모든 죄의 빚문서를 영원히 지웠습니다.\"\n• 시각 고증 및 장면 가이드: 우슬초 줄기 끝에 매달린 해면(스펀지)이 십자가 위 예수님의 입술에 닿는 클로즈업과, 그 위에 겹쳐지는 헬라어 완불 도장 문서 ΤΕΤΕΛΕΣΤΑΙ(다 이루었다).",
