    "title": "빈 무덤 속 가라앉은 세마포와 '한곳에 따로 개어 놓은 머릿수건(수다리온)'이 뜻하는 유대 식탁 관습('내가 곧 다시 오마!')",
    "origTitle": "The Folded Face Cloth (Soudarion) Left in a Separate Place in the Empty Tomb",
