    "hook": "왜 사도 요한은 빈 무덤 안에 들어가 '한곳에 따로 단정히 개어 놓은 머릿수건'만 보고도 그 자리에서 부활을 믿었을까?",
    "visualGuide": "고치처럼 그대로 주저앉은 세마포 옆에 주인이 곧 다시 돌아온다는 신호로 단정히 접혀 놓인 머릿수건(수다리온)",
    "dossierMd": "■ B025 | 부활 아침 빈 무덤 속에 남겨진 '세마포와 따로 개어 놓은 머릿수건'이 사도 요한을 단번에 믿게 한 이유\n• 분류: 신약 · 10_예수그리스도공생애 | 테마: T02_문화·관습 · T04_사물·생활사\n• 핵심 성경 본문: 요한복음 20:5~8 (참조: 요한복음 11:44)\n• 삼각 연동 코드: 인물 P026(예수 그리스도), P122(사도 요한), P029(베드로) | 사건 E156(부활 아침 빈 무덤과 막달라 마리아 만남)\n• 호기심 질문 (The Hook): \"사도 요한은 빈 무덤 안에 들어가 아직 부활하신 예수님을 직접 보지도 못한 상태에서, 단지 '놓인 세마포와 한곳에 따로 개어 놓은 머릿수건(수다리온)'만 보고 어떻게 그 자리에서 부활을 확신했을까(요 20:8)?\"\n• 표면적 읽기 vs 행간의 진짜 배경: 표면적 읽기: 시체 도둑이 훔쳐 갔다면 수의를 벗겨 놓고 갈 리가 없으니 도난이 아니라는 뜻으로만 이해합니다.\n• 행간의 진실: 원어와 1세기 유대 장례·식탁 문화를 보면 두 가지 결정적 증거가 들어 있습니다. 첫째, 유대 장례법은 시신에 몰약과 침향 백 근(약 34kg)을 바르며 세마포를 겹겹이 감쌉니다. 나사로가 살아났을 때는 세마포에 감긴 채로 걸어 나와서 예수님이 \"풀어 놓아 다니게 하라\"(요 11:44) 하셔야 했습니다. 그러나 예수님의 무덤 안 세마포는 누군가 풀거나 찢은 흔적 없이, 마치 나비가 고치를 빠져나간 것처럼 감싸인 모양 그대로 주저앉아(케이메나) 있었고, 얼굴을 감쌌던 머릿수건(수다리온)도 머리 위치 그대로 또렷이 말려(엔테튈리그메논) 있었습니다! 영광의 부활체가 세마포를 통과해 일어나신 것입니다.\n• 깊이 읽는 비하인드 스토리텔링: 둘째, 유대 가정의 식탁 관습에서 주인이 식사 도중 수건(냅킨, 수다리온)을 구겨서 식탁 위에 던져 놓으면 \"나는 식사를 완전히 끝냈으니 치워도 좋다\"는 신호였고, 반대로 수건을 단정하게 접어서(개어서) 식탁 한쪽에 놓아두면 하인들에게 \"나는 아직 식사가 끝난 것이 아니라 잠시 자리를 비운 것이니, 곧 다시 돌아올 것이다(I am coming back)!\"라는 무언의 메시지였습니다!\n• 무덤에 들어간 사도 요한은 주저앉은 세마포와 함께 단정히 개어 놓은 그 머릿수건(수다리온)을 보는 순간, \"주님이 죽음을 이기시고 부활하셨으며, 약속하신 대로 우리에게 반드시 다시 오신다!\"는 사실을 깨닫고 즉시 믿었던 것입니다(요 20:8 \"보고 믿더라\").\n• 구속사적 울림 & 『꿈바온』 한 줄 묵상:\n\"빈 무덤 돌판 위에 단정히 개어 놓으신 머릿수건은, 죽음을 이기신 주님께서 우리에게 남기신 '내가 반드시 다시 오마'라는 가장 확실한 약속입니다.\"\n• 시각 고증 및 장면 가이드: 새벽 햇살이 비쳐 드는 빈 돌무덤 안, 고치처럼 그대로 가라앉은 세마포 수의와 머리맡에 단정하게 접혀 놓인 머릿수건(수다리온), 그 앞에 서서 감격하는 사도 요한과 베드로.",
