    "hook": "왜 사울은 다메섹 회심 후 10년 넘게 '사울'이라 불리다가 구브로 총독 서기오 바울 앞에서부터 '바울'이라는 이름을 썼을까?",
    "visualGuide": "구브로 총독 관저에서 이방 선교를 위해 히브리 왕의 이름 '사울' 대신 로마식 이름 '바울(파울루스 — 작은 자)'을 택한 사도 바울",
    "dossierMd": "■ B026 | 왜 '사울(Saul)'은 1차 선교여행 중 구브로 총독 서기오 바울 앞에서 갑자기 '바울(Paul)'이라 불리기 시작했을까?\n• 분류: 신약 · 11_초대교회·선교 | 테마: T07_난제·오해교정 · T01_원어·언어유희\n• 핵심 성경 본문: 사도행전 13:7~9 (참조: 사도행전 22:25~28)\n• 삼각 연동 코드: 인물 P030(사도 바울), P156(바나바), P189(서기오 바울) | 사건 E167(바울과 바나바의 1차 선교여행 파송과 구브로 사역)\n• 호기심 질문 (The Hook): \"성도들이 가장 많이 오해하는 질문 — 사울은 다메섹에서 회심할 때 예수님이 '바울'로 이름을 바꿔주신 것일까? 아니면 원래 두 이름을 가지고 있었을까?\"\n• 표면적 읽기 vs 행간의 진짜 배경: 표면적 읽기: 아브람이 아브라함으로, 야곱이 이스라엘로 개명받았듯, 핍박자 '사울'이 회심한 뒤 하나님께 '바울'이라는 새 이름을 받았다고 흔히 설교하거나 오해합니다.\n• 행간의 진실: 성경 어디에도 하나님이나 예수님이 사울의 이름을 바울로 개명해 주셨다는 기록은 없습니다! 다메섹 회심(행 9장) 이후로도 무려 10년 넘게 사도행전 13장 8절까지는 계속 '사울'이라 불립니다. 그러다 사도행전 13장 9절에서 \"바울이라고도 하는 사울이(Saulos ho kai Paulos) 성령이 충만하여...\"라고 전환된 뒤 그 후로 '바울'이라 불립니다.\n• 깊이 읽는 비하인드 스토리텔링: 바울은 길리기아 수도 다소에서 태어날 때부터 로마 시민권(행 22:28)을 가진 유대인이었습니다. 당시 로마 시민권을 가진 디아스포라 유대인들은 유대 공동체 안에서 부르는 히브리식 본명(사울, Sha'ul — '하나님께 구함 받은 자', 베냐민 지파 초대 왕 사울의 이름)과, 헬라·로마 제국 사회에서 쓰는 라틴식 성명(코그노멘, 파울루스 Paulus / 바울 — '작은 자') 두 가지를 태어날 때부터 함께 가지고 있었습니다!\n• 유대 땅과 예루살렘에서 사역할 때(행 9~12장)는 유대식 이름인 '사울(큰 자, 왕의 이름)'을 썼으나, 사도행전 13장에서 구브로(키프로스) 섬의 로마 총독 서기오 바울 앞에서 복음을 전하며 본격적인 이방 세계 선교로 나아가는 순간부터, 유대인의 높은 벽을 허물고 이방인들에게 다가가기 위해 자신의 로마식 이름이자 '작은 자(Paulus)'라는 뜻의 '바울'을 공식 사역 이름으로 선택한 것입니다!\n• 구속사적 울림 & 『꿈바온』 한 줄 묵상:\n\"베냐민 지파의 자랑이던 '큰 자 사울'의 이름표를 내려놓고, 이방인 한 영혼을 얻기 위해 스스로 '작은 자 바울'이 된 낮아짐에서 세계 선교의 문이 열렸습니다.\"\n• 시각 고증 및 장면 가이드: 구브로 바보의 로마 총독 관저, 총독 서기오 바울 앞에서 성령 충만하여 복음을 전하는 바울(Saulos — 히브리명 / Paulus — 로마명 '작은 자' 비교 카드).",
