    "hook": "신들의 도시 아테네 한복판에 왜 '알지 못하는 신에게'라는 제단이 서 있었으며 바울은 이를 어떻게 복음의 접촉점으로 삼았을까?",
    "visualGuide": "아테네 아레오바고 언덕 위 'ΑΓΝΩΣΤΩ ΘΕΩ(알지 못하는 신에게)'라 새겨진 돌 제단 옆에서 철학자들에게 복음을 전하는 바울",
    "dossierMd": "■ B028 | 바울이 아테네 아레오바고 연설에서 인용한 '알지 못하는 신에게(AGNOSTO THEO)' 제단 — 기원전 600년 에피메니데스의 검은 양과 흰 양 전승\n• 분류: 신약 · 11_초대교회·선교 | 테마: T06_역사·고고학 · T02_문화·관습\n• 핵심 성경 본문: 사도행전 17:22~31 (참조: 디도서 1:12)\n• 삼각 연동 코드: 인물 P030(사도 바울), 아레오바고 디오누시오, P183(다마리) | 사건 E173(바울의 아테네 아레오바고 변증 설교)\n• 호기심 질문 (The Hook): \"신들의 도시 아테네 한복판에 왜 '알지 못하는 신에게(Ἀγνώστῳ Θεῷ)'라고 새겨진 제단이 서 있었으며, 바울은 그 제단 이야기를 어떻게 십자가와 부활의 복음으로 연결했을까?\"\n• 표면적 읽기 vs 행간의 진짜 배경: 표면적 읽기: 아테네 사람들이 워낙 미신이 많아서 혹시 빠뜨린 신이 있을까 봐 예비용 제단을 하나 만들어 둔 것으로만 압니다.\n• 행간의 진실: 고대 그리스 역사가 디오게네스 라에르티오스(『철학자 열전』 1.110)의 기록에 따르면, 기원전 600년경 아테네에 끔찍한 역병이 덮쳐 온갖 신들에게 제사를 드려도 역병이 그치지 않았습니다. 그때 크레타(그레데) 출신의 현자 에피메니데스(Epimenides)가 아테네의 아레오바고 언덕으로 굶주린 양 떼를 몰고 올라가 풀밭에 풀어놓으며 이렇게 말했습니다:\n\"양들이 풀을 뜯지 않고 스스로 앉아 쉬는 곳이 있다면, 그것은 올림포스의 어떤 신도 아닌 '우리가 알지 못하는 참된 신'이 그 자리를 택하신 증거이니, 그 자리에 이름 없는 제단을 쌓고 양을 잡으시오.\"\n• 깊이 읽는 비하인드 스토리텔링: 놀랍게도 푸른 풀밭 위에서 양들이 풀을 뜯지 않고 앉은 자리마다 아테네 사람들은 '알지 못하는 신에게(AGNOSTO THEO)'라는 제단을 쌓아 피의 제사를 드렸고, 그 즉시 아테네의 역병이 그쳤습니다!\n• 650년 뒤 아레오바고 언덕에 선 바울은 아테네 철학자들이 가장 자랑스럽게 여기는 그 역사적 기억을 정면으로 소환했습니다! 심지어 바울이 사도행전 17장 28절에서 인용한 \"우리가 그를 힘입어 살며 기동하며 존재하느니라\"라는 구절은 바로 그 제단을 만들게 한 크레타 시인 에피메니데스의 시구(詩句)였습니다! 바울은 \"600년 전 너희 조상들을 역병에서 구원했으나 너희가 이름을 몰라 '알지 못하는 신'이라 새겨 놓았던 그 창조주 하나님이, 이제 예수 그리스도의 십자가 피와 부활을 통해 자신을 온 세상에 밝히 드러내셨다!\"라고 변증하여 아레오바고 판사 디오누시오와 다마리를 주께로 인도했습니다.\n• 구속사적 울림 & 『꿈바온』 한 줄 묵상:\n\"인류의 모든 철학과 종교가 어둠 속에서 더듬어 찾던 '알지 못하는 신'의 빈자리에, 예수 그리스도께서 빛으로 걸어 들어오셨습니다.\"\n• 시각 고증 및 장면 가이드: 아테네 파르테논 신전이 멀리 보이는 아레오바고 바위 언덕, 헬라어로 ΑΓΝΩΣΤΩ ΘΕΩ(알지 못하는 신에게)가 새겨진 돌 제단 옆에서 스토아·에피쿠로스 철학자들에게 설교하는 바울.",
