    "title": "도망친 노예 '오네시모(유익한 자)'의 이름 언어유희와 바울이 친필로 써준 채무 인수 증서('내 앞으로 계산하라!')",
    "origTitle": "Onesimus (The Useful One) & Paul's Signed Promissory Note (Elloga)",
