    "hook": "왜 바울은 도망친 노예 오네시모의 이름으로 원어 언어유희를 치며 '그가 빚진 것은 다 내 장부에 달아 놓으라'고 친필 서명했을까?",
    "visualGuide": "로마 감옥에서 쇠사슬에 묶인 손으로 갈대 펜을 들어 친필 차용증('나 바울이 친필로 쓰노니 내가 갚으려니와')을 쓰는 바울과 오네시모",
    "dossierMd": "■ B029 | 왜 바울은 감옥에서 도망친 노예 '오네시모'를 주인 빌레몬에게 돌려보내며, 그 빚을 '내 계산서에 달아 놓으라'고 친필 서명했을까?\n• 분류: 신약 · 11_초대교회·선교 | 테마: T01_원어·언어유희 · T08_구속사·모형\n• 핵심 성경 본문: 빌레몬서 1:10~19\n• 삼각 연동 코드: 인물 P030(사도 바울), P169(빌레몬), P168(오네시모) | 사건 E277(로마 감옥에서의 빌레몬서 집필과 오네시모의 화해)\n• 호기심 질문 (The Hook): \"로마법상 주인의 돈을 훔쳐 도망친 노예(푸기티부스)는 십자가형이나 이마 낙인형에 처해졌는데, 왜 바울은 오네시모의 이름으로 기가 막힌 원어 언어유희를 치며 친필 차용증까지 써주었을까?\"\n• 표면적 읽기 vs 행간의 진짜 배경: 표면적 읽기: 바울이 친구 빌레몬에게 노예 오네시모를 한번만 봐달라고 부탁하는 인정 어린 편지로 읽습니다.\n• 행간의 진실: '오네시모(Ὀνήσιμος, Onesimos)'라는 헬라어 이름은 당시 로마 제국에서 노예들에게 가장 흔히 붙이던 이름으로, 그 뜻이 \"유익한 자 / 쓸모 있는 자\"였습니다. 그런데 정작 주인 빌레몬의 재산을 훔쳐 로마까지 도망친 그는 이름값과 정반대로 '가장 무익하고 쓸모없는 배신자'가 되어 있었습니다.\n• 깊이 읽는 비하인드 스토리텔링: 로마 감옥에서 바울을 만나 복음을 듣고 거듭난 오네시모를 돌려보내며, 바울은 빌레몬서 11절에서 헬라어 언어유희로 이렇게 탄원합니다. \"그가 전에는 네게 무익하였으나(아크레스톤), 이제는 나와 네게 유익하므로(유크레스톤 = 오네시모의 본뜻 회복!)\" — 즉, \"예수 그리스도의 복음이 '쓸모없던 죄인'을 진짜 그의 이름대로 '가장 유익한 하나님의 사람(오네시모)'으로 바꾸어 놓았습니다!\"라는 선언입니다.\n• 더 나아가 바울은 18~19절에서 로마 상법상 구속력을 갖는 친필 채무 인수 증서(카이로그라폰) 문구를 직접 적습니다. \"그가 만일 네게 불의를 하였거나 네게 빚진 것이 있으면 그것을 내 앞으로 계산하라(엘로가, ἐλλόγα — 내 장부에 달아 놓으라)! 나 바울이 친필로 쓰노니 내가 갚으려니와...\"\n• 종교개혁자 마틴 루터는 이 구절을 읽으며 무릎을 쳤습니다. \"우리 모두가 하나님 아버지 앞에서 도망친 노예 오네시모와 같았다. 그러나 예수 그리스도께서 성부 하나님께 '아버지, 저 죄인이 빚진 모든 죄 값을 내 십자가 장부에 달아 놓으소서, 내가 다 갚겠나이다' 하심으로 우리가 자녀가 되었다!\" (후대 교부 이그나티오스의 기록에 따르면, 용서받은 오네시모는 훗날 에베소 교회의 감독이 되어 순교하기까지 충성했습니다).\n• 구속사적 울림 & 『꿈바온』 한 줄 묵상:\n\"무익한 도망자였던 나를 위해 '그의 모든 빚을 내 앞으로 계산하라' 친필로 보증서신 예수 그리스도 덕분에, 나는 하나님께 가장 유익한 '오네시모'가 되었습니다.\"\n• 시각 고증 및 장면 가이드: 로마 가택 연금 방에서 쇠사슬에 묶인 손으로 갈대 펜을 들어 파피루스에 친필 서명하는 노년의 바울과, 그 편지를 가슴에 품고 눈물 흘리는 오네시모.",
