    "dossierMd": "■ B031 | 선악과는 왜 '사과(Apple)'로 알려졌을까? — 라틴어 불가타 성경의 동음이의어 '말룸(Malum)'\n• 시대·테마: 구약 01_창조·원역사 | T07_난제·오해교정 · T01_원어·언어유희\n• 본문: 창 2:17, 3:6 | 삼각 연동: 인물 P001(아담), P002(하와) | 사건 E002(인류의 타락)\n• 호기심 질문: \"성경 어디에도 선악과가 사과라는 말이 없는데, 왜 전 세계 그림과 동화에는 선악과가 늘 빨간 사과로 그려질까?\"\n• 행간의 진실 & 스토리텔링: 히브리어 원문은 선악과를 단지 '선과 악을 알게 하는 나무의 열매(페리, פְּרִי)'라고만 부릅니다(유대 전승에서는 무화과·포도·석류·에트로그 등으로 추정). 그런데 4세기경 히에로니무스가 성경을 라틴어(불가타 역)로 번역할 때, '악(Evil)'을 뜻하는 라틴어 명사 '말룸(malum, 단모음 a)'과 '사과(Apple)'를 뜻하는 라틴어 명사 '말룸(mālum, 장모음 ā)'의 철자가 똑같았습니다! 중세 유럽 화가들과 성극 연출가들이 \"선과 악(malum)을 알게 하는 나무\"를 그리면서 동음이의어인 '사과(mālum)'로 시각화한 것이 오늘날까지 굳어진 것입니다. 선악과의 본질은 과일의 품종이 아니라 '피조물인 인간이 하나님을 왕으로 인정하는 경계선'에 있었습니다.\n• 구속사 묵상 & 시각화: 에덴 중앙의 빛나는 열매(페리, 특정 사과 품종이 아닌 신비로운 황금빛 무화과·석류 결의 열매)와 라틴어 Malum(악) / Mālum(사과) 어원 비교 카드.",
