    "hook": "하나님은 왜 제물을 받으시기 전에 먼저 예배자인 '아벨'과 '가인'의 마음과 삶을 먼저 살피셨을까?",
    "visualGuide": "양의 첫 새끼의 기름진 부위를 믿음으로 드리는 아벨과 형식적인 곡식 단 앞에서 안색이 변한 가인",
    "dossierMd": "■ B032 | 왜 하나님은 가인의 제사는 받지 않으시고 아벨의 제사만 받으셨을까? — '피의 유무'보다 먼저였던 '아벨과 그의 제물'의 순서\n• 시대·테마: 구약 01_창조·원역사 | T01_원어·언어유희 · T08_구속사·모형\n• 본문: 창 4:3~5 (참조: 히 11:4, 요일 3:12) | 삼각 연동: 인물 P202(아벨), P201(가인) | 사건 E031(가인과 아벨의 제사)\n• 호기심 질문: \"농부인 가인이 땅의 소산을 드린 것이 잘못이었을까, 아니면 제물을 드리는 태도와 순서에 결정적 차이가 있었을까?\"\n• 행간의 진실 & 스토리텔링: 구약 레위기에도 곡식으로 드리는 '소제(민하)'가 있으므로 곡식 제물 자체가 거부된 것은 아닙니다. 창세기 4장 3~4절 원문을 자세히 보면 세 가지 결정적 차이가 드러납니다. 첫째, 가인은 그냥 \"땅의 소산으로\" 드렸으나, 아벨은 \"양의 첫 새끼 중에서도 기름진 것(가장 최상의 부위, 헬레브)\"을 구별해 드렸습니다. 둘째, 히브리서 11장 4절이 증언하듯 아벨은 \"믿음으로\" 드렸습니다. 셋째, 창세기 4장 4~5절의 어순을 보면 하나님은 먼저 '아벨(예배자의 삶과 중심)'을 받으시고 그다음에 '그의 제물'을 받으셨으며, 반대로 먼저 '가인(형제 미움과 교만)'을 받지 않으시고 '그의 제물'을 받지 않으셨습니다. 하나님은 예물보다 예배자 자신을 먼저 받으십니다.\n• 구속사 묵상 & 시각화: 돌 제단 위에 첫 새끼 양의 기름진 부위를 정성껏 올려놓고 무릎 꿇은 아벨과, 형식적으로 곡식 단을 쌓아 두고 안색이 변한 가인의 대비.",
