    "hook": "왜 므두셀라는 성경에서 가장 긴 969세를 살았으며 그가 숨을 거둔 바로 그 해에 정확히 무슨 일이 일어났을까?",
    "visualGuide": "므두셀라 생애 연대기(187세 라멕 출생 + 182세 노아 출생 + 노아 600세 홍수 = 정확히 969세 사망 연도 일치) 인포그래픽",
    "dossierMd": "■ B033 | 성경 최장수 969세 '므두셀라' 이름에 숨겨진 노아 홍수 D-Day 시한부 예언\n• 시대·테마: 구약 01_창조·원역사 | T01_원어·언어유희 · T08_구속사·모형\n• 본문: 창 5:21~27, 7:11 | 삼각 연동: 인물 P204(에녹), P205(므두셀라), P003(노아) | 사건 E032(에녹의 동행과 승천), E003(노아의 방주와 대홍수)\n• 호기심 질문: \"왜 므두셀라는 성경의 모든 인물 중 가장 긴 969년을 살았으며, 그가 죽은 해에 정확히 무슨 일이 일어났을까?\"\n• 행간의 진실 & 스토리텔링: 에녹은 65세에 아들 므두셀라(히브리어 메투쉘라흐, מְתוּשֶׁלַח)를 낳은 직후부터 300년간 하나님과 동행했습니다(창 5:22). 에녹이 하나님께로부터 장차 임할 심판의 계시를 받고 지은 아들 이름 '므두셀라'는 히브리어로 \"그가 죽으면(무트) 보낸다/심판이 임한다(샬라흐)\"라는 뜻입니다! 놀랍게도 창세기 5장의 연대를 계산해 보면, 므두셀라가 187세에 손자 노아를 얻고, 노아가 600세 되던 해(187 + 182(라멕) + 600 = 969세) — 즉 므두셀라가 969세로 숨을 거둔 바로 그 해에 노아의 대홍수가 터졌습니다! 왜 므두셀라가 성경에서 가장 오래(969년) 살았을까요? \"그가 죽으면 심판이 온다\"는 약속 때문에, 한 사람이라도 더 회개하고 돌아오기를 기다리신 하나님의 오래 참으심(벧후 3:9)이 그의 수명을 인류 최장수 969년까지 늘려 놓으신 것입니다!\n• 구속사 묵상 & 시각화: 969년의 연대기 타임라인 막대그래프(므두셀라의 생애 = 하나님의 오래 참으심 969년)와 방주 문이 닫히기 전까지 기다리시는 하나님의 은혜 인포그래픽.",
