    "title": "노아의 방주와 아기 모세의 갈대 상자에만 쓰인 히브리어 '테바(Tebah)' — 왜 둘 다 돛도 키(방향타)도 없었을까?",
    "origTitle": "The Ark of Noah and the Basket of Moses Both Called 'Tebah' Without Rudder or Sail",
