    "hook": "거대한 배인 노아의 방주와 아기 모세의 작은 갈대 상자가 히브리어 원문에서는 왜 똑같은 단어 '테바'로 기록되어 있을까?",
    "visualGuide": "역청을 칠하고 조향 장치(키·돛) 없이 오직 하나님의 손에 맡겨진 노아의 방주(테바)와 모세의 갈대 상자(테바) 대조도",
    "dossierMd": "■ B034 | 노아의 방주에는 왜 '키(방향타)'도 '돛'도 '노'도 없었을까? — 히브리어 '테바(Tebah)'가 쓰인 단 두 곳\n• 시대·테마: 구약 01_창조·원역사 | T01_원어·언어유희 · T08_구속사·모형\n• 본문: 창 6:14~16, 출 2:3 | 삼각 연동: 인물 P003(노아), P009(모세) | 사건 E003(노아의 방주), E011(모세의 갈대 상자)\n• 호기심 질문: \"거대한 배인 노아의 방주와 아기 모세를 눕힌 작은 갈대 상자가 히브리어 원문에서는 왜 완전히 똑같은 단어 '테바(תֵּבָה)'로 기록되어 있을까?\"\n• 행간의 진실 & 스토리텔링: 구약성경에서 일반 항해용 배는 '오니야(요 1:3)'라고 부르지만, 오직 노아의 방주(창 6:14)와 아기 모세의 갈대 상자(출 2:3) 단 두 곳에만 이집트 차용어인 '테바(תֵּבָה — 상자/관)'라는 단어가 쓰였습니다! 두 '테바'는 놀라운 공통점을 가집니다. 첫째, 둘 다 물이 스며들지 않도록 안팎에 역청(진흙)을 칠했습니다. 둘째, 둘 다 동력 장치(돛·노)와 조향 장치(키·방향타)가 전혀 없었습니다! 셋째, 둘 다 죽음의 물 한가운데서 새로운 구속 시대를 열 구원자(노아 가족, 모세)의 생명을 보존했습니다. 방향타가 없다는 것은 \"인간의 항해술이나 조종 실력으로 구원받는 것이 아니라, 오직 파도를 다스리시는 하나님의 손길에 100% 맡겨진 구원의 상자(예수 그리스도)\"임을 뜻합니다. 또한 방주의 유일한 창문(초하르, 창 6:16)을 옆면이 아닌 지붕 꼭대기('위로부터 한 규빗')에 내게 하신 것은, 사방에 넘실대는 죽음의 홍수(현실의 두려움)를 보지 말고 오직 위로부터 비치는 하나님의 하늘만 올려다보라는 설계였습니다.\n• 구속사 묵상 & 시각화: 키와 돛이 없고 지붕 위로만 창이 난 노아의 방주(테바)와 나일강 위의 아기 모세 갈대 상자(테바)가 위아래로 겹쳐지는 구속사 대조 일러스트.",
