    "title": "아브라함이 떠나온 '갈대아 우르'의 고고학 — 2층 회칠 벽돌 저택과 수세식 상하수도를 갖춘 초일류 문명도시를 버린 믿음",
    "origTitle": "Ur of the Chaldeans Excavated by Leonard Woolley vs the Nomad's Tent",
    "scriptures": "창 11:31~12:1; 히 11:8~10",
    "hook": "아브라함이 고향 갈대아 우르를 떠난 것은 낙후된 시골을 떠난 것이었을까 아니면 당대 세계 최고 문명도시의 기득권을 내려놓은 결단이었을까?",
    "visualGuide": "웅장한 지구라트와 2층 백색 저택이 즐비한 고대 우르 성문을 뒤로하고 검은 염소털 장막 나그네 길로 나서는 아브라함",
    "dossierMd": "■ B035 | 아브라함의 고향 '갈대아 우르'는 초라한 시골이었을까? — 수세식 화장실과 2층 벽돌 저택을 버리고 떠난 믿음\n• 시대·테마: 구약 02_족장시대 | T06_역사·고고학\n• 본문: 창 11:31~12:1 (참조: 수 24:2, 히 11:8~10) | 삼각 연동: 인물 P004(아브라함), P005(사라), P207(데라) | 사건 E005(아브라함의 소명과 가나안 이주)\n• 호기심 질문: \"아브라함이 갈대아 우르를 떠난 것은 시골에서 더 좋은 곳으로 이민 간 것이었을까, 아니면 당대 세계 최고의 초일류 문명도시는 버리고 장막 생활로 뛰어든 것이었을까?\"\n• 행간의 진실 & 스토리텔링: 1922~1934년 영국 고고학자 레너드 울리(Leonard Woolley) 경이 이라크 남부 우르(Ur, 우르 제3왕조 수도) 유적을 발굴했을 때 전 세계가 경악했습니다. 아브라함 당시(기원전 2000년경)의 갈대아 우르는 거대한 난나(달의 신) 지구라트 신전, 10~14개의 방을 갖춘 회칠한 2층 구운 벽돌 저택, 상하수도 배관과 수세식 화장실, 도서관과 무역 금융 문서, 황금 투구와 보석 세공품을 갖춘 당대 세계 최고 수준의 초호화 메트로폴리스였습니다! 아브라함은 달의 신을 섬기며 우상을 만들던(수 24:2) 그 안락하고 화려한 세계 최정상 문명도시의 기득권을 하나님의 말씀 한마디에 내려놓고, 평생 집 한 채 없이 검은 염소털 천막을 치며 떠도는 나그네의 길을 선택했습니다. 왜냐하면 \"그가 하나님이 계획하시고 지으실 터가 있는 성을 바랐기 때문\"(히 11:10)입니다.\n• 구속사 묵상 & 시각화: 웅장한 지구라트와 2층 백색 저택이 늘어선 고대 문명도시 우르의 성문을 뒤로하고, 광야의 모래바람 속으로 낙타와 양 떼를 몰고 걸어 나오는 아브라함과 사라.",
