    "hook": "불임인 본처가 자기 여종을 남편에게 주고 임신한 여종이 교만해졌을 때 강등시키는 행동은 고대 근동 어떤 법에 따른 것이었을까?",
    "visualGuide": "고대 설형문자 점토판 법전(함무라비·누지 문서)과 브엘라해로이 샘가에서 하갈을 만나주시는 여호와의 사자",
    "dossierMd": "■ B036 | 왜 사라의 여종 하갈은 임신하자마자 안주인 사라를 멸시했고, 사라는 왜 아브라함에게 책임을 물었을까? — 함무라비 법전 제146조의 배경\n• 시대·테마: 구약 02_족장시대 | T02_문화·관습 · T06_역사·고고학\n• 본문: 창 16:1~6 | 삼각 연동: 인물 P004(아브라함), P005(사라), P210(하갈), P211(이스마엘) | 사건 E034(하갈의 도주와 브엘라해로이)\n• 호기심 질문: \"불임인 본처가 자신의 여종을 남편에게 주어 대리모를 삼는 행동과, 임신한 여종이 본처를 무시했을 때 종으로 강등시키는 처분은 아브라함 집안만의 특이한 일이었을까?\"\n• 행간의 진실 & 스토리텔링: 고대 근동의 누지(Nuzi) 문서와 함무라비 법전(제144~146조)을 보면 창세기 16장의 모든 행동이 당시 메소포타미아 관습법 그대로였음이 밝혀집니다. 당시 법에 따르면 정실 아내가 자식이 없을 때 자신의 직속 여종을 남편에게 첩으로 줄 의무와 권리가 있었고, 여종이 낳은 아이는 본처의 무릎 위에서 출산하여 본처의 법적 자녀로 입적되었습니다. 또한 함무라비 법전 제146조는 \"여종이 아이를 밴 뒤 안주인과 동등해지려 하며 안주인을 업신여기면, 안주인은 그 여종을 돈 받고 팔 수는 없으나 다시 노예의 표식을 채워 일반 여종으로 강등시킬 수 있다\"고 규정했습니다! 아브라함이 사라에게 \"당신의 여종은 당신의 수중에 있으니 당신의 눈에 좋을 대로 그에게 행하라\"(창 16:6)고 말한 것은 무책임한 회피라기보다, 고대 근동 법상 본처에게 부여된 여종 인사권을 공식 확인해 준 조치였습니다. 그러나 하나님의 약속을 기다리지 않고 세상 관습법(인간적 편법)을 따른 결과는 수천 년간의 가정 불화와 아픔을 낳았습니다.\n• 구속사 묵상 & 시각화: 고대 점토판 법전(함무라비·누지 계약서) 배경과 브엘라해로이 샘가에서 우는 하갈을 찾아오신 여호와의 사자.",
