    "hook": "롯의 아내가 뒤를 돌아보았다는 히브리어 동사 '나바트'에는 어떤 마음의 상태가 담겨 있으며 왜 하필 소금 기둥이 되었을까?",
    "visualGuide": "사해 남단 스돔 산 암염 절벽 지대에서 불타는 소돔을 미련 가득히 돌아보며 소금 화산재에 덮여 굳어지는 롯의 아내",
    "dossierMd": "■ B037 | 롯의 아내는 왜 뒤를 돌아보다가 하필 '소금 기둥'이 되었을까? — 사해 남단 암염 지형과 마음의 미련\n• 시대·테마: 구약 02_족장시대 | T05_지리·생태 · T01_원어·언어유희\n• 본문: 창 19:17, 19:26 (참조: 눅 17:32) | 삼각 연동: 인물 P208(롯), P004(아브라함) | 사건 E007(소돔과 고모라 유황불 심판)\n• 호기심 질문: \"천사가 '뒤를 돌아보지 말라'고 경고했는데, 롯의 아내가 '돌아보았다(히브리어 나바트)'는 단어에는 어떤 깊은 뜻이 담겨 있을까?\"\n• 행간의 진실 & 스토리텔링: 창세기 19장 26절에서 롯의 아내가 뒤를 '돌아보았으므로(와타베트, 원형 나바트 נָבַט)'라는 히브리어 동사는 고개를 잠깐 휙 돌렸다는 뜻이 아니라, \"아쉬움과 미련을 품고 오랫동안 응시하며 발걸음을 멈추다\"라는 뜻입니다! 몸은 천사의 손에 이끌려 소돔 성 밖으로 나왔지만, 그녀의 마음과 보물창고는 여전히 불타는 소돔 성 안에 남아 있었던 것입니다(그래서 예수님도 눅 17:32에서 세상의 소유에 미련을 두지 말라며 \"롯의 아내를 기억하라!\"고 경고하셨습니다). 지질학적으로도 소돔과 고모라가 위치한 사해(염해) 남단 스돔 산(Mount Sodom / 자발 우스둠) 일대는 거대한 암염(소금 바위)과 유황·역청 층이 매장된 단층지대로, 대지진과 함께 지하의 유황 가스와 소금물이 하늘로 치솟아 폭발할 때 뒤처져 멈춰 선 그녀의 몸 위로 고농도 소금 화산재가 덮쳐 소금 기둥으로 굳어버린 것입니다.\n• 구속사 묵상 & 시각화: 붉은 유황불이 치솟는 사해 남단 평지와 앞만 보고 소알 성으로 달리는 롯 일행 뒤에서, 소돔을 향해 고개를 돌린 채 하얗게 굳어가는 소금 기둥(오늘날 사해 남단 스돔 산의 '롯의 아내' 암염 기둥 지형 반영).",
