    "title": "막벨라 굴 매입 때 헷 사람 에브론이 '거저 드리겠다'고 세 번 사양하며 밭 전체를 끼워 팔아 은 400세겔을 받은 히타이트 토지세법",
    "origTitle": "Abraham Buying the Cave of Machpelah & Hittite Land Law (400 Shekels of Silver)",
    "scriptures": "창 23:3~20",
    "hook": "왜 아브라함은 동굴만 사려 했는데 에브론은 인심 쓰는 척 밭 전체를 통째로 사게 유도하고 은 400세겔 거금을 다 받았을까?",
    "visualGuide": "헤브론 성문 앞 장로들 앞에서 깎지 않고 은 400세겔을 정량대로 달아주어 가나안 땅 첫 합법 등기를 확보하는 아브라함",
    "dossierMd": "■ B038 | 아브라함이 사라의 매장지로 막벨라 굴을 살 때, 왜 헷 사람 에브론은 '그냥 공짜로 드리겠다'고 세 번이나 사양하다가 은 400세겔 거금을 다 받았을까?\n• 시대·테마: 구약 02_족장시대 | T02_문화·관습 · T06_역사·고고학\n• 본문: 창 23:3~20 | 삼각 연동: 인물 P004(아브라함), P005(사라), 헷 사람 에브론 | 사건 E036(사라의 죽음과 헤브론 막벨라 굴 매입)\n• 호기심 질문: \"에브론이 처음에는 '내 주여 들으소서 그 밭과 굴을 거저 드리리이다'라고 호탕하게 말하더니, 왜 바로 다음 문장에서 '땅값은 은 400세겔이나 우리 사이에 그게 무슨 문제가 되리이까'라며 부르는 게 값인 폭리를 취했을까?\"\n• 행간의 진실 & 스토리텔링: 고대 중동 상거래의 전형적인 '예의상 사양을 가장한 고단수 가격 흥정법(Oriental Bargaining)'과 히타이트(헷 족속) 부동산 세법이 숨어 있습니다! 첫째, 아브라함은 원래 밭 끝에 있는 '막벨라 굴(동굴)만' 사겠다고 요청했습니다(창 23:9). 왜냐하면 당시 헷 족속의 법(히타이트 법전 제46~47조)에 따르면, 토지의 일부(굴만)를 매입하면 봉건적 부역과 세금 의무는 원주인(에브론)에게 남지만, 밭 전체(밭과 굴과 그 안의 모든 나무)를 통째로 매입하면 매수자(아브라함)가 모든 세금과 의무를 떠안게 되어 있었기 때문입니다! 그래서 에브론은 인심 쓰는 척하며 \"밭과 굴을 다 드리겠습니다\"라고 끼워 팔기를 시도했고, 말끝에 은근슬쩍 '은 400세겔'이라는 당시 시세의 수십 배에 달하는 거액(훗날 다윗이 성전 터 아라우나 타작마당을 살 때는 은 50세겔, 오므리가 사마리아 산 전체를 살 때 은 2달란트)을 불렀습니다. 그러나 아브라함은 깎으려 하지 않고 상인이 통용하는 정량으로 은 400세겔을 전액 달아 주어, 장차 자신의 후손이 차지할 가나안 약속의 땅에 누구도 취소할 수 없는 첫 번째 합법적 등기부등본(믿음의 교두보)을 박아 넣었습니다!\n• 구속사 묵상 & 시각화: 헤브론 성문 앞 헷 족속 장로들이 지켜보는 가운데 청동 저울에 은 400세겔을 정확히 달아 건네는 아브라함과, 나무가 우거진 막벨라 바위 동굴.",
