    "hook": "사막을 건너온 낙타 열 마리가 배불리 마시는 물의 양은 실제로 얼마나 되며 리브가는 몇 번이나 우물 계단을 오르내렸을까?",
    "visualGuide": "해 질 녘 메소포타미아의 깊은 계단식 우물에서 땀을 흘리며 열 마리 낙타의 물구유에 물을 가득 채우는 리브가의 섬김",
    "dossierMd": "■ B039 | 왜 리브가는 일면식도 없는 나그네(엘리에셀)의 낙타 열 필에게 물을 다 길어 주었을까? — 물동이 약 1,000리터의 기적적인 헌신\n• 시대·테마: 구약 02_족장시대 | T04_사물·생활사 · T02_문화·관습\n• 본문: 창 24:14~20 | 삼각 연동: 인물 P006(이삭), P213(리브가), P212(엘리에셀) | 사건 E037(이삭과 리브가의 결혼)\n• 호기심 질문: \"사막을 건너온 낙타 열 필이 배불리 마시는 물의 양은 실제로 얼마나 되며, 왜 아브라함의 종 엘리에셀은 이것을 며느리감의 결정적 시험 기준으로 삼았을까?\"\n• 행간의 진실 & 스토리텔링: 사막을 며칠간 걸어와 갈증 난 성체 낙타 한 마리가 한 번에 마시는 물의 양은 무려 80~100리터에 달합니다! 즉, 낙타 열 필이 다 마시기까지 물을 길어 주려면 약 800~1,000리터(15리터짜리 토기 물동이로 무려 60~70번 이상!)를 우물 계단 아래로 오르내리며 구유에 쏟아부어야 합니다. 건장한 성인 남성도 2시간 이상 땀을 비오듯 흘려야 하는 중노동입니다! 엘리에셀은 외모나 재력이 아니라, 아무 대가도 바랄 수 없는 낯선 나그네와 말 못하는 짐승에게까지 기꺼이 1,000리터의 물을 길어 나르는 '지극한 환대와 섬김의 성품(헤세드)'을 가진 여인인지를 기도제목으로 걸었고, 리브가는 \"내가 당신의 낙타를 위하여서도 물을 길어 그것들로 배불리 마시게 하리이다\"라며 '급히(마하르)' 달려가 그 일을 완수함으로 언약 가문의 안주인이 되었습니다.\n• 구속사 묵상 & 시각화: 메소포타미아 나홀 성 밖 해 질 녘의 깊은 계단식 우물에서, 토기 물동이를 어깨에 메고 땀 흘리며 열 마리 낙타의 돌 물구유에 물을 가득 채우는 리브가.",
