    "hook": "라헬은 왜 친정을 떠나면서 아버지 라반의 드라빔을 훔쳤으며 라반은 왜 일주일 길을 추격해 그 작은 신상을 되찾으려 했을까?",
    "visualGuide": "천막 안 낙타 안장 위에 앉은 라헬과 누지 점토판 문서 속 가문 상속권 증표로서의 드라빔 소형 신상 도해",
    "dossierMd": "■ B040 | 라헬은 왜 친정집을 몰래 떠나면서 아버지 라반의 우상 '드라빔(Teraphim)'을 훔쳐 낙타 안장 밑에 숨겼을까?\n• 시대·테마: 구약 02_족장시대 | T02_문화·관습 · T06_역사·고고학\n• 본문: 창 31:19, 31:30~35 | 삼각 연동: 인물 P007(야곱), P215(라헬), P217(라반) | 사건 E039(야곱의 밧단아람 탈출과 미스바 언약)\n• 호기심 질문: \"라헬은 미신 때문에 친정집 우상 드라빔을 훔쳤을까, 아니면 고대 메소포타미아의 '가문 상속권 증서'를 챙기려 했던 것일까?\"\n• 행간의 진실 & 스토리텔링: 이라크 북부에서 발굴된 기원전 15세기 누지(Nuzi) 설형문자 점토판이 이 미스터리를 풀어주었습니다! 당시 메소포타미아 하란 지역의 관습법에 따르면, 장인이 사위에게 가문의 재산 상속권과 족장권을 넘겨줄 때 가문의 수호신상인 '드라빔(Teraphim, 손바닥~사람 머리 크기의 가정 우상)'을 증표로 넘겨주었습니다. 즉, 드라빔을 소유한 사위가 장인 사후에 가문의 합법적 재산 상속권(유언장 효력)을 주장할 수 있었던 것입니다! 라반이 20년간 야곱의 품삯을 열 번이나 속이고 재산을 가로채자, 라헬은 아버지의 부당한 대우에 반발하여 남편 야곱에게 장자 상속권을 확보해 주려는 인간적 계산(동시에 친정 우상 문화의 잔재)으로 드라빔을 훔쳤고, 라반 역시 그 재산권 증표를 되찾으려 일주일 길을 맹추격해 온 것입니다. 결국 야곱은 훗날 세겜 상수리나무 아래에 이 모든 이방 신상과 귀고리를 땅에 묻어버리고서야(창 35:4) 벧엘로 올라갈 수 있었습니다.\n• 구속사 묵상 & 시각화: 천막 안 낙타 안장(카르) 위에 앉아 태연한 척하는 라헬과 천막을 뒤지는 라반, 그리고 누지 문서 속 소형 점토 조각상(드라빔) 고증 도해.",
