    "title": "17세 소년 요셉이 팔린 몸값 '은 20세겔'(BC 1800년 고바벨론 노예 시세)과 예수님이 팔리신 '은 30세겔'(모세·신약 시대 시세)의 고고학!",
    "origTitle": "Joseph Sold for 20 Shekels of Silver vs Ancient Near Eastern Slave Price Inflation",
    "scriptures": "창 37:25~28; 출 21:32; 마 26:15",
    "hook": "왜 요셉이 팔린 값은 은 20세겔이고 모세 율법과 예수님 시대의 노예 몸값은 정확히 은 30세겔로 10세겔 차이가 날까?",
    "visualGuide": "고대 근동 시대별 노예 시세표(기원전 18세기 은 20세겔 → 기원전 15세기 이후 은 30세겔)와 미디안 대상에게 팔리는 요셉",
    "dossierMd": "■ B041 | 왜 요셉의 형들은 요셉을 죽이려다 말고 하필 '미디안 상인들에게 은 20세겔'에 팔아넘겼을까? — 고대 노예 시세표의 증거\n• 시대·테마: 구약 02_족장시대 | T06_역사·고고학 · T08_구속사·모형\n• 본문: 창 37:25~28 (참조: 레 27:5, 출 21:32, 마 26:15) | 삼각 연동: 인물 P156(요셉), P218(유다) | 사건 E041(요셉의 채색옷과 애굽 노예 피랍)\n• 호기심 질문: \"요셉이 팔린 몸값 '은 20세겔'과 예수님이 팔리신 몸값 '은 30세겔'은 고대 사회의 물가에서 왜 정확히 10세겔 차이가 날까?\"\n• 행간의 진실 & 스토리텔링: 고대 근동 역사가 케네스 키친(Kenneth Kitchen) 교수가 시대별 고대 메소포타미아·이집트 노예 매매 문서를 전수 조사한 결과, 놀랍게도 아브라함·요셉 시대(기원전 19~18세기, 고바벨론 및 함무라비 시대)의 남성 노예 평균 시세가 정확히 '은 20세겔'이었습니다! 반면 세월이 흘러 물가가 오르면서 모세 시대(기원전 15~13세기, 출 21:32)에는 성인 노예 몸값이 '은 30세겔'이 되었고, 페르시아 시대에는 은 90~120세겔까지 올랐습니다. 즉, 창세기 37장 28절의 '은 20세겔'은 후대에 창작된 숫자가 아니라 기원전 18세기 당시의 정확한 시장 가격이며(레 27:5에서도 5~20세 남자의 서원 값을 은 20세겔로 책정 — 당시 요셉의 나이가 정확히 17세!), 형제 유다(Judah)의 제안으로 은 20세겔에 팔린 17세 소년 요셉은, 훗날 동명이인 제자 가룟 유다(Judas)에 의해 성인 노예 몸값인 은 30세겔(마 26:15)에 팔려 온 인류를 구원하신 예수 그리스도의 완벽한 그림자였습니다.\n• 구속사 묵상 & 시각화: 도단 들녘의 마른 구덩이 옆에서 향품을 실은 미디안 낙타 대상에게 은 20세겔을 받고 요셉을 넘기는 형들과 시대별 고대 노예 몸값 변화표(BC 1800년 은 20세겔 vs 출애굽·예수님 시대 은 30세겔).",
