    "dossierMd": "■ B042 | 보디발의 아내가 요셉을 유혹할 때 왜 성경은 '집에 다른 사람들이 하나도 없었더라'를 강조하며, 왜 보디발은 요셉을 사형시키지 않고 왕의 감옥에 넣었을까?\n• 시대·테마: 구약 02_족장시대 | T03_행간·인물관계 · T02_문화·관습\n• 본문: 창 39:11~20 | 삼각 연동: 인물 P156(요셉), P231(보디발) | 사건 E042(보디발의 집 시련과 감옥 총무)\n• 호기심 질문: \"고대 이집트에서 외국인 노예가 친위대장의 아내를 강간하려 했다면 그 자리에서 즉결 처형감인데, 왜 보디발은 화만 내고 요셉을 살려두었을까?\"\n• 행간의 진실 & 스토리텔링: 고대 이집트 귀족 저택은 하인이 수십 명씩 북적거렸는데, 창세기 39장 11절에 \"그 집에 사람 가운데 아무도 거기에 없었더라\"는 것은 그날이 나일강 범람 축제일(또는 태양신 축제일)이어서 보디발의 아내가 일부러 하인들을 모두 축제에 내보내고 아픈 척 집에 남아 요셉을 기다렸다는 고대 유대 주석의 설명과 정확히 들어맞습니다. 더 흥미로운 것은 남편 보디발의 반응입니다! 창세기 39장 19절에 \"주인이 자기 아내가 자기에게 이르기를 '당신의 종이 내게 이같이 행하였다' 하는 말을 듣고 심히 노한지라\"라고 되어 있는데, 누구에게 화가 났는지 목적어가 생략되어 있습니다. 만약 요셉의 강간 미수를 100% 믿었다면 친위대장(원어 사리스 파르오 — 사형 집행관들의 우두머리!)인 보디발은 요셉을 즉시 처형했을 것입니다. 그러나 보디발은 평소 자기 아내의 행실과 요셉의 정직함을 너무나 잘 알고 있었기에 아내의 거짓말을 눈치챘고, 체면상 요셉을 그냥 둘 수는 없어 자신이 직접 관할하는 '왕의 죄수를 가두는 감옥'(창 39:20)에 넣어 요셉의 생명을 보존하고 곧이어 감옥 전체의 총무로 맡겼습니다! 그 감옥이야말로 요셉이 바로의 술 맡은 관원장을 만나 국무총리로 직행하는 하나님의 비밀 엘리베이터였습니다.\n• 구속사 묵상 & 시각화: 화려한 이집트 기둥 저택에서 겉옷을 버려두고 밖으로 뛰어 나오는 요셉과, 왕의 감옥 열쇠 꾸러미를 맡아 죄수들을 돌보는 요셉.",
