    "dossierMd": "■ B043 | 바로 왕 앞에서 요셉이 '수염을 깎고(면도하고)' 나아간 단 한 줄의 기록이 증명하는 이집트 궁정 고증\n• 시대·테마: 구약 02_족장시대 | T02_문화·관습 · T06_역사·고고학\n• 본문: 창 41:14 | 삼각 연동: 인물 P156(요셉) | 사건 E011(요셉의 애굽 총리 등극)\n• 호기심 질문: \"히브리인들에게 수염은 남자의 명예여서 수염을 깎는 것은 큰 수치(삼하 10:4)였는데, 왜 창세기 41장 14절은 요셉이 감옥에서 나와 바로 앞에 설 때 '수염을 깎고' 들어갔다고 기록했을까?\"\n• 행간의 진실 & 스토리텔링: 고대 근동에서 셈족(히브리인·아람인·바벨론인) 남성들은 모두 풍성한 수염을 기르는 것을 남성성과 지혜의 상징으로 여겼습니다. 반면 고대 이집트인들은 전 세계에서 유일하게 머리카락과 수염을 말끔히 면도(Shaving)하는 것을 청결과 신성함의 기준으로 삼았던 민족이었습니다!(파라오조차 평소에는 면도를 하고 공식 의식 때만 끈으로 묶는 가짜 금속 턱수염 오시리스 수염을 달았음). 이집트 문화에 정통하지 않은 후대 작가가 썼다면 절대 알 수 없는 디테일인 \"요셉이 곧 수염을 깎고(와예갈라흐) 그의 옷을 갈아입고 바로에게 들어가니\"(창 41:14)라는 구절은, 창세기가 이집트 궁정 예법을 정확히 아는 모세에 의해 기록되었음을 보여주는 빛나는 고증 증거입니다.\n• 구속사 묵상 & 시각화: 감옥에서 나온 히브리 청년 요셉이 이집트 세마포 예복을 입고 깔끔히 면도한 모습으로 파라오의 황금 어전 기둥 홀에 당당히 서는 장면.",
