    "dossierMd": "■ B045 | 모세는 왜 떨기나무 불꽃 앞에서 '신발을 벗으라'는 명령을 들었을까? — 종의 맨발과 거룩한 땅\n• 시대·테마: 구약 03_출애굽·광야 | T02_문화·관습\n• 본문: 출 3:1~5 (참조: 수 5:15) | 삼각 연동: 인물 P009(모세) | 사건 E011(떨기나무 소명)\n• 호기심 질문: \"하나님이 모세와 여호수아에게 사명을 주실 때 제일 먼저 요구하신 행동이 왜 하필 '네 발에서 신을 벗으라'였을까?\"\n• 행간의 진실 & 스토리텔링: 첫째, 광야에서 양을 치는 목자의 가죽 샌들 바닥에는 온갖 오물과 먼지가 묻어 있습니다. 신을 벗는 것은 내 세상의 더러움과 과거의 걸음을 내려놓는 정결의 행위였습니다. 둘째, 고대 근동에서 노예(종)들은 평생 신발을 신지 못하고 맨발로 주인을 섬겼습니다(그래서 탕자가 돌아왔을 때 아버지가 종이 아닌 아들의 신분으로 회복시키며 '발에 신을 신기라'고 한 것임). 모세가 신발을 벗은 것은 \"하나님, 이제부터 내 인생의 주인은 내가 아니라 여호와 당신이시며, 나는 주님의 맨발의 종입니다\"라는 주권 양도의 고백이었습니다. 셋째, 시내 광야의 흔하고 가시 돋친 떨기나무(스네)가 타서 재가 되지 않고 계속 불타올랐던 이유는 나무가 특별해서가 아니라 그 안에 계신 하나님의 임재의 불 때문이었습니다. 마찬가지로 80세 노인 모세가 지치지 않고 사명을 감당할 수 있는 비결도 모세의 스펙이 아니라 그와 함께하시는 '스스로 있는 자(예흐예 아쉐르 예흐예)'의 불꽃에 있었습니다.\n• 구속사 묵상 & 시각화: 호렙산 바위 앞 타오르되 재가 되지 않는 가시 떨기나무 불꽃 앞에서 가죽 샌들을 벗어 옆에 두고 맨발로 엎드린 80세의 모세.",
