    "visualGuide": "광야 행군 대열 속에서 함께 이동하는 황금빛 언약궤(아론 하베리트)와 이집트풍 나무 관인 요셉의 유골함(아론 요셉)",
    "dossierMd": "■ B046 | 왜 출애굽할 때 이스라엘 백성들은 400년 전에 죽은 '요셉의 유골(뼈)'을 관에 담아 메고 나왔을까?\n• 시대·테마: 구약 03_출애굽·광야 | T08_구속사·모형 · T02_문화·관습\n• 본문: 출 13:19 (참조: 창 50:24~26, 수 24:32, 히 11:22) | 삼각 연동: 인물 P156(요셉), P009(모세), P114(여호수아) | 사건 E012(출애굽), E052(가나안 땅 분배와 세겜 언약)\n• 호기심 질문: \"요셉은 애굽의 국무총리로서 거대한 피라미드나 왕가의 계곡에 묻힐 수 있었는데, 왜 자기 뼈를 가나안으로 메고 가달라고 유언했으며 그 유골함은 광야 40년 내내 어떤 역할을 했을까?\"\n• 행간의 진실 & 스토리텔링: 히브리서 11장 22절은 요셉의 일생 중 가장 위대한 믿음의 행위로 총리 등극이 아니라 \"임종시에 이스라엘 자손들이 떠날 것을 말하고 또 자기 뼈를 위하여 명하였으며\"를 꼽습니다! 요셉이 죽을 때 미라(향 재료를 넣은 입관)로 처리된 그의 관(아론, 창 50:26)은 지하 무덤에 영구 매장되지 않고 고센 땅 지상에 안치되어 있었습니다. 이스라엘 백성들이 애굽에서 벽돌을 구우며 채찍에 맞을 때마다, 그들은 요셉의 관을 보며 \"하나님이 반드시 우리를 찾아오셔서 이 관을 메고 약속의 땅으로 나가게 하실 것이다!\"라는 소망을 붙들었습니다. 그리고 광야 40년 행군 내내 이스라엘 진영에는 두 개의 나무 상자(히브리어로 둘 다 똑같이 '아론 אָרוֹן'!)가 함께 이동했습니다 — 하나는 살아계신 하나님의 말씀이 담긴 '언약궤(아론 하베리트)'였고, 다른 하나는 하나님의 약속이 반드시 이루어진다는 증거인 '요셉의 유골함(아론 요셉)'이었습니다! 마침내 여호수아 24장 32절에서 그 뼈가 세겜 땅에 묻히며 400년 언약이 완수되었습니다.\n• 구속사 묵상 & 시각화: 광야 행군 대열 속에서 앞장선 금빛 '언약궤(아론)'와 레위인들이 함께 메고 가는 이집트풍 나무 관 '요셉의 유골함(아론)'이 나란히 걸어가는 구속사 행군도.",
