    "visualGuide": "새벽이슬 마른 광야 모래 위에 내린 하얀 고수씨 같은 만나와 하루 한 오멜씩 거두는 백성들",
    "dossierMd": "■ B047 | 광야에서 내린 '만나(Manna)'의 진짜 이름은 왜 '이것이 무엇이냐?(만 후)'라는 질문 그 자체였을까?\n• 시대·테마: 구약 03_출애굽·광야 | T01_원어·언어유희 · T04_사물·생활사\n• 본문: 출 16:14~15, 16:31 (참조: 요 6:31~35) | 삼각 연동: 인물 P009(모세) | 사건 E045(마라의 쓴물과 엘림, 만나와 메추라기)\n• 호기심 질문: \"40년 동안 매일 아침 먹은 하늘 양식의 이름이 왜 명사가 아니라 '이게 뭐야?(만 후)'라는 의문문으로 굳어졌을까?\"\n• 행간의 진실 & 스토리텔링: 아침 이슬이 마른 뒤 광야 지면에 하얗고 둥근 서리 같은 것이 깔려 있는 것을 본 이스라엘 백성들은 서로 쳐다보며 히브리어로 \"만 후?(מָן הוּא — 이것이 무엇이냐?)\"(출 16:15)라고 물었습니다. 왜냐하면 세상의 그 어떤 백과사전이나 경험으로도 설명할 수 없는 하늘로부터 내려온 초자연적 은혜였기 때문입니다! 그래서 그 양식의 이름이 아예 '만나(이게 뭐지?)'가 되었습니다. 만나는 갓 거두었을 때는 '꿀 섞은 과자 같고 기름 섞은 과자 맛'(출 16:31; 민 11:8)이 났으며, 부자나 가난한 자나 똑같이 하루 한 오멜(약 2.2리터)씩만 거두어야 했고 욕심부려 남겨두면 벌레가 생기고 냄새가 났습니다(단 안식일 전날 거둔 두 배의 만나는 상하지 않음!). 이는 \"하나님의 은혜는 어제 비축해 둔 것으로 사는 것이 아니라, 매일 아침 새벽이슬과 함께 무릎 꿇어 거두는 생명의 떡(예수 그리스도, 요 6:35)\"임을 40년간 체득하게 하신 훈련이었습니다.\n• 구속사 묵상 & 시각화: 새벽이슬 맺힌 시내 광야 모래 위에 하얀 고수씨처럼 내려앉은 만나를 소쿠리에 거두는 백성들과 항아리(오멜)에 담긴 만나.",
