    "hook": "안식년이 되어 자유인이 될 수 있는데도 주인을 사랑하여 평생 종으로 남겠다고 할 때 왜 하필 문설주에서 귀를 뚫었을까?",
    "visualGuide": "유월절 피가 발렸던 집 문설주 기둥에 귀를 대고 사랑의 자원 종이 되는 히브리 종과 십자가 못 자국의 오버랩",
    "dossierMd": "■ B048 | 왜 율법을 어기고 주인에게 종살이하던 히브리 종이 '나는 주인을 사랑하여 자유케 되지 않겠노라' 할 때 문설주에 대고 '송곳으로 귀를 뚫었을까'?\n• 시대·테마: 구약 03_출애굽·광야 | T02_문화·관습 · T08_구속사·모형\n• 본문: 출 21:2~6 (참조: 신 15:16~17, 시 40:6, 빌 2:7) | 삼각 연동: 인물 P009(모세), P026(예수 그리스도) | 사건 E013(시내산 언약과 율법 수여)\n• 호기심 질문: \"안식년(7년째)이 되어 자유의 몸으로 나갈 수 있는데도 주인과 처자를 사랑하여 평생 종으로 남겠다고 자원할 때, 왜 하필 '문설주'에 대고 '귀'를 송곳으로 뚫었을까?\"\n• 행간의 진실 & 스토리텔링: 출애굽기 21장 5~6절의 이 법은 성경의 종(노예) 개념을 완전히 뒤바꾸는 '사랑의 자원 종(Bondservant of Love)' 규례입니다. 6년간 빚 때문에 의무로 일한 종은 7년째에 공짜로 자유인이 됩니다. 그러나 주인의 인자함과 주인이 준 아내와 자녀들을 너무나 사랑하여 \"나는 내 주인과 내 처자를 사랑하니 자유인이 되지 않겠노라\" 선언하면, 재판장 앞에서 주인이 그를 데리고 집 문설주(유월절 어린양의 피를 발랐던 바로 그 기둥!)에 세우고 송곳으로 그의 귓바퀴를 뚫었습니다. 왜 하필 '귀'를 뚫었을까요? 구약에서 귀를 뚫는다는 것은 \"이제부터 내 귀는 오직 사랑하는 주인의 음성만 듣고 순종하겠습니다\"라는 영원한 헌신의 표식이었습니다! 시편 40편 6절에서 메시아는 \"주께서 내 귀를 파셨나이다(뚫으셨나이다)\"라고 고백하셨고, 하늘 보좌의 자유를 버리시고 하나님 아버지와 신부 된 우리(처자)를 너무나 사랑하사 스스로 종의 형체를 입으시고 십자가 나무 기둥에 손과 발을 뚫리신 분이 바로 예수 그리스도이십니다.\n• 구속사 묵상 & 시각화: 나무 문설주 앞에서 인자한 주인을 바라보며 기꺼이 귀를 대는 종과, 그 위에 겹쳐지는 십자가 못 자국의 구속사적 오버랩.",
