    "dossierMd": "■ B049 | 대제사장 아론의 흉패 속 '우림과둠밈'은 어떻게 하나님의 'Yes / No' 응답을 보여주었을까?\n• 시대·테마: 구약 03_출애굽·광야 | T04_사물·생활사 · T01_원어·언어유희\n• 본문: 출 28:30, 민 27:21, 삼상 14:41 | 삼각 연동: 인물 P010(아론), P237(엘르아살) | 사건 E014(성막 봉헌)\n• 호기심 질문: \"대제사장의 가슴 판결 흉패 주머니 안에 넣었던 '우림(Urim)'과 '둠밈(Thummim)'은 무엇이었으며 어떤 원리로 작동했을까?\"\n• 행간의 진실 & 스토리텔링: 히브리어로 '우림(אוּרִים)'은 히브리어 알파벳 첫 글자 알렙(א)으로 시작하며 \"빛들(Lights)\"이라는 뜻이고, '둠밈(תֻּמִּים)'은 히브리어 알파벳 마지막 글자 타우(ת)로 시작하며 \"완전함들 / 진리들(Perfections / Truth)\"이라는 뜻입니다! 즉, 우림과 둠밈은 알렙(א)부터 타우(ת, 헬라어 알파와 오메가)까지 하나님의 완전하신 빛과 진리를 상징하는 두 개의 성스러운 보석(또는 흰 돌과 검은 돌)이었습니다. 사무엘상 14장 41절(70인역 본문)을 보면 사울 왕이 \"여호와여 허물이 내게 있거든 우림을 주시고 백성에게 있거든 둠밈을 주소서\"라고 기도하는 장면이 나옵니다. 국가적 중대사 앞에서 대제사장이 판결 흉패 안에 손을 넣어 꺼내거나 보석에 빛이 발하는 방식으로 하나님의 뜻을 분별했으며, 오늘날에는 참된 빛과 진리(우림과 둠밈)이신 성경 말씀과 성령님이 우리 가슴의 판결 흉패가 되어 주십니다.\n• 구속사 묵상 & 시각화: 12지파 보석이 박힌 대제사장의 금빛 판결 흉패와 그 안주머니에서 영롱한 빛을 내는 두 보석 우림(빛, א)과 둠밈(완전함, ת).",
