    "hook": "왜 성경은 '염소 새끼를 그 어미의 젖으로 삶지 말라'는 계명을 세 번이나 거듭 명령하셨을까?",
    "visualGuide": "라스 샤므라(우가릿) 가나안 주술 점토판과 대조되는 어미 염소 품에서 평화롭게 젖을 먹는 새끼 염소",
    "dossierMd": "■ B050 | 왜 염소 새끼를 '그 어미의 젖으로 삶지 말라'는 계명이 구약성경에 세 번이나 반복될까? — 가나안 풍요 주술 배격\n• 시대·테마: 구약 03_출애굽·광야 | T02_문화·관습 · T06_역사·고고학\n• 본문: 출 23:19, 34:26, 신 14:21 | 삼각 연동: 인물 P009(모세) | 사건 E013(시내산 언약과 율법)\n• 호기심 질문: \"오늘날 유대인들이 고기와 치즈(유제품)를 함께 먹지 않는 코셔(Kosher) 식단의 기원이 된 '염소 새끼를 어미의 젖으로 삶지 말라'는 법의 원래 배경은 무엇이었을까?\"\n• 행간의 진실 & 스토리텔링: 1929년 시리아 북부 라스 샤므라(고대 우가릿, Ugarit) 유적에서 발굴된 기원전 14세기 가나안 신화 점토판에 의해 이 법의 고고학적 배경이 드러났습니다. 우가릿 점토판에는 가나안 사람들이 봄철 농사의 다산과 풍요를 빌기 위해 바알과 아세라 신에게 드리는 주술 의식으로 \"새끼 염소를 그 어미의 젖에 삶아 그 국물을 밭과 과수원에 뿌리는 의식\"이 기록되어 있었습니다! 하나님께서 보시기에 새끼에게 생명을 먹여 살려야 할 '어미의 젖'으로 그 새끼를 삶아 죽이는 행위는 생명의 질서를 모독하는 잔인한 역설이자 가나안의 주술적 탐욕이었습니다. 그래서 하나님은 이스라엘 백성들에게 가나안의 다산 주술을 철저히 금하시고, 생명을 주신 분의 질서와 긍휼을 식탁에서부터 기억하라고 세 번이나 거듭 명령하신 것입니다.\n• 구속사 묵상 & 시각화: 고대 우가릿 설형문자 점토판과 어미 염소 품에서 평화롭게 젖을 먹는 아기 염소의 따뜻한 생명 중심 일러스트.",
