    "dossierMd": "■ B051 | 모세가 광야에서 높이 매단 '놋뱀(구리 뱀)' — 왜 죄를 상징하는 뱀을 불을 통과한 놋(청동)으로 만들어 장대에 달았을까?\n• 시대·테마: 구약 03_출애굽·광야 | T08_구속사·모형 · T01_원어·언어유희\n• 본문: 민 21:4~9 (참조: 요 3:14~15, 고후 5:21, 왕하 18:4) | 삼각 연동: 인물 P009(모세), P026(예수 그리스도), P043(히스기야) | 사건 E050(불뱀 사건과 장대 위 놋뱀)\n• 호기심 질문: \"십계명 제2계명에서 아무 형상이든지 만들지 말라고 하신 하나님이, 왜 민수기 21장에서는 직접 놋뱀을 만들어 장대 위에 달라고 명령하셨을까?\"\n• 행간의 진실 & 스토리텔링: 원망하다 불뱀에 물려 죽어가는 백성들을 살리기 위해 하나님은 불뱀을 없애주신 것이 아니라, 불뱀 모양을 '놋(네호쉐트 — 심판의 불을 견뎌내는 청동)'으로 만들어 장대(네스 — 군대 깃발) 위에 높이 매달고 그것을 쳐다보는 자마다 살리라고 하셨습니다(히브리어로 뱀 나하쉬와 놋 네호쉐트는 같은 자음 어근 N-Ch-Sh를 공유하는 강렬한 언어유희!). 왜 하필 저주의 상징인 '뱀'의 모양을 달았을까요? 예수님이 니고데모에게 친히 해석해 주셨듯(요 3:14 \"모세가 광야에서 뱀을 든 것같이 인자도 들려야 하리니\"), 죄가 전혀 없으신 예수님이 십자가 장대 위에서 우리를 대신하여 '죄와 저주 덩어리(고후 5:21 죄로 삼으심)'가 되어 심판의 불(놋)을 다 받으셨기 때문입니다! 독이 몸에 퍼져 손가락 하나 움직일 힘도 없는 죄인이라도, 장대 위에 달리신 주님을 '믿음으로 쳐다보기만 하면(히브리어 히비트 — 소망을 품고 응시하면)' 즉시 살아납니다. (단, 700년 뒤 이스라엘 백성들이 구원자 하나님 대신 그 놋뱀 조각 자체를 우상 숭배하자 히스기야 왕이 '느후스단(그건 그냥 놋 조각일 뿐이다!)'이라며 과감히 부숴버렸습니다 — 왕하 18:4).\n• 구속사 묵상 & 시각화: 시내 광야 진영 한가운데 높이 세워진 나무 장대(네스) 위의 붉은 청동 뱀을 천막 문 앞에서 간절히 올려다보며 나음을 입는 백성들.",
