    "visualGuide": "포도원 좁은 담 사이에서 불칼을 든 여호와의 사자를 보고 주저앉은 나귀와 눈이 가려진 채 지팡이를 든 발람",
    "dossierMd": "■ B052 | 발람의 나귀가 입을 열어 말할 때, 왜 선지자 발람은 나귀가 말을 한다는 사실에 전혀 놀라지 않고 나귀와 말싸움을 했을까?\n• 시대·테마: 구약 03_출애굽·광야 | T03_행간·인물관계 · T01_원어·언어유희\n• 본문: 민 22:22~35 (참조: 벧후 2:15~16) | 삼각 연동: 인물 P235(발람), P310(발락) | 사건 E051(발락과 발람의 저주 실패)\n• 호기심 질문: \"자기가 타고 가던 나귀가 사람 말로 '내가 당신에게 무엇을 하였기에 나를 이같이 세 번을 때리느냐?'라고 물으면 기절초풍해야 정상인데, 발람은 왜 아무렇지도 않게 '네가 나를 거역하기 때문이다!'라고 대꾸했을까?\"\n• 행간의 진실 & 스토리텔링: 민수기 22장 28~30절의 이 블랙코미디 같은 장면은 탐욕과 분노에 눈이 먼 인간의 영적 맹목성을 가장 날카롭게 고발하는 성경의 해학입니다! 모압 왕 발락이 약속한 '금은이 가득한 집'과 고관대작의 뇌물에 눈이 뒤집힌 주술사 발람은, 말 못하는 나귀조차 단번에 본 '칼을 빼어 손에 들고 길에 서신 여호와의 사자'를 전혀 보지 못했습니다. 심지어 나귀가 입을 열어 사람의 말로 항변하는데도, 탐욕과 혈기에 사로잡힌 발람은 그것이 초자연적 경고라는 사실조차 인지하지 못한 채 나귀와 말다툼을 벌였습니다! 베드로후서 2장 16절은 이를 두고 \"말 못하는 나귀가 사람의 소리로 말하여 이 선지자의 미친 행동을 저지하였느니라\"고 일갈합니다. 욕심에 눈이 멀면 영적 지도자라도 짐승보다 둔해질 수 있다는 엄중한 비하인드입니다.\n• 구속사 묵상 & 시각화: 좁은 포도원 담장 사이에서 불칼을 든 여호와의 사자를 보고 주저앉은 나귀와, 눈이 가려진 채 지팡이를 치켜든 발람의 극적 대비.",
