    "title": "요단강이 가장 거세게 범람하는 '보리 추수 철(만년설 해빙기)'에 제사장의 발이 먼저 물에 잠길 때 '아담(Adam) 성읍'에서 끊어진 물줄기!",
    "origTitle": "Crossing the Flooded Jordan at Harvest Time as the Waters Stood Up at the City of Adam",
    "scriptures": "수 3:14~17",
    "hook": "왜 하나님은 요단강이 얕은 건기가 아니라 강둑에 물이 철철 넘치는 보리 추수 범람기에 건너게 하셨으며 왜 상류 '아담' 성읍에서 물이 끊어졌을까?",
    "visualGuide": "언약궤를 멘 제사장의 발이 범람하는 요단강 물에 먼저 잠기는 순간 상류 아담 성읍에서 물벽이 서는 장면",
    "dossierMd": "■ B053 | 왜 이스라엘 백성이 요단강을 건널 때 강물이 가장 잔잔한 건기가 아니라, 강둑에 물이 철철 넘치는 '보리 추수 철(우기 범람기)'에 건너게 하셨을까?\n• 시대·테마: 구약 04_가나안정복·사사 | T05_지리·생태 · T08_구속사·모형\n• 본문: 수 3:14~17 | 삼각 연동: 인물 P114(여호수아) | 사건 E052(요단강 도하와 길갈 할례)\n• 호기심 질문: \"평소 폭이 20~30m에 불과한 요단강이 봄철 보리 추수기에는 왜 폭 1km가 넘는 급류로 변하며, 왜 하나님은 언약궤를 멘 제사장들이 먼저 발을 잠글 때까지 물을 가르지 않으셨을까?\"\n• 행간의 진실 & 스토리텔링: 여호수아 3장 15절은 괄호 설명처럼 중요한 지리적 배경을 박아 넣습니다 — \"요단이 곡식 거두는 시기에는 항상 언덕에 넘치더라!\" 매년 3~4월(유월절·보리 추수기)이 되면 북쪽 헤르몬산(해발 2,814m)의 만년설이 녹아내리고 봄비가 겹치면서, 평소에는 걸어서도 건널 수 있던 얕은 요단강이 수심 3~4m, 강폭 수백 미터의 황톳빛 성난 급류로 돌변합니다! 하나님은 누구나 걸어 건널 수 있는 갈수기가 아니라 인간의 힘으로는 절대 건널 수 없는 최대 범람기에 요단강 앞에 서게 하셨습니다. 더구나 홍해 때는 모세가 지팡이를 내밀어 먼저 바다가 갈라진 것을 눈으로 보고 건넜지만(출 14:21~22), 요단강에서는 언약궤를 멘 제사장들의 발바닥이 넘실대는 범람하는 물가에 먼저 잠겼을 때에야(수 3:15~16) 상류 25km 지점의 아담(Adam) 성읍에서 물이 벽처럼 쌓여 끊어졌습니다! 이는 구속사의 의미심장한 원리입니다: '첫 사람 아담(Adam)'으로부터 흘러내려 오던 죽음의 강물이, 말씀이 육신이 되신 언약궤(예수 그리스도)가 요단강(죽음)에 발을 디디실 때 완전히 끊어진 것입니다!\n• 구속사 묵상 & 시각화: 헤르몬산 눈 녹은 물로 강둑까지 범람하는 거센 요단강 물결 속에 언약궤를 멘 제사장들의 발이 닿는 순간, 상류 아담 성읍 쪽으로 거대한 물벽이 서며 마른땅이 드러나는 장면.",
