    "dossierMd": "■ B054 | 기생 라합의 집 창문에 매단 '붉은 줄(티크바트 하샤니)' — 히브리어 '줄(티크바)'이 동시에 '소망'을 뜻하는 원어 언어유희\n• 시대·테마: 구약 04_가나안정복·사사 | T01_원어·언어유희 · T08_구속사·모형\n• 본문: 수 2:18, 2:21, 6:22~25 (참조: 마 1:5) | 삼각 연동: 인물 P237(라합), P114(여호수아), 살몬 | 사건 E015(여리고 성 함락과 라합 구원)\n• 호기심 질문: \"정탐꾼들이 라합에게 창문에 매달라고 한 '붉은 줄'의 히브리어 단어 '티크바(תִּקְוָה)'가 성경의 다른 곳에서는 왜 전부 '소망(Hope)'으로 번역될까?\"\n• 행간의 진실 & 스토리텔링: 여호수아 2장 18절과 21절에서 정탐꾼을 달아 내린 밧줄과는 다른 단어로 쓰인 '붉은 줄(티크바트 하샤니, תִּקְוַת הַשָּׁנִי)'에서 '티크바(Tikvah)'는 '팽팽하게 당겨진 줄/끈'이라는 어원에서 파생되어 히브리어에서 \"소망 / 희망(Hope)\"(시 62:5 \"나의 소망이 그로부터 나오는도다\", 오늘날 이스라엘 국가의 제목도 하티크바 HaTikvah — 그 소망!)을 뜻하는 단어입니다! 즉, 히브리어 원문으로 읽으면 라합이 성벽 창문에 매단 것은 단순한 붉은 밧줄이 아니라 \"홍색 실의 소망(The Scarlet Hope)\"이었습니다! 이중 성벽이 무너져 내리는 여리고의 심판 날에 오직 그 붉은 소망의 줄(출애굽 유월절 문설주의 피와 골고다 십자가 보혈의 연결고리)이 매달린 라합의 집만 무너지지 않았고, 이방 기생이었던 라합은 유다 지파의 족장 살몬과 결혼하여 보아스의 어머니(다윗 왕의 고조모, 예수 그리스도의 조상 — 마 1:5)가 되는 기적의 반전을 누렸습니다.\n• 구속사 묵상 & 시각화: 웅장한 여리고 이중 토성 외벽 창문 밖으로 선명하게 드리워진 진홍빛 굵은 삼겹 줄(티크바 — 소망의 붉은 줄).",
