    "title": "에발산과 그리심산 양편에서 울려 퍼진 축복과 저주 선포 — 세겜 골짜기의 천연 야외 원형극장 음향학과 에발산 여호수아 제단 발굴!",
    "origTitle": "Natural Amphitheater of Mount Gerizim and Mount Ebal & Joshua's Altar Excavation",
    "scriptures": "수 8:30~35; 신 27:11~13",
    "hook": "마이크도 없던 시대에 수십만 백성이 에발산과 그리심산에 나뉘어 서서 어떻게 골짜기 중앙의 율법 낭독 소리를 또렷이 들었을까?",
    "visualGuide": "천연 원형극장 지형을 이룬 에발산·그리심산 협곡과 아담 제르탈 교수가 발굴한 에발산의 다듬지 않은 자연석 제단",
    "dossierMd": "■ B055 | 여호수아가 여리고를 점령한 직후, 왜 비옥한 성읍을 차지하지 않고 에발산과 그리심산으로 올라가 율법 낭독 예배를 드렸을까? — 세겜 골짜기의 천연 원형극장 음향학\n• 시대·테마: 구약 04_가나안정복·사사 | T05_지리·생태 · T06_역사·고고학\n• 본문: 수 8:30~35 (참조: 신 27:11~13) | 삼각 연동: 인물 P114(여호수아) | 사건 E053(아이성 전투와 에발산·그리심산 축복과 저주 선포)\n• 호기심 질문: \"마이크도 확성기도 없던 시대에 수십만 명의 백성이 에발산과 그리심산 양편에 나뉘어 서서 어떻게 골짜기 중앙에서 읽는 율법 소리를 또렷이 들을 수 있었을까?\"\n• 행간의 진실 & 스토리텔링: 세겜 협곡을 사이에 두고 북쪽의 민둥바위 산인 에발산(저주 선포, 르우벤·갓·아셀·스불론·단·납달리 6지파)과 남쪽의 푸른 나무가 자라는 그리심산(축복 선포, 시므온·레위·유다·잇사갈·요셉·베냐민 6지파)이 마주 보고 있는 지형은, 양쪽 산비탈이 오목하게 파여 소리가 공명하는 세계 최대의 천연 야외 원형극장(Natural Amphitheater) 구조를 이루고 있습니다! 실제로 현대 음향학자들과 성서지리학자들이 골짜기 중앙에서 육성으로 성경을 낭독하는 실험을 한 결과, 양쪽 산 중턱까지 음성이 메아리 없이 선명하게 전달되는 것이 확인되었습니다. 또한 1980년대 고고학자 아담 제르탈(Adam Zertal) 교수가 에발산 북동쪽 사면에서 여호수아 시대(초기 철기 1기)의 다듬지 않은 자연석과 경사로(계단 없는 제단, 출 20:25~26 규례 일치!)로 지어진 대형 제단 유적과 정결한 제물(어린 숫양·숫염소·소)의 탄화된 뼈를 발굴하여 성경 기록의 역사성을 생생히 입증했습니다.\n• 구속사 묵상 & 시각화: 에발산과 그리심산 양쪽 사면에 6지파씩 마주 서고, 골짜기 중앙 언약궤 앞에서 율법책을 낭독하는 여호수아와 에발산의 다듬지 않은 돌 제단.",
