    "hook": "이름 뜻이 '오른손의 아들'인 베냐민 지파 에훗의 오른손 장애(왼손잡이)가 어떻게 모압 왕궁 경호원들의 몸수색을 뚫는 비밀병기가 되었을까?",
    "visualGuide": "오른쪽 허벅지 옷 속에서 한 규빗 양날 단검을 왼손으로 뽑아 드는 사사 에훗",
    "dossierMd": "■ B056 | 왜 사사 에훗은 '왼손잡이'였고, 모아브 왕 에글론은 에훗이 칼을 뽑을 때 의자에서 벌떡 일어났다가 찔렸을까?\n• 시대·테마: 구약 04_가나안정복·사사 | T01_원어·언어유희 · T02_문화·관습\n• 본문: 삿 3:15~25 | 삼각 연동: 인물 P240(에훗), 에글론 | 사건 E054(옷니엘·에훗·삼갈 초기 사사들의 구원)\n• 호기심 질문: \"이름 자체가 '오른손의 아들(벤-야민)'인 베냐민 지파 사람 에훗이 왜 '오른손이 묶인 자(왼손잡이)'였으며, 그 핸디캡이 어떻게 구원의 비밀병기가 되었을까?\"\n• 행간의 진실 & 스토리텔링: 사사기 3장 15절에서 '왼손잡이'로 번역된 히브리어 원어는 '이테르 야드 예미노(אִטֵּר יַד־יְמִינוֹ — 그의 오른손이 묶인/제한된 자)'입니다! 이름 뜻이 '오른손의 아들(베냐민)'인 지파에서 태어났는데 정작 오른손에 장애가 있거나 쓰지 못하는 왼손잡이였다는 것은 당대 사회에서 큰 결핍이자 약점이었습니다. 그러나 하나님은 바로 그 약점을 들어 쓰셨습니다! 고대 근동의 모든 전사는 오른손으로 칼을 뽑기 때문에 칼집을 왼쪽 허리에 찼고, 왕궁 경호원들도 방문객의 왼쪽 허리만 몸수색했습니다. 그러나 왼손잡이 에훗은 한 규빗(약 45cm)짜리 양날 단검을 오른쪽 허벅지 옷 속에 숨겨 경호원들의 수색을 감쪽같이 통과했습니다. 그리고 비둔한 모압 왕 에글론(이름 뜻: '살찐 송아지')에게 \"왕이여, 내가 은밀히 아뢸 하나님의 말씀이 있나이다\"(삿 3:20)라고 말하자, 이방 왕조차 신의 신탁을 서서 듣는 고대 궁정 예법에 따라 무거운 몸을 이끌고 보좌에서 일어섰고, 그 무방비 순간에 에훗의 왼손이 번개같이 구원을 이루었습니다. 하나님 앞에서는 나의 핸디캡이 곧 하나님의 비밀병기입니다.\n• 구속사 묵상 & 시각화: 서늘한 다락방에서 오른쪽 허벅지 옷자락 속에서 양날 단검을 뽑아 드는 왼손잡이 사사 에훗.",
