    "dossierMd": "■ B057 | 사사 드보라의 승전가에 기록된 야엘의 무기 — 왜 시스라 장군에게 물 대신 '엉긴 젖(요거트)'을 주고 '장막 말뚝'으로 관자놀이를 박았을까?\n• 시대·테마: 구약 04_가나안정복·사사 | T02_문화·관습 · T08_구속사·모형\n• 본문: 삿 4:18~21, 5:24~27 | 삼각 연동: 인물 P014(드보라), P249(바락), P249(야엘), P315(시스라) | 사건 E055(드보라와 바락의 기손강 승리와 야엘)\n• 호기심 질문: \"철 병거 900대를 거느렸던 무적의 장군 시스라가 왜 평범한 유목민 여인 야엘의 천막 안에서 속수무책으로 잠들어 죽음을 맞이했을까?\"\n• 행간의 진실 & 스토리텔링: 고대 베두인 유목민 사회에는 두 가지 철칙이 있었습니다. 첫째, 여인의 내실 천막에는 남편 외에 어떤 외부 남성도 함부로 들어올 수 없었기에 도망자 시스라는 가장 안전한 은신처로 여겨 야엘의 장막에 숨어들었습니다. 둘째, 시스라가 \"물을 조금 달라\"고 했을 때 야엘은 물 대신 가죽 부대를 열어 귀빈 대접용 '엉긴 젖(헤마 — 유목민 전통 발효 산양유/버터밀크)'(삿 4:19; 5:25)을 대접에 담아 주었습니다. 전쟁터에서 극도로 긴장하고 탈진한 상태에서 트립토판과 지방이 풍부한 이 발효유를 단숨에 들이켠 시스라는 순식간에 깊은 숙면에 빠졌습니다. 그리고 고대 유목민 사회에서 천막을 세우고 거센 사막 바람에 날아가지 않도록 나무 말뚝(야테드)을 방망이로 땅에 박는 일은 전적으로 여인들의 일상이자 가장 익숙한 숙련 노동이었습니다! 칼 한 번 잡아본 적 없는 여인 야엘은 자신이 매일 쓰던 가장 평범한 살림 도구(장막 말뚝과 방망이)로 가나안 적장의 '머리(관자놀이)'를 깨뜨려, 창세기 3장 15절(\"여자의 후손이 뱀의 머리를 상하게 할 것\")의 구속사적 승리를 예표했습니다.\n• 구속사 묵상 & 시각화: 검은 유목민 천막 안, 귀빈용 주발(엉긴 젖)과 나무 장막 말뚝·방망이를 손에 쥔 여인 야엘과 밖으로 보이는 기손강 폭우.",
