    "title": "형제 70명을 한 바위 위에서 죽인 아비멜렉이 세겜 성에 '소금을 뿌린' 이유와 데베스 망대 여인이 던진 '맷돌 위짝(한 돌)'의 심판",
    "origTitle": "Abimelech Sowing Shechem with Salt and Crushed by an Upper Millstone at Thebez",
