    "hook": "한 바위 위에서 형제 70명을 죽인 아비멜렉이 왜 마지막에 한 여인이 던진 가정용 맷돌 위짝 하나에 두개골이 깨져 죽었을까?",
    "visualGuide": "무너진 세겜 성터에 뿌려진 저주의 소금과 데베스 망대 위에서 떨어진 둥근 현무암 손맷돌 위짝(레하임)",
    "dossierMd": "■ B059 | 기드온의 아들 아비멜렉이 세겜 사람들에게 '소금을 뿌린' 이유와 맷돌 위짝에 맞아 죽은 수치\n• 시대·테마: 구약 04_가나안정복·사사 | T02_문화·관습\n• 본문: 삿 9:45, 9:53~54 | 삼각 연동: 인물 P242(아비멜렉), P041(요담) | 사건 E056(아비멜렉의 찬탈과 요담의 가시나무 우화)\n• 호기심 질문: \"아비멜렉은 왜 세겜 성을 헐고 그 땅에 '소금'을 뿌렸으며, 왜 데베스 망대 아래에서 여인이 던진 '맷돌 위짝'에 두개골이 깨지자 급히 병기 든 소년에게 자기를 찔러달라고 했을까?\"\n• 행간의 진실 & 스토리텔링: 첫째, 고대 근동(앗수르와 헷 제국 비문)에서 반역한 성읍을 파괴한 뒤 그 터에 소금을 뿌리는 의식은 실제로 농작물이 못 자랄 만큼 소금을 수십 톤 뿌렸다는 뜻이 아니라, \"이 성읍은 사막의 소금 땅(염전)처럼 영구히 저주받아 다시는 사람이 살거나 재건되지 못할 것이다\"라는 상징적 저주 선포 의식이었습니다. 둘째, 한 바위 위에서 형제 70명을 돌로 쳐 죽였던 아비멜렉은 결국 데베스 망대 위에서 한 무명의 여인이 집에서 곡식을 갈던 '맷돌 위짝(케레브 레하임 — 손잡이가 달린 회전 상판 돌, 무게 약 10~15kg)'을 아래로 떨어뜨리자 정확히 한 개의 돌에 두개골이 깨져 죽었습니다(형제 70명을 한 돌 위에서 죽인 죄가 한 돌로 심판받음!). 고대 전사에게 가정주부의 가사 도구(맷돌)에 맞아 죽는 것은 사사 시스라가 야엘의 장막 말뚝에 죽은 것처럼 최고의 불명예였기에 부하에게 칼로 찔러달라 했으나, 성경은 끝까지 \"여인이 맷돌 위짝을 아비멜렉의 머리 위에 내려던져 그의 두개골을 깨뜨렸더라\"(삿 9:53; 삼하 11:21)고 기록해 교만한 자의 말로를 박제했습니다.\n• 구속사 묵상 & 시각화: 무너진 세겜 성터와 데베스 성 망대 위에서 떨어진 둥근 현무암 손맷돌 위짝(레하임).",
