    "visualGuide": "요단강 나루터 검문소와 히브리어 자음 신(שׁ 쉬)과 사멕(ס 스)의 고대 히브리 방언 음운학 비교 카드",
    "dossierMd": "■ B060 | 베냐민 지파와 에브라임 지파를 가른 요단강 나루터의 암호 — 왜 에브라임 사람들은 '쉽볼렛(Shibboleth)'을 발음하지 못하고 '십볼렛(Sibboleth)'이라 했을까?\n• 시대·테마: 구약 04_가나안정복·사사 | T01_원어·언어유희 · T06_역사·고고학\n• 본문: 삿 12:5~6 | 삼각 연동: 인물 P243(입다) | 사건 E057(입다의 암몬 승리와 에브라임 내전)\n• 호기심 질문: \"오늘날 영어 사전에도 '집단 구별 암호/방언'이라는 뜻의 단어로 등재된 '쉽볼렛(Shibboleth)' 사건은 어떤 고대 히브리어 방언 차이에서 비롯되었을까?\"\n• 행간의 진실 & 스토리텔링: 길르앗(요단 동편) 사람 입다가 암몬을 물리치자, 늘 패권을 주장하던 에브라임 지파(요단 서편)가 시비를 걸어 동족상잔이 벌어졌습니다. 패주하는 에브라임 군사들이 요단강 나루터를 건너 도망치려 할 때, 길르앗 사람들은 \"강물 / 곡식 이삭\"을 뜻하는 히브리어 단어 '쉽볼렛(שִׁבֹּלֶת, Shibboleth — 첫 자음 신 Shin שׁ, '쉬' 발음)'을 발음해 보라고 요구했습니다. 당시 요단 서편 에브라임 고원 지대 사람들의 방언에는 무성 후치경 마찰음인 [ʃ] (쉬) 발음이 없어서 모두 치경 마찰음인 [s] (스)로 발음하는 음운적 특징이 있었기에, 그들은 아무리 애를 써도 '십볼렛(סִבֹּלֶת, Sibboleth)'이라고밖에 발음하지 못해 그 자리에서 4만 2천 명이 발각되었습니다. 한 하나님을 섬기는 형제 지파가 방언 발음 하나 차이로 서로를 구별해 죽이는 사사 시대의 영적 비극을 적나라하게 보여주는 언어학 비하인드입니다.\n• 구속사 묵상 & 시각화: 요단강 여울목 나루터에서 창을 들고 검문하는 길르앗 병사들과 히브리어 글자 שׁ (Shin - 쉽볼렛) vs ס (Samekh - 십볼렛) 발음 대조 인포그래픽.",
