    "dossierMd": "■ B061 | 삼손이 젊은 사자의 시체 속에서 꿀을 떠먹은 행동이 왜 나실인 규례의 치명적 위반이자 수수께끼의 열쇠였을까?\n• 시대·테마: 구약 04_가나안정복·사사 | T02_문화·관습 · T04_사물·생활사\n• 본문: 삿 14:5~14 (참조: 민 6:3~7) | 삼각 연동: 인물 P016(삼손, P021 인근 사사 계열), P003(마노아), P317(들릴라) | 사건 E058(삼손의 탄생과 다곤 신전 최후 승리)\n• 호기심 질문: \"나실인이 지켜야 할 3대 절대 금기 사항을 삼손은 어떻게 하나씩 깨뜨렸으며, 죽은 사자 몸속에 정말 벌집이 생길 수 있을까?\"\n• 행간의 진실 & 스토리텔링: 민수기 6장 3~7절에 따른 나실인의 3대 규례는 ① 포도주와 독주 및 포도나무 소산 금지, ② 시체(죽은 것) 접촉 절대 금지, ③ 머리에 삭도를 대지 말 것이었습니다. 그런데 삼손은 첫째, 포도원이 있는 딤나로 내려가 블레셋 여인과 혼인 잔치(히브리어 미쉬테 — 문자 그대로 '술 마시는 연회'!)를 벌였고, 둘째, 자기가 찢어 죽인 사자의 시체(주검)에 손을 대어 그 몸속에 친 벌집에서 꿀을 떠먹고 부모에게까지 주었습니다(고온 건조한 팔레스타인 여름 기후에서는 사자 사체가 수일 내에 미라처럼 바짝 말라 가죽과 갈비뼈만 남는 공동이 형성되어 야생 꿀벌이 집을 짓기에 완벽한 공간이 됨!). 그리고 셋째, 마지막에는 들릴라의 무릎에서 머리카락까지 밀렸습니다. 그러나 나실인 서약을 세 번 다 깨뜨리고 두 눈이 뽑혀 맷돌을 돌리던 삼손이 마지막에 다곤 신전 두 기둥 사이에서 \"주 여호와여 구하옵나니 나를 생각하옵소서 하나님이여 구하옵나니 이번만 나를 강하게 하사...\"(삿 16:28)라고 회개하며 부르짖었을 때, 그의 힘이 돌아온 것은 머리카락이 다시 자라서가 아니라 깨어진 자리에서 다시 하나님을 찾은 회개의 기도 때문이었습니다.\n• 구속사 묵상 & 시각화: 다곤 신전의 두 중앙 돌기둥을 양손으로 밀어내며 하늘을 향해 마지막 기도를 올리는 삼손.",
