    "dossierMd": "■ [B075] 삼손이 나귀 턱뼈로 블레셋 천 명을 물리친 '라맛 레히'와 갈증 끝에 터져 나온 '엔학고레(부르짖는 자의 샘)'의 반전\n• 삿 15:14~19\nP016(삼손) · E058 | 삼손이 '신선한(트리아 — 갓 죽어 아직 마르지 않아 무겁고 단단한) 나귀 턱뼈' 하나로 블레셋 군사 천 명을 물리친 뒤 기고만장하여 \"나귀의 턱뼈로 한 더미, 두 더미를 쌓았음이여!\"(히브리어로 나귀 하모르와 더미 하모르가 완전 동음이의어인 말장난 노래!)라고 자만했습니다. 그러나 하나님이 그에게 극심한 목마름(갈증)을 허락하시자, 천하장사 삼손도 물 한 모금 없어 죽게 되었다며 \"내가 이제 목말라 죽어서 할례받지 못한 자들의 손에 떨어지겠나이다!\"라고 겸손히 부르짖었고, 그때 하나님이 우묵한 땅을 터뜨려 내신 샘이 바로 '엔학고레(부르짖는 자의 샘)'였습니다.",
