    "dossierMd": "■ B076 | 어린 사무엘을 부르신 밤, 성경은 왜 '하나님의 등불은 아직 꺼지지 아니하였으며'라는 구절을 굳이 넣었을까?\n• 시대·테마: 구약 05_통일왕국 | T04_사물·생활사 · T08_구속사·모형\n• 본문: 삼상 3:1~4 (참조: 출 27:20~21) | 삼각 연동: 인물 P019(사무엘), P246(엘리) | 사건 E059(한나의 기도와 사무엘의 소명)\n• 호기심 질문: \"사무엘상 3장 1~3절에서 엘리 제사장의 '눈이 점점 어두워가서 잘 보지 못하는 그때'와 성소의 '하나님의 등불은 아직 꺼지지 아니하였으며'가 나란히 기록된 이유는 무엇일까?\"\n• 행간의 진실 & 스토리텔링: 출애굽기 27장 20~21절 규례에 따르면 성소의 일곱 금 촛대 등불은 감람유를 채워 저녁부터 아침까지 밤새도록 꺼지지 않게 밝혀야 했고, 날이 밝기 직전인 새벽 4~5시경 기름이 다 타 들어가며 등불이 가물거리는 시간이 찾아왔습니다. 본문은 첫째로 하나님의 음성이 들린 시각이 동트기 직전 새벽녘이었음을 알려주며, 둘째로 훨씬 깊은 영적 메타포를 보여줍니다! 당시 이스라엘은 말씀이 희귀하고 엘리 제사장의 영안이 어두워져 영적 암흑기로 꺼져가고 있었지만, 언약궤 곁을 지키며 자던 한 소년 사무엘이라는 '하나님의 등불'이 아직 꺼지지 않고 남아 있었기에 새 시대의 새벽이 열릴 수 있었다는 감동적인 행간의 선언입니다.\n• 구속사 묵상 & 시각화: 실로 성소의 가물거리는 금 촛대 등불 아래, 언약궤 가까이에서 세마포 에봇을 입고 무릎 꿇어 귀 기울이는 어린 사무엘.",
