    "dossierMd": "■ B077 | 블레셋 다곤 신전에 끌려간 언약궤 앞에서, 왜 다곤 신상은 첫날엔 엎드러지기만 하더니 둘째 날엔 '머리와 두 손목이 끊어져 문지방에' 나뒹굴었을까?\n• 시대·테마: 구약 05_통일왕국 | T02_문화·관습 · T06_역사·고고학\n• 본문: 삼상 5:1~5 | 삼각 연동: 인물 P019(사무엘), P246(엘리) | 사건 E060(아벡 전투 언약궤 피랍과 다곤 신상 파손)\n• 호기심 질문: \"다곤 신상의 머리와 두 손목이 정확히 '문지방(마프탄)' 위에서 잘려 나간 사건은 고대 근동 전쟁 관습에서 무엇을 뜻했을까?\"\n• 행간의 진실 & 스토리텔링: 고대 근동(이집트 메디네트 하부 부조 및 앗수르 전쟁 벽화)에서 전쟁에서 승리한 왕은 적장의 머리를 베고 두 손목을 잘라 성문 문지방에 진열함으로써 \"이 적장은 지혜(머리)와 힘(두 손)을 완전히 상실하여 완전히 처형되었다\"는 것을 만천하에 공표했습니다! 블레셋 사람들은 전쟁에서 이겼다고 여호와의 언약궤를 전리품처럼 아스돗 다곤 신전에 갖다 놓았으나, 첫날 밤 다곤 신상은 여호와의 궤 앞에 코를 박고 경배하듯 쓰러졌고, 블레셋 사람들이 억지로 다시 세워 놓자 둘째 날 밤에는 하나님께서 고대 근동 전쟁법 그대로 다곤 신상의 머리와 두 손목을 잘라 신전 문지방 위에 던져 놓으심으로 누가 진짜 승리자이신지를 보여주셨습니다. (이 일 때문에 블레셋 제사장들은 다곤의 잘린 머리와 손목이 닿았던 문지방을 발로 밟지 못하고 폴짝 뛰어넘어 들어가는 미신적 관습이 생겼고, 훗날 스바냐 1:9은 이를 본뜬 유다의 우상 숭배자들을 '문지방을 뛰어넘는 자들'이라며 책망했습니다!).\n• 구속사 묵상 & 시각화: 아스돗 다곤 신전 한복판에서 황금빛으로 빛나는 여호와의 언약궤와, 그 앞 문지방 위에 머리와 양 손목이 부러진 채 엎드러진 거대 석조 다곤 신상.",
