    "dossierMd": "■ B078 | 왜 사울 왕은 아말렉 왕 아각을 살려두고 길갈이 아닌 갈멜에 '자기를 위하여 기념비(야드)'를 세웠을까?\n• 시대·테마: 구약 05_통일왕국 | T01_원어·언어유희 · T03_행간·인물관계\n• 본문: 삼상 15:12, 삼하 18:18 | 삼각 연동: 인물 P020(사울), P019(사무엘), P256(압살롬) | 사건 E062(사울의 아말렉 진멸 불순종과 버림받음)\n• 호기심 질문: \"사울 왕이 갈멜에 세운 '기념비'와 압살롬이 왕의 골짜기에 세운 '기념비'가 히브리어 원문에서는 왜 둘 다 똑같이 '손(야드, יָד)'이라는 단어로 기록되어 있을까?\"\n• 행간의 진실 & 스토리텔링: 사무엘상 15장 12절에서 사울이 자기를 위하여 세운 '기념비'의 히브리어 원어는 '야드(יָד — 손 / 능력 / 기념비)'입니다! 고대 가나안과 페니키아에서는 왕이나 장군이 자신의 공적을 과시하기 위해 돌기둥 위에 커다란 '손바닥 모양'을 새긴 전승비를 세워 \"내 손(야드)의 힘으로 이 승리를 이루었다!\"라고 자랑했습니다. 하나님이 아말렉을 치게 하신 것인데, 사울은 하나님의 영광을 가로채어 '자기 손(야드)의 공적비'를 세운 것입니다! 훗날 다윗을 반역한 압살롬 역시 아들이 없자 자기의 이름을 전하려고 왕의 골짜기에 비석을 세우고 '압살롬의 기념비(야드 압살롬 — 압살롬의 손)'(삼하 18:18)라 불렀습니다. 자기 이름과 자기 손(야드)의 기념비를 세우려 했던 사울과 압살롬은 둘 다 몰락했으나, 오직 하나님의 손에 붙들린 다윗의 집은 영원히 서게 되었습니다(놀랍게도 오늘날 예루살렘 홀로코스트 추모관의 이름 '야드 바셈(Yad Vashem)'은 사 56:5에서 하나님이 친히 세워주시는 '영원한 기념비(야드)와 이름(셈)'에서 유래했습니다!).\n• 구속사 묵상 & 시각화: 갈멜 언덕 위에 세워진 고대 근동 양식의 손바닥 문양 돌기둥(야드)과 사울의 찢어진 겉옷 자락을 붙잡은 사무엘.",
