    "visualGuide": "일시적인 왕조를 상징하는 작은 토기 기름병(팍)과 영원한 메시아 왕권을 상징하는 웅장한 숫양의 기름 뿔병(케렌) 대조도",
    "dossierMd": "■ B079 | 사무엘이 이새의 집에서 기름을 부을 때, 왜 사울에게는 '기름병(팍)'으로 붓고 다윗에게는 '기름 뿔병(케렌)'으로 부었을까?\n• 시대·테마: 구약 05_통일왕국 | T04_사물·생활사 · T08_구속사·모형\n• 본문: 삼상 10:1, 16:1, 16:13 (참조: 왕상 1:39) | 삼각 연동: 인물 P021(다윗), P020(사울), P019(사무엘) | 사건 E063(베들레헴 다윗의 기름부음)\n• 호기심 질문: \"사울과 예후는 깨지기 쉬운 질그릇 '기름병(팍)'으로 기름 부음을 받았는데, 왜 다윗과 솔로몬은 숫양의 뿔로 만든 '기름 뿔병(케렌)'으로 기름 부음을 받았을까?\"\n• 행간의 진실 & 스토리텔링: 성경의 단어 선택은 소름 돋을 만큼 정교합니다! 인간들의 요구로 세워진 초대 왕 사울(삼상 10:1)과 북이스라엘 심판 도구로 세워진 예후(왕하 9:1)에게 기름을 부을 때는 히브리어로 작고 깨지기 쉬운 질그릇 병인 '팍(פַּךְ, Flask/Vial)'을 썼습니다. 실제로 이 두 왕조는 질그릇처럼 일시적이었다가 깨어져 끝났습니다. 반면 하나님께서 친히 택하신 언약의 왕 다윗(삼상 16:1, 13)과 솔로몬(왕상 1:39)에게 기름을 부을 때는 성막에서 가져온 숫양의 뿔로 만든 '케렌(קֶרֶן, Horn — 뿔병, 구원의 뿔과 영원한 왕권의 상징!)'에 기름을 채워 부었습니다! 그래서 다윗과 세례 요한의 아버지 사가랴는 메시아를 찬양할 때마다 \"다윗의 집에 구원의 뿔(케렌 예슈아)을 일으키셨다\"(시 18:2; 눅 1:69)고 노래한 것입니다.\n• 구속사 묵상 & 시각화: 깨지기 쉬운 작은 토기 기름병(팍)과 대조되는, 감람유가 가득 담긴 웅장한 숫양의 기름 뿔병(케렌)으로 소년 다윗의 머리에 기름을 붓는 사무엘.",
