    "visualGuide": "이새 가문 가계도(막내아들 다윗과 큰누이 스루야의 세 아들 요압·아비새·아사헬이 또래 외삼촌-외조카 관계임을 보여주는 도표)",
    "dossierMd": "■ B080 | 다윗과 군대장관 요압은 왜 평생 서로를 버리지 못하는 애증의 관계였을까? — 다윗의 누이 '스루야의 세 아들(요압·아비새·아사헬)' 가계도 비하인드\n• 시대·테마: 구약 05_통일왕국 | T03_행간·인물관계\n• 본문: 대상 2:15~16, 삼하 2:18, 3:39, 19:22 | 삼각 연동: 인물 P021(다윗), P252(요압), 아비새, P264(아사헬) | 사건 E065(다윗의 헤브론 즉위와 통일왕국 완성)\n• 호기심 질문: \"사무엘하만 읽으면 요압이 다윗의 일반 부하 장수처럼 보이는데, 왜 요압은 다윗 왕에게 반말하듯 대들고 다윗도 \"스루야의 아들들이 나보다 강하도다\"라며 평생 요압을 처벌하지 못했을까?\"\n• 행간의 진실 & 스토리텔링: 역대상 2장 15~16절의 이새 가문 족보를 열어야 이 수수께끼가 풀립니다! 다윗에게는 '스루야(Zeruiah)'와 '아비가일'이라는 두 명의 누이(누나/이부누이)가 있었습니다. 그리고 바로 그 누이 스루야가 낳은 세 아들이 다윗 군대의 최고 핵심 3총사인 '요압 · 아비새 · 아사헬'이었습니다! 즉, 다윗은 외삼촌이고 요압·아비새·아사헬은 다윗의 친외조카였으며, 다윗이 여덟째 막내아들이었기 때문에 큰누나 스루야의 아들인 조카 요압과 아비새는 외삼촌 다윗과 나이가 거의 비슷한 또래였습니다! 아굴람 굴 시절부터 목숨을 걸고 외삼촌 다윗을 지킨 골육지친이자 개국 일등 공신 조카들이었기에, 요압이 아브넬과 압살롬과 아마사를 독단으로 죽이며 왕권을 위협해도 다윗은 차마 생전에 조카 요압을 직접 처단하지 못하고 탄식만 했던 것입니다.\n• 구속사 묵상 & 시각화: 이새 → 다윗(막내아들) & 스루야(누이) → 요압·아비새·아사헬(외조카 3형제) 가계도 관계망 인포그래픽.",
