    "hook": "두 발을 다 절며 자신을 '죽은 개 같은 나'라 부르던 사울의 손자 므비보셋이 왕의 식탁에 앉았을 때 식탁보 아래에서 일어난 은혜는 무엇일까?",
    "visualGuide": "다윗 왕궁의 화려한 식탁보 아래로 부러진 두 발이 가려진 채 왕자들과 동등하게 왕의 만찬을 나누는 므비보셋",
    "dossierMd": "■ B081 | 다윗은 왜 절뚝거리는 원수 가문의 손자 '므비보셋'을 죽이지 않고 평생 왕자들의 식탁에 앉혔을까? — 식탁보 아래 감춰진 두 다리\n• 시대·테마: 구약 05_통일왕국 | T02_문화·관습 · T08_구속사·모형\n• 본문: 삼하 9:1~13 (참조: 삼하 4:4) | 삼각 연동: 인물 P021(다윗), P255(므비보셋), P247(요나단) | 사건 E066(다윗 언약과 므비보셋을 향한 은총)\n• 호기심 질문: \"고대 왕조에서는 쿠데타의 씨앗을 없애려고 전임 왕가의 후손을 몰살하는 것이 상식이었는데, 왜 다윗은 사울의 손자이자 요나단의 아들 므비보셋을 수소문해 왕의 식탁에 앉혔을까?\"\n• 행간의 진실 & 스토리텔링: 다섯 살 때 사울과 요나단의 전사 소식을 들은 유모가 급히 안고 도망치다 떨어뜨려 두 발을 다 절게 된 므비보셋(삼하 4:4)은, 목초지조차 없는 황량한 광야 마을 '로드발(Lo-debar — 말씀도 없고 목초도 없는 불모지)'에 숨어 언제 다윗에게 발각되어 죽을까 공포에 떨며 살았습니다. 그러나 다윗이 그를 찾은 이유는 심판이 아니라 '요나단과 맺은 언약 때문에 하나님의 은총(헤세드)을 베풀기 위해서'(삼하 9:1, 3)였습니다! 스스로를 \"죽은 개 같은 나\"(8절)라고 부르던 므비보셋을 다윗은 예루살렘 궁으로 데려와 \"내 상에서 항상 떡을 먹으리라\"(10, 13절) 선언했습니다. 왕의 식탁보 아래로 들어가면 잘생긴 압살롬 왕자의 건강한 다리나 므비보셋의 부러져 뒤틀린 두 다리나 모두 왕의 식탁보에 똑같이 가려져 보이지 않고 오직 왕의 아들의 얼굴만 보입니다! 죄로 인해 영적 두 다리가 부러져 로드발에서 떨던 우리를, 예수 그리스도와의 언약 때문에 하나님의 자녀 식탁에 앉히시고 우리의 모든 허물을 은혜의 식탁보로 덮어주신 복음의 결정판입니다.\n• 구속사 묵상 & 시각화: 화려한 다윗 왕궁의 만찬 식탁, 식탁보 아래로는 절뚝거리는 두 발이 가려진 채 왕자들과 나란히 앉아 다윗 왕의 따뜻한 미소를 마주하는 므비보셋.",
