    "dossierMd": "■ B082 | 왜 다윗은 압살롬을 피해 울며 감람산으로 도망갈 때, 언약궤를 메고 따라온 사독 제사장에게 '언약궤를 도로 예루살렘으로 메어 가라!'고 돌려보냈을까?\n• 시대·테마: 구약 05_통일왕국 | T03_행간·인물관계 · T08_구속사·모형\n• 본문: 삼하 15:24~26 (참조: 삼상 4:3~11) | 삼각 연동: 인물 P021(다윗), P259(사독) | 사건 E068(압살롬의 반역과 다윗의 눈물의 피난길)\n• 호기심 질문: \"언약궤를 가지고 가면 백성들의 민심도 얻고 전쟁에 승리할 부적처럼 쓸 수 있었을 텐데, 왜 다윗은 눈물의 피난길에서 언약궤를 예루살렘 성소로 돌려보냈을까?\"\n• 행간의 진실 & 스토리텔링: 과거 엘리 제사장의 두 아들 홉니와 비느하스는 블레셋과의 전쟁에서 불리해지자 하나님의 뜻을 묻지도 않고 언약궤를 승리 보장용 부적처럼 전쟁터로 끌고 왔다가 언약궤도 빼앗기고 자신들도 전사했습니다(삼상 4장). 반면 다윗은 가장 절박한 순간에도 하나님을 자기의 정치적 도구로 이용하지 않았습니다! 그는 사독에게 이렇게 고백합니다: \"하나님의 궤를 성읍으로 도로 메어 가라! 만일 내가 여호와 앞에서 은혜를 입으면 도로 나를 인도하사 네게 그 궤와 그 계신 데를 보이시리라. 그러나 만일 그가 말씀하시기를 '내가 너를 기뻐하지 아니한다' 하시면 종이 여기 있사오니 선히 여기시는 대로 내게 행하시옵소서!\"(삼하 15:25~26). 상자(궤)를 내 손에 쥐어야 안심하는 미신이 아니라, 나를 버리시든 다시 세우시든 하나님의 절대 주권에 내 운명을 온전히 맡긴 참된 신앙이 다윗을 다시 예루살렘 보좌로 돌아오게 했습니다.\n• 구속사 묵상 & 시각화: 기드론 시내를 건너 감람산 비탈을 맨발로 오르는 다윗이 언약궤를 멘 사독과 레위인들에게 손을 들어 예루살렘 성으로 돌아가기를 명하는 숙연한 장면.",
