    "dossierMd": "■ [B096] 선지자 아모스가 자신을 소개하며 말한 '나는 목자요 뽕나무(돌무화과)를 재배하는 자(볼레스 쉬크밈)'의 진짜 직업 뜻은?\n• 암 7:14\nP076(아모스) · E083 | 아모스 7장 14절의 '뽕나무'는 누에가 먹는 뽕나무가 아니라 중동 저지대에서 자라는 야생 무화과인 '돌무화과나무(Sycamore fig, 히브리어 쉬크밈)'이며, '재배하는 자(볼레스)'는 정확히 \"돌무화과 열매에 칼집을 내는(꼬집는) 노동자\"라는 뜻입니다! 돌무화과 열매는 속에 기생 말벌이 들어 있어 그대로 두면 쓰고 먹을 수 없기 때문에, 수확 며칠 전에 인부가 일일이 나무에 올라가 손톱이나 철침으로 열매 하나하나에 상처(칼집)를 내어 에틸렌 가스를 배출시켜야만 비로소 달고 부드러운 열매로 익습니다. 가난한 농부들이나 하던 그 고된 일을 하던 아모스를 부르셔서, 하나님은 교만하고 쓴 북이스라엘의 심령에 말씀의 칼집을 내어 회개의 단 열매를 맺게 하셨습니다.",
