    "dossierMd": "■ [B118] 예레미야애가 1~4장은 왜 알파벳 순서(22절)로 쓰였다가 마지막 5장만 알파벳 순서가 깨진 22절로 끝날까?\n• 애 1~5장\nP072(예레미야) · E088 | 예루살렘 멸망의 피눈물을 노래한 예레미야애가 1장, 2장, 4장은 각 22절씩, 3장은 3배인 66절로 철저히 히브리어 알파벳 22글자(알렙~타우) 순서에 맞춘 답관체 조가(Elegy)입니다. 이는 \"우리의 슬픔과 고통을 알렙부터 타우까지 하나님 앞에 남김없이 다 쏟아놓는다\"는 뜻입니다. 그런데 마지막 5장은 절수는 똑같이 22절로 맞추면서도 알파벳 순서를 완전히 깨뜨렸습니다! 슬픔이 극에 달해 이제는 정형화된 시의 틀조차 유지할 수 없는 탄식이 터져 나오면서도, \"여호와여 우리를 주께로 돌이키소서\"(애 5:21)라는 기도로 나아가는 영적 진실성을 보여줍니다.",
