    "dossierMd": "■ [B119] 학개·말라기 시대에 백성들이 바친 '눈먼 것, 저는 것, 병든 것' — 왜 말라기는 '그것을 너희 총독에게 드려 보라!'고 일갈했을까?\n• 말 1:6~14\nP085(말라기) · E120 | 포로 귀환 후 100년이 지나자 매너리즘에 빠진 제사장들과 백성들은 흠 없는 제물은 자기 외양간에 남겨두고, 시장에 내다 팔 수도 없는 눈먼 양, 다리 저는 염소, 병든 가축을 성전 제단에 끌고 와 대충 때우듯 제사를 드렸습니다. 이에 하나님은 말라기를 통해 \"이제 그것을 너희 총독(페하 — 페르시아 파견 총독)에게 드려 보라 그가 너희를 기뻐하겠느냐?\"(말 1:8)라고 탄식하시며, 그토록 형식적이고 오염된 예배를 멈추게 하려고 차라리 \"너희가 내 제단 위에 헛되이 불사르지 못하게 하기 위하여 너희 중에 성전 문을 닫을 자가 있었으면 좋겠도다!\"(말 1:10)라고까지 말씀하셨습니다. 하나님이 원하시는 것은 제물의 개수가 아니라 예배자의 경외함입니다.",
