    "dossierMd": "■ [B120] 구약의 마지막 책 말라기에서 '만군의 여호와(예호와 체바오트)'라는 호칭이 유독 24번이나 폭발적으로 등장하는 이유\n• 말 1:4~4:6\nP085(말라기) · E120 | 불과 4장밖에 안 되는 짧은 말라기서에 '만군의 여호와(יְהוָה צְבָאוֹת — 하늘 천군천사와 온 우주 만물의 총사령관이신 여호와)'라는 호칭이 무려 24번(전체 절수의 절반 가까이에!) 반복됩니다. 당시 유다는 페르시아 대제국의 속주인 작고 초라한 변방 공동체였고 백성들은 \"하나님이 우리를 사랑하신 증거가 어디 있느냐?\"고 냉소했습니다. 바로 그때 구약 계시의 문을 닫으시며 하나님은, 비록 유다가 세상 제국 눈에는 작아 보여도 당신들의 하나님은 온 우주와 천군을 호령하시는 '만군의 여호와'이시며 반드시 '치료하는 광선을 비추는 의로운 해(메시아)'(말 4:2)를 보내실 분임을 각인시키고 신구약 중간기 400년의 침묵을 건너가게 하셨습니다.",
