    "dossierMd": "■ B121 | 요셉과 예수님의 직업 '목수(헬라어 텍톤, Τέκτων)' — 나무 의자를 깎는 목공이 아니라 '돌을 다듬는 석공·건축 장인'이었다!\n• 시대·테마: 신약 10_예수그리스도공생애 | T01_원어·언어유희 · T06_역사·고고학\n• 본문: 막 6:3, 마 13:55 | 삼각 연동: 인물 P026(예수 그리스도), P156(요셉) | 사건 E122(소년 예수님의 성전 방문과 나사렛 성장기)\n• 호기심 질문: \"나무가 귀하고 온통 석회암과 현무암 바위투성이인 1세기 갈릴리 나사렛에서, 예수님과 아버지 요셉의 직업인 헬라어 '텍톤(τέκτων)'은 실제로 무슨 일을 하는 사람이었을까?\"\n• 행간의 진실 & 스토리텔링: 헬라어 '텍톤(τέκτων — 영어 아키텍트 Architect의 어원!)'은 단순히 나무만 다루는 목수가 아니라, 석재(돌)와 목재를 모두 다루어 집과 성벽과 농기구를 짓는 '종합 건축 장인 / 석공(Stonemason & Builder)'을 뜻합니다! 실제로 1세기 갈릴리 가옥의 90% 이상은 나무가 아닌 현무암과 석회암 돌을 정으로 깎아 쌓고 지붕 들보와 문짝에만 나무를 썼습니다. 더구나 예수님이 자라나신 나사렛에서 북쪽으로 걸어서 단 1시간 거리(약 6km)에는 헤롯 안디바가 갈릴리 수도로 대대적인 신도시 건설 공사를 벌이던 '세포리스(Sepphoris)'가 있었는데, 요셉과 청년 예수님은 바로 그 현장에서 무거운 바위를 정으로 쪼고 다듬는 거친 노동으로 땀을 흘리셨습니다. 그래서 예수님의 비유와 말씀 속에는 유독 건축과 돌에 관한 생생한 전문 지식 — \"반석 위에 기초를 파고 집을 짓는 지혜로운 사람\"(마 7:24), \"망대를 세우려 할 때 먼저 비용을 계산함\"(눅 14:28), \"건축자들의 버린 돌이 모퉁이의 머릿돌이 되었나니\"(마 21:42) — 이 가득 녹아 있었던 것입니다!\n• 구속사 묵상 & 시각화: 나사렛 작업장에서 정과 망치로 흰 석회암 모퉁잇돌과 올리브나무 멍에를 다듬으시는 청년 예수님의 단단하고 굳은살 박인 손.",
