    "dossierMd": "■ B122 | 예수님이 말씀하신 '내 멍에는 쉽고 내 짐은 가벼우니라' — 갈릴리 장인이 맞추어 주는 '맞춤형 2인용 나무 멍에(크레스토스)'\n• 시대·테마: 신약 10_예수그리스도공생애 | T01_원어·언어유희 · T04_사물·생활사\n• 본문: 마 11:28~30 | 삼각 연동: 인물 P026(예수 그리스도) | 사건 E135(수고하고 무거운 짐 진 자들을 향한 초청)\n• 호기심 질문: \"소를 묶는 무거운 나무 기구인 '멍에(쥐고스)'가 어떻게 '쉽고 편할(크레스토스)' 수가 있을까?\"\n• 행간의 진실 & 스토리텔링: 마태복음 11장 30절의 \"내 멍에는 쉽고(크레스토스, χρηστός)\"에서 헬라어 크레스토스의 정확한 뜻은 \"몸의 굴곡에 딱 맞게 정교하게 깎아 맞추어져 살이 까지지 않는(Well-fitting / Tailored)\"이라는 뜻입니다! 고대 이스라엘에서는 어린 소에게 밭 갈기를 가르칠 때 혼자 1인용 멍에를 메게 하지 않고, 힘세고 노련한 어미 소(고참 소)와 나란히 묶는 '2인용 쌍멍에'를 씌웠습니다. 이때 무거운 쟁기 하중은 덩치 큰 노련한 소가 90% 이상 다 끌고, 옆에 묶인 어린 소는 그저 어미 소의 보폭에 맞춰 나란히 걷기만 하면 되었습니다! 최고의 목수(텍톤)이신 예수님이 \"나의 멍에를 메고 내게 배우라\" 하신 것은, \"네가 혼자 바리새인의 율법 멍에를 메고 피 흘리지 말고, 내가 네 어깨 치수에 딱 맞게 깎아 놓은 쌍멍에 옆자리로 들어오라! 무거운 인생의 짐은 옆에서 내가 다 끌고 갈 테니 너는 나와 보폭만 맞추어 걸어가자!\"라는 가장 다정한 동행의 초청이었습니다.\n• 구속사 묵상 & 시각화: 소의 어깨선에 꼭 맞게 매끄럽게 깎은 2인용 올리브나무 쌍멍에(쥐고스 크레스토스)와 밭고랑을 나란히 걷는 큰 소와 작은 소.",
