    "title": "고향 나사렛 회당에서 이사야 61장 2절을 읽으시던 예수님이 왜 문장 한가운데('은혜의 해를 전파하여' 쉼표 뒤 '보복의 날' 직전!)에서 책을 덮으셨을까?",
