    "dossierMd": "■ B123 | 예수님이 고향 나사렛 회당에서 이사야서 두루마리를 읽으실 때, 왜 61장 2절 문장 한가운데서 말을 뚝 끊고 두루마리를 덮으셨을까?\n• 시대·테마: 신약 10_예수그리스도공생애 | T08_구속사·모형 · T02_문화·관습\n• 본문: 눅 4:16~21 (참조: 사 61:1~2) | 삼각 연동: 인물 P026(예수 그리스도) | 사건 E127(나사렛 회당의 메시아 취임 선언)\n• 호기심 질문: \"이사야 61장 2절 원문은 '여호와의 은혜의 해와 우리 하나님의 보복의 날을 선포하여'라고 한 문장으로 이어져 있는데, 왜 예수님은 '은혜의 해를 전파하여'까지만 읽고 딱 멈추신 뒤 책을 덮으셨을까?\"\n• 행간의 진실 & 스토리텔링: 1세기 유대 회당 예배에서는 말씀 봉독자가 일어서서 두루마리를 읽고, 설교할 때는 자리에 앉아서(랍비의 권위 있는 교육 자세) 강론했습니다(눅 4:16, 20). 그날 예수님이 읽으신 이사야 61장 1~2절 원문은 \"여호와의 은혜의 해(초림 — 구원과 희년의 선포)와, 우리 하나님의 보복의 날(재림 — 최후의 심판)\"이 쉼표 하나 사이로 붙어 있었습니다! 구약 선지자들이 멀리서 볼 때는 초림과 재림이 하나의 산봉우리처럼 붙어 보였지만, 예수님은 \"여호와의 은혜의 해를 전파하여\"까지만 읽으시고 그 뒷부분(\"우리 하나님의 보복의 날\")을 읽지 않은 채 두루마리를 덮어 맡은 자에게 주시고 \"이 글이 오늘 너희 귀에 응하였느니라!\"고 선언하셨습니다! 왜 멈추셨을까요? 예수님의 초림은 세상을 심판(보복)하러 오신 날이 아니라 죄인을 구원하러 오신 '은혜의 해'이기 때문이며, 예수님이 멈춰 놓으신 그 쉼표(,) 하나 사이에 지난 2천 년간의 신약 교회 시대(이방인 구원의 골든타임)가 열려 있는 것입니다!\n• 구속사 묵상 & 시각화: 나사렛 회당 강단에서 양피지 이사야 두루마리를 읽다 문장 중간에서 두루마리를 말아 덮으시는 예수님과 회당 안 사람들의 집중된 시선.",
