    "dossierMd": "■ B124 | 중풍병자를 메고 온 네 친구가 뜯어낸 가버나움 집 지붕 — 왜 기와가 아니라 '흙과 갈대 지붕을 파내어(에크소뤼쏘)' 달아 내렸을까?\n• 시대·테마: 신약 10_예수그리스도공생애 | T04_사물·생활사 · T01_원어·언어유희\n• 본문: 막 2:1~5, 눅 5:18~20 | 삼각 연동: 인물 P026(예수 그리스도) | 사건 E130(지붕을 뚫고 내린 중풍병자의 죄 사함과 치유)\n• 호기심 질문: \"마가복음은 지붕을 '뜯어 구멍을 내고(파내고)'라고 했고 누가복음은 '기와(케라모스)를 벗기고'라고 했는데, 1세기 갈릴리 집 지붕은 실제로 어떻게 생겼을까?\"\n• 행간의 진실 & 스토리텔링: 가버나움 유적지에서 발굴된 1세기 유대 서민 가옥은 바깥마당에서 지붕으로 바로 올라가는 돌계단이 나 있었고, 평평한 지붕(옥상)은 굵은 나무 들보 위에 잔가지와 갈대를 엮어 올린 뒤 두꺼운 진흙(점토)을 발라 돌 롤러로 다져 놓은 구조(비 오면 수시로 흙을 다시 다짐)였으며, 부분적으로 구운 토기 판(케라모스 — 헬라권 독자인 데오빌로가 이해하기 쉽게 누가가 쓴 표현)을 덮기도 했습니다. 마가복음 2장 4절이 쓴 헬라어 '에크소뤼쏘(ἐξορύσσω)'는 문자 그대로 \"땅을 곡괭이나 손으로 파헤쳐 구멍을 뚫다!\"라는 뜻입니다! 아래층 방 안에서 예수님이 말씀을 전하시는 동안, 천장 위에서 쿵쿵 소리가 나더니 마른 흙먼지와 지푸라기가 바리새인들의 머리 위로 우수수 떨어지고, 이윽고 뻥 뚫린 천장 구멍으로 햇살과 함께 중풍병자의 침상이 밧줄에 매달려 내려온 것입니다! 예수님은 집이 망가졌다고 꾸짖으시는 대신, 지붕을 파헤쳐서라도 친구를 주님 발 앞에 데려온 \"그들의 믿음을 보시고(이돈 텐 피스틴 아우톤)\" 먼저 죄 사함과 구원을 선포하셨습니다.\n• 구속사 묵상 & 시각화: 가버나움 평지붕 옥상에서 네 친구가 흙과 갈대 층을 걷어내고 밧줄로 침상을 달아 내리는 위아래 단면 투시 일러스트.",
