    "dossierMd": "■ B125 | 백부장의 하인을 고쳐달라고 간청할 때, 왜 유대 장로들까지 나서서 '이 백부장은 우리 민족을 사랑하고 회당을 지어준 사람입니다'라고 증언했을까? — 가버나움 현무암 회당 터\n• 시대·테마: 신약 10_예수그리스도공생애 | T06_역사·고고학 · T02_문화·관습\n• 본문: 눅 7:1~10, 마 8:5~13 | 삼각 연동: 인물 P026(예수 그리스도), P148(가버나움 백부장) | 사건 E134(가버나움 백부장의 믿음과 하인 치유)\n• 호기심 질문: \"오늘날 갈릴리 가버나움에 가면 하얀 석회암 회당 기둥 아래에 시커먼 현무암 기초석이 깔려 있는데, 그 검은 기초석이 바로 이 백부장이 지어준 회당 터일까?\"\n• 행간의 진실 & 스토리텔링: 오늘날 가버나움 유적지 지상에서 볼 수 있는 화려한 흰색 석회암 회당은 4세기(비잔틴 시대)에 지어진 것입니다. 그런데 프란치스코회 고고학 발굴단이 그 흰색 회당 바닥 아래를 발굴했을 때, 정확히 1세기 예수님 시대에 갈릴리 고유의 검은 현무암(Basalt)으로 튼튼하게 쌓아 올린 회당의 기초 벽면과 자갈 바닥이 그대로 드러났습니다! 이방 군대인 로마군(또는 헤롯 안디바의 치안군) 백부장이 자기 사비를 털어 유대인들을 위해 지어주었고(눅 7:5 \"그가 우리 민족을 사랑하고 또한 우리를 위하여 회당을 지었나이다\"), 예수님이 실제로 그 안에서 가르치시고 귀신을 쫓아내시며 생명의 떡 설교(요 6:59)를 하셨던 바로 그 역사적 공간입니다. 더욱 감동적인 것은, 정작 회당을 지어준 백부장 본인은 자신이 이방인이라 예수님이 자기 지붕 아래 들어오시는 것을 감당치 못한다며 \"다만 말씀으로만 하옵소서!\"라고 고백해 예수님조차 놀라게 한 최고의 믿음을 보였다는 점입니다.\n• 구속사 묵상 & 시각화: 가버나움 유적지의 1세기 검은 현무암 회당 기초석과, 투구를 옆구리에 끼고 겸손히 고개 숙인 로마 백부장.",
