    "visualGuide": "말라기 4장 2절 메시아 예언('그의 날개/옷자락 끝에 치료하는 광선')을 믿고 청색 실 섞인 옷술(치칮)을 붙잡는 여인의 손",
    "dossierMd": "■ B126 | 왜 열두 해 혈루증 앓던 여인은 예수님의 뒤로 와서 겉옷 전체가 아니라 하필 '겉옷 가(크라스페돈 — 옷술/치칮)'를 만졌을까?\n• 시대·테마: 신약 10_예수그리스도공생애 | T04_사물·생활사 · T08_구속사·모형\n• 본문: 마 9:20~22, 막 5:25~34 (참조: 민 15:38~39, 말 4:2) | 삼각 연동: 인물 P026(예수 그리스도), P307(혈루증 여인) | 사건 E139(야이로의 딸 소생과 열두 해 혈루증 여인 치유)\n• 호기심 질문: \"성경이 그냥 '옷을 만졌다'고 하지 않고 왜 굳이 '그의 겉옷 가(헬라어 크라스페돈, 히브리어 치칮)'를 만졌다고 기록했으며, 그것이 말라기 4장 2절 예언과 어떻게 연결될까?\"\n• 행간의 진실 & 스토리텔링: 민수기 15장 38~39절에 따라 경건한 유대인 남성은 네모난 겉옷(탈리트)의 네 귀퉁이 끝에 청색 끈을 넣은 옷술(히브리어 '치칮 Tzitzit', 헬라어 '크라스페돈 κράσπεδον')을 달고 다녔습니다. 이때 겉옷의 네 귀퉁이 자락을 히브리어로 '카나프(כָּנָף — 옷자락 / 동시에 새의 날개!)'라고 불렀습니다! 그런데 구약의 마지막 메시아 예언인 말라기 4장 2절을 히브리어 원문 그대로 직역하면 이렇게 되어 있습니다: \"내 이름을 경외하는 너희에게는 의로운 해(메시아)가 떠올라서, 그의 날개들(비크나페하 — 그의 겉옷 귀퉁이 옷술들!)에 치료하는 광선이 있으리니!\" 12년 동안 피가 마르지 않아 부정하다고 버림받았던 그 여인은 말라기 4장 2절의 메시아 예언을 굳게 믿고, \"예수님이 진정 말라기가 예언한 메시아라면, 그의 날개 끝(겉옷 가 옷술, 크라스페돈)만 만져도 그곳에 약속된 치유의 능력이 내게 임하리라!\"는 말씀 중심의 믿음으로 손을 뻗었던 것이며, 예수님은 그 손을 부정한 손이라 물리치지 않으시고 \"딸아, 안심하라 네 믿음이 너를 구원하였다!\"고 온 회중 앞에서 명예를 회복시켜 주셨습니다.\n• 구속사 묵상 & 시각화: 예수님의 겉옷 네 귀퉁이 끝에 달린 청색 실 섞인 유대 전통 옷술(치칮 / 크라스페돈)을 군중 틈바구니에서 간절히 붙잡는 여인의 손 클로즈업.",
