    "dossierMd": "■ [B128] 오병이어의 기적 때 소년이 가져온 '보리떡 다섯 개와 물고기 두 마리'는 왜 부자의 도시락이 아니라 가장 가난한 서민의 한 끼였을까?\n• 요 6:9\nP026(예수 그리스도), P123(안드레), 오병이어 소년 · E026 | 1세기 로마 제국과 유대에서 부유층은 곱고 흰 밀떡(소맥 빵)을 먹었고, 거칠고 까끌까끌한 보리떡(크리디노스)은 가축 사료나 가장 가난한 빈민들이 먹는 값싼 양식이었습니다(탈무드에서도 \"밀은 사람이 먹고 보리는 짐승이 먹는다\"고 기록). 함께 가져온 '물고기 두 마리(옵사리아 뒤오)' 역시 큰 생선이 아니라, 갈릴리 호수에서 잡은 정어리·멸치 크기의 작은 생선을 소금에 절여 말린 반찬용 잔생선이었습니다. 소년의 보잘것없고 가난한 도시락 하나가 주님의 손에 들려 축사될 때 장정만 5천 명(노약자·여인 포함 2만 명)을 배불리 먹이는 하늘 잔치가 되었습니다.",
