    "dossierMd": "■ [B132] 일만 달란트 탕감받은 종의 비유 — '일만 달란트'와 '백 데나리온'은 오늘날 가치로 얼마나 차이가 날까?\n• 마 18:23~35\nP026(예수 그리스도), P029(베드로) · E144 | 노동자 하루 일당이 1데나리온이므로 동료가 빚진 '백 데나리온'은 약 100일 치 품삯(오늘날 약 1,500만~2,000만 원)으로 갚을 수 있는 현실적인 금액입니다. 반면 왕에게 탕감받은 '일만 달란트'는 1달란트 = 6,000데나리온이므로 무려 6,000만 데나리온, 즉 노동자 한 사람이 한 푼도 안 쓰고 16만 4천 년 동안 일해야 갚을 수 있는 천문학적 액수(수조 원대, 당시 유대·이두매·사마리아 전체 1년 총세금이 600달란트에 불과했음!)입니다! 우리가 하나님께 탕감받은 죄의 빚은 '16만 년 치'인데, 형제의 '100일 치' 허물을 용서하지 못해 멱살을 잡는 우리의 모습을 비추는 거울입니다.",
