    "dossierMd": "■ [B133] 초막절 끝날('큰 날')에 예수님이 성전에서 외치신 '누구든지 목마르거든 내게로 와서 마시라!'의 실로암 금주전자 물 붓기 예식 배경\n• 요 7:37~39 (참조: 사 12:3)\nP026(예수 그리스도) · E145 | 1세기 예루살렘 성전의 초막절 7일 동안 매일 아침 대제사장은 금주전자(황금 물병)를 들고 행렬을 지어 실로암 못에 내려가 물을 길어 온 뒤, 나팔 소리와 함께 이사야 12장 3절(\"그러므로 너희가 기쁨으로 구원의 우물들에서 물을 길으리로다\")을 찬양하며 번제단 위 은대접에 물을 쏟아붓는 '수제(물 부음 예식)'를 거행했습니다. 그리고 그 예식이 절정에 달한 명절 끝날, 온 백성이 제단에 부어지는 물을 바라보며 메시아와 성령의 생수를 갈망하던 바로 그 순간에, 예수님이 성전 한복판에 우뚝 서서 \"누구든지 목마르거든 내게로 와서 마시라! 나를 믿는 자는 그 배에서 생수의 강이 흘러나오리라!\"고 외치신 것입니다!",
