    "dossierMd": "■ [B135] 날 때부터 맹인 된 사람을 고치실 때, 왜 말씀으로만 하지 않으시고 굳이 '땅에 침을 뱉어 진흙을 이겨 눈에 바르셨을까'?\n• 요 9:6~7 (참조: 창 2:7)\nP026(예수 그리스도) · E145 | 태어날 때부터 안구 자체가 없거나 형성되지 않은 선천성 맹인에게는 고치는 치유(Healing)를 넘어 없는 기관을 새로 만드는 '창조(Creation)'의 능력이 필요했습니다! 그래서 초기 교부 이레네우스와 어거스틴이 통찰했듯, 예수님은 창세기 2장 7절에서 땅의 흙(진흙)으로 첫 사람 아담을 빚으셨던 창조주 하나님의 방식 그대로, 땅의 흙을 이겨 그 맹인의 빈 눈자위에 새로운 눈을 창조해 넣으심으로 \"태초에 흙으로 인간을 지으신 창조주가 바로 내 앞에 서 계신 예수님이시다!\"라는 사실을 보여주셨습니다.",
