    "dossierMd": "■ [B136] 요한복음 10장의 양의 문 비유 — 왜 중동의 돌 양의 우리에는 나무 문짝이 따로 없고 '목자 자신이 문에 가로누워' 잘까?\n• 요 10:1~11\nP026(예수 그리스도) · E145 | 팔레스타인 들녘에서 목자들이 돌담을 둥글게 쌓아 만든 야외 양의 우리(아울레)에는 양들이 드나드는 좁은 출입구 통로만 뚫려 있을 뿐, 나무 경첩 달린 문짝이 따로 없습니다! 대신 밤이 되면 양들을 우리 안에 다 들여보낸 뒤, 목자 자신이 그 좁은 출입구 바닥에 몸을 가로눕혀 잠을 잡니다. 즉, 양이 밖으로 나가려 해도 목자의 몸을 밟고 지나가야 하고, 이리나 강도가 들어오려 해도 문에 누워 있는 목자와 먼저 목숨 걸고 싸워야 합니다! 그래서 예수님은 \"나는 양의 문을 지키는 문지기다\"라고 하지 않으시고 \"나는 양의 문(에고 에이미 헤 튀라)이라!\"(요 10:7, 9)고 말씀하신 것입니다.",
