    "visualGuide": "죽은 지 나흘이 되어 돌문으로 막힌 베다니 동굴 무덤 앞에서 눈물을 흘리신 뒤 '나사로야 나오라!' 외치시는 부활이요 생명이신 예수님",
    "dossierMd": "■ [B137] 왜 예수님은 나사로가 죽었다는 소식을 듣고도 이틀을 더 머무르시어 굳이 '나흘(4일)이 지나 썩은 냄새가 날 때' 베다니에 도착하셨을까?\n• 요 11:6, 11:17, 11:39\nP026(예수 그리스도), P143(나사로), P141(마르다), P142(마리아) · E149 | 회당장 야이로의 딸(막 숨이 멎은 직후)과 나인성 과부의 아들(장례 행렬 중, 사망 당일)을 살리셨을 때, 바리새인들은 유대 미신 전승을 들어 \"사람이 죽은 뒤 사흘(3일) 동안은 영혼이 시신 주위를 맴돌기 때문에 사흘 안에 깨어난 것은 완전한 부활이 아니라 기절에서 깨어난 것(가사 상태)일 수 있다\"고 핑계를 댔습니다! 유대 전승에서 시신이 부패하여 얼굴을 알아볼 수 없게 되는 '나흘째(4일째)'부터는 영혼이 완전히 떠나 그 누구도 되살릴 수 없고 오직 창조주 하나님만 살리실 수 있는 절대 불가능의 영역이었습니다. 예수님은 일부러 나흘이 꽉 차서 마르다조차 \"주여 죽은 지가 나흘이 되었으매 벌써 냄새가 나나이다\"(요 11:39)라고 체념한 그때 도착하셔서, \"나사로야 나오라!\" 한 말씀으로 사망 권세를 깨뜨리셨습니다.",
