    "dossierMd": "■ [B139] 예수님이 부자 청년에게 말씀하신 '낙타가 바늘귀로 들어가는 것이 부자가 하나님 나라에 들어가는 것보다 쉬우니라' — 성문 쪽문설 vs 밧줄 오역설 팩트체크\n• 마 19:24, 막 10:25, 눅 18:25\nP026(예수 그리스도) · E149 | 흔히 예루살렘 성문에 밤에 낙타가 무릎을 꿇고 짐을 내려야만 겨우 통과할 수 있는 작은 쪽문('바늘귀 문')이 있었다는 예화가 널리 퍼져 있으나, 이는 중세 시대(11~15세기)에 만들어진 후대 전승으로 1세기 예루살렘에는 그런 성문이 없었습니다(만약 낙타가 무릎 꿇고 들어갈 수 있는 문이었다면 예수님이 바로 다음 절인 26절에서 \"사람으로는 할 수 없으되 하나님으로서는 다 하실 수 있느니라!\"고 말씀하셨을 리가 없습니다!). 당시 탈무드 격언(\"코끼리가 바늘귀로 들어간다\")처럼 팔레스타인에서 가장 큰 동물인 '낙타(카멜로스)'와 집에서 쓰는 가장 작은 구멍인 '바느질 바늘귀(라피스 / 의사 누가는 외과 수술용 봉합 바늘 벨로네 βελόνη 사용!)'를 대비시켜 \"인간의 재력이나 자력 구원으로는 0% 불가능하며 오직 하나님의 전적인 은혜의 기적으로만 구원받는다\"는 진리를 선포하신 것입니다.",
