    "dossierMd": "■ [B140] 종려주일 입성 때 왜 예수님은 군마(백마)가 아니라 '아직 아무도 타보지 않은 나귀 새끼'를 타고 예루살렘에 입성하셨을까?\n• 막 11:1~10, 슥 9:9 (참조: 왕상 1:33)\nP026(예수 그리스도) · E152 | 고대 근동에서 왕이 전쟁을 하러 입성할 때는 군마(전쟁 말)를 탔지만, 전쟁이 끝나고 평화(샬롬)를 선포하러 입성할 때는 '나귀'를 탔습니다(솔로몬이 기혼에서 대관식을 치를 때도 다윗 왕의 노새/나귀를 탔음 — 왕상 1:33). 스가랴 9장 9절 예언 그대로 예수님은 로마를 칼로 뒤집는 정치적 혁명가가 아니라, 자신의 십자가 피로 하나님과 죄인 사이에 영원한 화평을 이루시는 겸손한 평화의 왕으로 나귀 새끼를 타고 입성하셨습니다(장차 재림하실 때는 심판의 왕으로 백마를 타고 오심 — 계 19:11).",
