    "visualGuide": "푸른 잎사귀만 화려하게 피워 올리고 봄철 선열매(파게)가 전혀 없는 무화과나무와 외식하는 예루살렘 성전의 교차 비교도",
    "dossierMd": "■ [B141] 수난주간 월요일, 아직 무화과 철이 아닌데도(막 11:13) 왜 예수님은 잎만 무성한 무화과나무를 저주하셨을까? — 선열매 '파게(Paggim)'의 생태학\n• 막 11:12~14, 20~21\nP026(예수 그리스도) · E152 | 성도들이 가장 많이 질문하는 난제입니다! \"무화과 철이 아닌데 열매가 없다고 저주하시는 것은 억지 아닌가?\" 그러나 팔레스타인 무화과나무의 생태를 알면 단번에 풀립니다. 정규 무화과 수확 철은 6월과 8~9월이지만, 유월절 무렵인 3~4월 봄철에 무화과나무에 '푸른 잎사귀'가 돋아날 때는 반드시 그 잎보다 먼저(또는 동시에) 풋열매인 '선열매(히브리어 파게 פַּגִּים / 아랍어 타크쉬)'가 함께 맺힙니다! 나그네들은 봄철에 이 선열매를 따 먹으며 허기를 달랬는데, 만약 나무에 선열매(파게)가 하나도 안 열렸다면 그 나무는 그해 여름 정규 철에도 열매를 전혀 맺지 못하는 불임 나무입니다. 무엇보다도 남들보다 잎사귀만 화려하게 피워 올려 \"내게 열매가 있다!\"고 과시하면서 정작 속에는 선열매 하나 없던 이 무화과나무는, 성전 건물과 종교 예식(잎사귀)만 무성할 뿐 회개와 의의 열매는 전혀 없던 당시 예루살렘 성전과 외식하는 종교 지도자들에 대한 시청각 심판 예언이었습니다.",
