    "title": "바리새인들이 들고 온 세금 동전 '데나리온' — 동전 앞뒷면에 새겨진 티베리우스 황제 신격화 문구와 '하나님의 형상(에이콘)이 찍힌 너희 자신은 하나님께 바치라!'는 명답!",
    "origTitle": "Tiberius' Denarius ('Son of the Divine Augustus') vs Bearing the Image (Eikon) of God",
    "scriptures": "마 22:15~22; 창 1:27",
    "hook": "예수님께 세금 문제를 시험하려 가져온 은화 1데나리온 동전 앞뒷면에는 실제로 어떤 우상 숭배 글자가 새겨져 있었을까?",
    "visualGuide": "티베리우스 황제 초상과 신성모독 라틴어 문구가 새겨진 1세기 은화 데나리온 실물과 하나님의 형상으로 지음 받은 인간의 대조",
    "dossierMd": "■ [B142] 예수님을 시험하려 바리새인들이 들고 온 가이사의 세금 동전 '데나리온' — 동전 앞뒷면에 새겨진 신성모독 문구의 비밀\n• 마 22:15~22\nP026(예수 그리스도) · E153 | 당시 로마 유대 속주에서 인두세로만 납부해야 했던 티베리우스 황제의 은화 '데나리온(Denarius)' 앞면에는 티베리우스의 초상화와 함께 라틴어로 TI CAESAR DIVI AVG F AVGVSTVS (\"신성한 아우구스투스의 아들이며 신이신 티베리우스 가이사\"), 뒷면에는 PONTIFEX MAXIMVS (\"최고 대제사장\")라는 신성모독 문구가 새겨져 있었습니다! 경건한 유대인이 그 우상 숭배 동전을 품속에 지니고 성전 경내에 들어온 것 자체가 위선이었습니다. 예수님은 그 동전을 꺼내게 하신 뒤 \"이 형상(에이콘)과 이 글이 누구의 것이냐?\" 물으시고 \"가이사의 형상이 찍힌 동전은 가이사에게 바치고, 하나님의 형상(에이콘, 창 1:27)이 찍힌 너희 자신의 존재와 생명은 하나님께 바치라!\"는 천상의 지혜로 응수하셨습니다.",
