    "visualGuide": "여인의 뜰 나팔 모양 황동 헌금함(쇼파로트) 앞에 서서 손바닥 위의 가장 작은 구리 동전 두 렙돈 전부를 넣는 과부와 미소 지으시는 예수님",
    "dossierMd": "■ [B143] 가난한 과부가 성전 헌금함에 넣은 '두 렙돈(고드란트)' — 왜 한 렙돈은 남기지 않고 두 렙돈 전부를 넣었으며 성전 헌금함('나팔 모양 13개 통')은 어떻게 생겼을까?\n• 막 12:41~44, 눅 21:1~4\nP026(예수 그리스도), 두 렙돈 과부 · E153 | 예루살렘 성전 '여인의 뜰' 벽면에는 황동으로 만든 나팔 모양의 헌금함(쇼파로트) 13개가 설치되어 있었습니다. 부자들이 무거운 은화·동전 자루를 나팔 모양 황동 깔때기에 쏟아부으면 \"쨍그랑!\" 하는 요란한 금속 소리가 온 뜰에 울려 퍼져 자기 의를 과시하기 좋았습니다. 반면 '렙돈(Λεπτόν — 얇고 작은 껍질이라는 뜻)'은 1데나리온의 1/128에 불과한 유대 최소 단위 구리 동전으로 소리조차 거의 나지 않았습니다. 과부에게는 동전이 딱 두 개(두 렙돈) 있었으므로 하나만 내고 하나는 자기 저녁 빵 값으로 남길 수도 있었지만(게다가 미쉬나 규례상 성전 감사 헌금 최소 단위가 두 렙돈이기도 했음), 그녀는 '자기의 생활비 전부(홀론 톤 비온 아우테스 — 직역하면 자기의 생명 전체!)'를 주님께 드렸고, 바로 다음 장에서 자기 생명 전체를 십자가에 내어주실 예수님만은 그 작은 동전 두 개가 떨어지는 소리를 가장 크게 들으셨습니다.",
