    "dossierMd": "■ [B144] 마가 다락방 최후의 만찬으로 제자들을 인도한 암호 — 왜 예루살렘 거리에서 '물 한 동이를 가지고 가는 남자'를 따라가라고 하셨을까?\n• 막 14:12~16, 눅 22:7~13\nP026(예수 그리스도), P029(베드로), P122(사도 요한), P163(마가 요한) · E027, E154 | 유월절을 맞아 수십만 명의 순례객이 붐비는 예루살렘 거리에서 가룟 유다가 만찬 장소를 미리 밀고하지 못하도록 예수님은 베드로와 요한에게 기가 막힌 보안 암호를 주셨습니다: \"성내로 들어가라 그리하면 물 한 동이를 가지고 가는 사람(안트로포스 — 남성!)을 만나리니 그를 따라가라!\" 당시 중동 사회에서 토기 물동이(케라미온)를 머리에 이고 물을 길어 나르는 일은 100% 여인들의 몫이었고, 남성은 가죽 부대를 멨지 절대 물동이를 이고 다니지 않았습니다! 따라서 수만 인파 속에서도 물동이를 이고 걸어가는 남자는 멀리서도 단번에 눈에 띄는 완벽한 표식이었습니다(전승에 따르면 그 집이 바로 부유한 마리아와 아들 마가 요한의 다락방이었습니다).",
