    "visualGuide": "1세기 로마·유대식 트리클리니움(ㄷ자 침상 식탁) 배치도(중앙 예수님·오른쪽 요한·왼쪽 상석 가룟 유다에게 떡 한 조각을 건네시는 끝없는 사랑)",
    "dossierMd": "■ [B145] 최후의 만찬 식탁 배치('트리클리니움 Triclinium') — 가룟 유다와 사도 요한은 예수님의 어느 쪽 자리에 누워 있었을까?\n• 요 13:23~26\nP026(예수 그리스도), P122(사도 요한), P131(가룟 유다) · E154 | 레오나르도 다빈치의 명화 『최후의 만찬』처럼 긴 테이블에 의자를 놓고 일렬로 앉은 것이 아닙니다! 1세기 유월절 공식 만찬은 로마·헬라식 ㄷ자형 낮은 침상 식탁('트리클리니움, Triclinium')에서 왼팔 팔꿈치를 쿠션에 괴고 비스듬히 누워 오른손으로 음식을 먹었습니다. 이때 주빈석인 예수님의 오른쪽 자리(예수님의 가슴 바로 앞)에는 사도 요한이 누워 있어 고개만 살짝 뒤로 젖히면 예수님의 가슴에 의지해 귓속말로 질문할 수 있었고(요 13:23, 25), 충격적이게도 호스트(예수님)의 왼쪽 가장 높은 상석(최고 귀빈석!)에는 가룟 유다가 누워 있었습니다! 예수님은 자기를 팔아넘길 가룟 유다를 가장 귀한 상석에 앉히시고, 호스트가 가장 사랑하는 귀빈에게만 베푸는 최고의 환대 표시인 '소스에 찍은 떡 한 조각(프소미온)'(요 13:26)을 건네시며 마지막 순간까지 회개의 손길을 내미셨던 것입니다!",
