    "dossierMd": "■ [B146] 겟세마네('기름 짜는 틀') 동산의 올리브 착유기 — 왜 예수님은 감람산 기름틀 동산에서 땀이 핏방울같이 되도록 기도하셨을까?\n• 눅 22:39~44, 마 26:36\nP026(예수 그리스도) · E154 | 아람어 '겟세마네(Gethsemane, 히브리어 가트 쉐마님 גַּת שְׁמָנִים)'의 직역은 \"기름 짜는 틀(Olive Oil Press)\"입니다! 감람산(올리브산)에서 수확한 감람 열매를 맷돌로 으깬 뒤, 수백 킬로그램짜리 거대한 돌 추(바위 덩어리)를 지렛대로 짓눌러 세 번에 걸쳐 기름을 짜내던 동산이었습니다(이때 가장 처음 짜낸 순결한 1등급 기름이 바로 맞은편 예루살렘 성전 등잔대를 밝히는 성소 기름으로 쓰였음!). 바로 그 '겟세마네(기름 짜는 틀)'에서 '그리스도(기름 부음 받은 자)'께서 온 인류의 죄의 짐이라는 거대한 바위 추에 짓눌려 모세혈관이 터지는 혈한증(헤마토히드로시스 — 땀이 땅에 떨어지는 핏방울같이 됨, 의사 누가의 유일한 기록!)을 흘리시기까지 자신을 짜내어 세상의 구원 등불을 밝히셨습니다.",
