    "dossierMd": "■ [B150] 본디오 빌라도가 예수님을 재판한 '가바다(박석 깔린 곳)'와 가이사랴에서 발굴된 '빌라도 비석(Pilate Stone)'\n• 요 19:13, 마 27:24\nP026(예수 그리스도), P199(본디오 빌라도) · E155 | 1961년 지중해 해안 가이사랴 로마 극장 유적지에서 라틴어로 [PON]TIVS PILATVS [PRAEF]ECTVS IVDAE[AE] (\"유대 총독 본디오 빌라도\")라고 선명히 새겨진 봉헌 석판이 발굴되어 빌라도의 실존과 직함을 확증했습니다. 빌라도가 유월절 오전 6시경 재판석(베마)에 앉았던 '박석(리토스트로톤, 히브리어 가바다 — 넓은 돌판이 깔린 높은 광장)'에서 그는 대야에 물을 떠다 손을 씻으며 \"이 사람의 피에 대하여 나는 무죄하니\"라고 발을 뺐으나, 사도신경은 온 인류의 죄를 대표하여 \"본디오 빌라도에게 고난을 받으사\"라고 그의 이름을 영원히 기록했습니다.",
