    "dossierMd": "■ [B151] 예수님이 맞으신 로마의 채찍질('플라겔룸 Flagellum')과 구레네 시몬이 대신 진 십자가 가로대('파티불룸 Patibulum')\n• 마 27:26, 27:32, 막 15:21\nP026(예수 그리스도), P151(구레네 시몬), P294(루포) · E155 | 유대 율법의 태형은 39대(40대에서 하나 감함)로 제한되었으나, 로마군의 사형 직전 태형 도구인 '플라겔룸(Flagellum)'은 여러 가닥의 가죽 줄 끝에 납 구슬과 뾰족한 양의 뼈 조각을 매달아, 한 번 후려칠 때마다 등가죽과 근육이 밭고랑처럼 찢겨 나가는(시 129:3; 사 53:5 \"그가 채찍에 맞음으로 우리는 나음을 받았도다\") 치명적인 고문이었습니다. 극심한 출혈로 예수님이 무게 약 35~50kg의 십자가 가로대(파티불룸 — 세로 기둥 스티페스는 처형장에 이미 박혀 있었음)를 지고 가시다 쓰러지시자, 유월절을 지키러 북아프리카 리비아(구레네)에서 온 구레네 시몬이 억지로 그 십자가를 대신 졌고, 그 억지 십자가가 시몬의 두 아들 알렉산더와 루포(막 15:21; 롬 16:13 바울이 \"주 안에서 택하심을 입은 루포와 그의 어머니 곧 내 어머니\"라 부른 초대교회 기둥 성도!) 온 가정을 구원하는 축복의 통로가 되었습니다.",
