    "dossierMd": "■ [B152] 1968년 예루살렘 기브앗 하미브타르에서 발굴된 1세기 십자가 처형 유골('여호하난의 발뒤꿈치 뼈와 대못')이 밝힌 십자가 고증\n• 요 20:25, 눅 24:39\nP026(예수 그리스도) · E027 | 1968년 예루살렘 북동쪽 무덤에서 서기 1세기에 실제로 로마 십자가형으로 처형된 20대 유대인 남성('여호하난')의 유골함이 세계 최초로 발견되었습니다. 그의 오른쪽 발뒤꿈치 뼈(종골)에는 길이 11.5cm의 무쇠 대못이 감람나무 조각과 함께 그대로 박힌 채 끝이 구부러져 있었습니다! 또한 로마 십자가형에서 손에 못을 박을 때 손바닥 한가운데에 박으면 체중 때문에 살이 찢어지므로, 고대 해부학에서 '손(케이르)'에 포함되던 손목 수근골(데스도 공간, 정중신경 통과 부위)에 대못을 박아 온몸의 하중을 버티게 했다는 사실이 의학·고고학적으로 규명되었습니다.",
