    "visualGuide": "히브리어·라틴어·헬라어 3개 국어로 적힌 십자가 나무 죄패(Titulus)와 히브리어 두문자 י-ה-ו-ה(YHWH) 강조 인포그래픽",
    "dossierMd": "■ [B153] 빌라도가 예수님의 십자가 머리 위에 히브리(아람)·로마(라틴)·헬라 3개 국어로 써 붙인 죄패 '나사렛 예수 유대인의 왕'의 히브리 두문자 비밀\n• 요 19:19~22\nP026(예수 그리스도), P199(빌라도) · E027 | 대제사장들이 왜 그토록 발끈하며 빌라도에게 \"유대인의 왕이라 쓰지 말고 자칭 유대인의 왕이라 쓰라!\"(요 19:21)고 항의했을까요? 당시 십자가 죄패에 적힌 히브리어 네 단어 — \"예슈아(יֵשׁוּעַ, 예수) 하나츠리(הַנָּצְרִי, 나사렛) 웨멜렉(וּמֶלֶךְ, 그리고 왕) 하예후딤(הַיְּהוּדִים, 유대인들의)\" — 의 첫 글자(두문자, Acronym) 네 개를 순서대로 따서 읽으면 소름 돋게도 정확히 하나님의 거룩한 이름 4문자 — Y - H - W - H (י-ה-ו-ה, 여호와 / 야훼!) — 가 나타납니다! 대제사장들은 십자가 위에서 여호와 하나님의 이름(YHWH)이 빛나는 것을 견딜 수 없었으나, 빌라도는 \"내가 쓸 것을 썼다!\"며 일축했습니다.",
