    "dossierMd": "■ [B154] 예수님이 운명하시는 순간 성소 휘장이 '아래에서 위로'가 아니라 '위로부터 아래까지 둘로 찢어진'(마 27:51) 이유와 그 두께\n• 마 27:51, 히 10:19~20\nP026(예수 그리스도) · E027 | 유대 미쉬나(세겔림 8:5)에 따르면 헤롯 성전의 성소와 지성소를 가로막던 휘장(파로케트)은 높이가 약 18m(60피트, 아파트 6층 높이!), 두께가 성인 남성의 손바닥 너비(약 7~10cm)에 달하며 72가닥의 꼬아 만든 실로 직조되어 말 두 필이 양쪽에서 잡아당겨도 절대 찢어지지 않는 거대한 장벽이었습니다. 그리고 그 시각은 오후 3시(제9시, 저녁 상번제 분향 시간)여서 성소 안에는 수많은 제사장이 들어가 있었습니다. 그런데 사람이 손댈 수도 없는 18m 꼭대기 '위로부터 아래까지(아노텐 헤오스 카토)' 하나님의 손이 직접 그 두꺼운 휘장을 단번에 찢어 놓으심으로, 이제 누구든지 예수님의 피를 힘입어 지성소 은혜의 보좌로 직행할 수 있는 새 시대가 열렸음을 선포하셨습니다!",
