    "dossierMd": "■ [B155] 아리마대 요셉과 니고데모가 예수님의 시신을 모실 때 가져온 '몰약과 침향 섞은 것 백 근(약 34kg)' — 왜 왕실 장례 규모의 향품을 가져왔을까?\n• 요 19:38~40\nP145(아리마대 요셉), P144(니고데모) · E155 | 로마 도량형 1근(리트라)은 약 327g이므로 니고데모가 가져온 몰약과 침향 '백 근'은 무려 약 33~34kg에 달하는 엄청난 양입니다! 당시 일반 유대인의 장례에는 1~2kg의 향품만 썼고, 오직 유대 왕이나 최고 랍비 가말리엘의 장례 때만 30~40kg의 향품을 썼습니다. 생전에는 바리새인들과 공회원이 두려워 밤에 몰래 찾아오고(요 3:2) 숨어 지내던 두 사람(아리마대 요셉과 니고데모)이, 정작 모든 제자가 다 도망친 십자가 죽음의 현장에서는 두려움을 떨치고 나와 예수님을 '만왕의 왕'으로 예우하는 최고 왕실 장례 예법으로 자신들의 사랑을 고백한 것입니다(사 53:9 \"그가 죽은 후에 부자와 함께 있었도다\" 예언 성취!).",
