    "dossierMd": "■ [B156] 부활 아침 막달라 마리아에게 왜 예수님은 '나를 붙들지 말라(메 무 하프투)'고 하시면서, 도마에게는 '네 손을 내밀어 내 옆구리에 넣어보라'고 하셨을까?\n• 요 20:17, 20:27\nP026(예수 그리스도), P140(막달라 마리아), P127(도마) · E156 | 요한복음 20장 17절의 \"나를 붙들지 말라(메 무 하프투, Μή μου ἅπτου)\"는 현재 명령형 부정문으로, \"내 몸에 손끝도 대지 말라(부정 탄다)\"는 뜻이 아니라, \"이미 붙잡고 있는 것을 이제 그만 매달려 붙잡고 있으라(Stop clinging to Me)!\"라는 뜻입니다! 막달라 마리아는 죽었다 살아나신 예수님을 다시는 잃어버리지 않으려고 예전 육신의 관계처럼 발을 꽉 끌어안고 놓지 않으려 했습니다. 이에 예수님은 \"이제 나는 승천하여 성령으로 너희와 영원히 함께할 것이니, 육신의 내 옷자락에 매달려 있지 말고 어서 내 형제들에게 가서 부활의 증인이 되라!\"고 파송하신 것이며, 반대로 의심하던 도마에게는 못 자국과 창 자국을 직접 만져보게 하심으로 믿음을 세워주신 맞춤형 사랑이었습니다.",
