    "scriptures": "행 2:1~4; 2:41; 출 32:28; 고후 3:6",
    "hook": "왜 구약 시내산에서 율법 돌판이 내려온 날 죽은 사람의 수(3000명)와 신약 오순절 성령이 내려온 날 구원받은 사람의 수(3000명)가 정확히 똑같을까?",
    "visualGuide": "출애굽기 32장 28절(율법 조문은 죽이는 것 — 3000명 사망)과 사도행전 2장 41절(영은 살리는 것 — 3000명 구원)의 구속사 데칼코마니",
    "dossierMd": "■ B158 | 왜 오순절 성령 강림 때 베드로의 첫 설교로 회개하고 세례받은 사람의 수가 하필 '삼천(3,000) 명'이었을까? — 시내산 첫 오순절과의 소름 돋는 대조!\n• 시대·테마: 신약 11_초대교회·선교 | T08_구속사·모형 · T02_문화·관습\n• 본문: 행 2:1~4, 2:41 (참조: 출 19:16~18, 32:28, 고후 3:6) | 삼각 연동: 인물 P029(베드로), P009(모세) | 사건 E028(오순절 마가 다락방 성령 강림과 초대교회 탄생), E013(시내산 언약)\n• 호기심 질문: \"구약에서 유월절 출애굽 후 정확히 50일째(첫 번째 오순절!)에 시내산에서 십계명 돌판을 받을 때는 몇 명이 죽었으며, 신약 마가 다락방 오순절에는 몇 명이 살아났을까?\"\n• 행간의 진실 & 스토리텔링: 유대 전승에서 유월절(출애굽) 후 50일째 되는 오순절(칠칠절 / 맥추절, 샤부오트)은 모세가 시내산에서 불과 연기 가운데 십계명 돌판(율법)을 받은 날을 기념하는 절기였습니다! 그런데 구약의 그 첫 번째 오순절 날, 산 아래에서 금송아지를 만들어 숭배하던 백성들 중 레위 자손의 칼에 심판받아 죽은 사람의 수가 정확히 몇 명이었을까요? 출애굽기 32장 28절 — \"그날에 백성 중에 죽은 자가 삼천(3,000) 명가량이었더라!\"\n• 그리고 1,500년 뒤, 예수님이 유월절 어린양으로 피 흘리신 후 50일째 되는 신약의 오순절 날(행 2장), 마가 다락방에 돌판이 아닌 마음 판에 새겨지는 성령의 불이 임하고 베드로가 복음을 선포했을 때 그날 구원받아 살아난 사람의 수가 정확히 몇 명이었습니까? 사도행전 2장 41절 — \"이 날에 신도의 수가 삼천(3,000)이나 더하더라!\"\n• 사도 바울이 고린도후서 3장 6절에서 \"율법 조문은 죽이는 것이요 영(성령)은 살리는 것임이니라!\"라고 외친 말씀이 구약 시내산의 '율법 아래 죽은 3,000명'과 신약 오순절의 '성령으로 살아난 3,000명'으로 완벽한 대칭을 이룬 것입니다!\n• 구속사 묵상 & 시각화: 시내산의 번개와 깨어진 돌판 아래 쓰러진 3,000명(출 32:28)과, 예루살렘 마가 다락방 성령의 불꽃 아래 세례받으며 살아나는 3,000명(행 2:41)의 구속사 데칼코마니 인포그래픽.",
