    "title": "성전 열 개의 문 중 유일하게 황금보다 빛나는 '코린트식 청동(고린도 놋)'으로 주조된 '미문(아름다운 문 / 니카노르 문)'과 은과 금보다 귀한 예수의 이름!",
    "origTitle": "The Beautiful Gate (Nicanor's Gate of Corinthian Bronze) & 'Silver and Gold Have I None'",
    "scriptures": "행 3:1~10",
    "hook": "왜 헤롯 성전의 수많은 문 중에서 동쪽 중앙 대문만 '미문(아름다운 문)'이라 불렸으며 감람산에서 발굴된 '니카노르 유골함'은 무엇을 증명할까?",
    "visualGuide": "아침 햇살에 순금보다 눈부시게 빛나는 코린트 청동 미문 15계단 위에서 앉은뱅이의 오른손을 잡아 일으키는 베드로와 요한",
    "dossierMd": "■ B159 | 성전 '미문(Beautiful Gate)' 앞의 나면서 못 걷게 된 사람 — 왜 그 문만 황금보다 비싼 '코린트식 청동(고린도 놋)'으로 빛났을까?\n• 시대·테마: 신약 11_초대교회·선교 | T06_역사·고고학 · T04_사물·생활사\n• 본문: 행 3:1~10 | 삼각 연동: 인물 P029(베드로), P122(사도 요한), 미문 앞 치유받은 사람 | 사건 E159(성전 미문 앞 치유와 솔로몬 행각 설교)\n• 호기심 질문: \"헤롯 성전의 다른 아홉 개 문은 모두 금과 은으로 입혔는데, 왜 '니카노르의 문'만 유일하게 '아름다운 문(미문, 호라이아)'이라는 별명으로 불렸을까?\"\n• 행간의 진실 & 스토리텔링: 유대 역사가 요세푸스(『유대전쟁사』 5.5.3)와 미쉬나(미도트) 기록에 따르면, 이방인의 뜰에서 여인의 뜰로 올라가는 동쪽 중앙 대문은 알렉산드리아의 부호 니카노르가 기증한 '니카노르 문(성경의 미문)'이었습니다. 다른 아홉 개 문은 나무에 금박·은박을 입혔으나, 오직 이 문만은 금과 은과 구리가 절묘하게 합금된 전설적인 '코린트식 청동(Corinthian Bronze)' 통판으로 주조되어 아침 햇살을 받으면 순금보다 훨씬 눈부시고 찬란한 빛을 뿜어냈기에 백성들이 '미문(아름다운 문)'이라 불렀습니다(1902년 감람산에서 \"문을 만든 알렉산드리아의 니카노르의 유골\"이라 새겨진 실제 유골함이 발굴됨!). 세상에서 가장 화려한 금은 합금 문(미문) 앞에서 구걸하던 사십 세 넘은 장애인을 향해, 베드로는 \"이 문에 발린 은과 금은 내게 없거니와 내게 있는 이것을 네게 주노니 나사렛 예수 그리스도의 이름으로 일어나 걸으라!\"며 그의 오른손을 잡아 일으켰고, 평생 성전 문밖에만 앉아 있던 그가 최초로 미문을 통과해 성전 안으로 걷고 뛰며 들어가 하나님을 찬송했습니다!\n• 구속사 묵상 & 시각화: 찬란한 황금빛 청동으로 빛나는 거대한 성전 미문(15계단 위) 앞에서 오른손을 내밀어 앉은뱅이를 일으켜 세우는 베드로와 요한.",
