    "title": "신약의 다른 모든 곳에서는 하나님 우편에 '앉아 계신' 예수님이 오직 스데반 집사가 돌에 맞아 순교할 때만 자리에서 '일어서서(서 계신 것을 보노라)' 맞이하신 이유!",
    "origTitle": "Jesus Standing (Hestota) at the Right Hand of God to Welcome the First Martyr Stephen",
    "scriptures": "행 7:55~56; 히 10:12",
    "hook": "왜 부활 승천 후 보좌에 앉으신 예수님이 스데반이 순교하는 순간에는 보좌에서 벌떡 일어서서 스데반을 내려다보고 계셨을까?",
    "visualGuide": "돌무더기 속에서 하늘을 우러르는 스데반('면류관')을 향해 하늘 보좌에서 기립하여 면류관을 들고 맞이하시는 예수님",
    "dossierMd": "■ B160 | 스데반 집사가 돌에 맞아 순교할 때, 왜 하늘 보좌에 '앉아 계시던' 예수님이 스데반을 향해 '일어서서(서 계신 것을 보노라)' 맞이하셨을까?\n• 시대·테마: 신약 11_초대교회·선교 | T08_구속사·모형 · T01_원어·언어유희\n• 본문: 행 7:55~56 (참조: 시 110:1, 히 10:12) | 삼각 연동: 인물 P152(스데반), P026(예수 그리스도), P020(청년 사울) | 사건 E162(스데반 집사의 설교와 최초 순교)\n• 호기심 질문: \"신약성경의 다른 모든 구절(히 1:3, 10:12, 골 3:1 등)에서는 부활·승천하신 예수님이 하나님 우편에 '앉아 계신다'고 기록하는데, 왜 오직 사도행전 7장 55~56절에서만 하나님 우편에 '서 계신다(헤스토타)'고 두 번이나 강조할까?\"\n• 행간의 진실 & 스토리텔링: 히브리서 10장 12절이 설명하듯 예수님이 하나님 우편에 '앉으셨다'는 것은 구속 사역을 다 마치시고 왕으로 통치하신다는 뜻입니다. 그런데 최초의 순교자 스데반이 산헤드린 공회원들의 돌에 맞아 피 흘리며 죽어가는 그 순간, 스데반이 성령이 충만하여 하늘을 우러러보았을 때 예수님은 보좌에 앉아 계시지 않고 하나님 우편에 벌떡 일어서 계셨습니다(헤스토타)! 어거스틴과 요한 크리스토무스 등 초대 교부들은 이 장면을 보며 눈물을 흘렸습니다:\n1. 첫째, 사랑하는 종이 땅에서 피 흘리며 싸우는 것을 차마 앉아서 보실 수 없어 기립 박수(Standing Ovation)와 영접의 자세로 일어서신 왕의 마중이었습니다! (스테파노스 Στέφανος라는 이름 뜻 자체가 '승리의 면류관'이듯, 주님이 면류관을 들고 일어서서 첫 순교자를 맞이하신 것입니다!)\n2. 둘째, 땅의 불법 재판관(산헤드린)들이 스데반에게 유죄 판결을 내릴 때, 하늘 법정에서 스데반의 변호인(파라클레토스)이신 예수님이 아버지 보좌 앞에서 증인으로 일어서셔서 \"이 종은 나의 참된 증인입니다!\"라고 변호해 주신 장면입니다.\n• 구속사 묵상 & 시각화: 예루살렘 성문 밖 돌무더기 속에서 무릎 꿇고 하늘을 올려다보는 스데반과, 열린 하늘 영광의 보좌 우편에서 자리에서 일어서서 두 팔을 벌리고 계신 예수님.",
