    "dossierMd": "■ [B161] 빌립 집사가 광야 길에서 만난 '에티오피아 여왕 간다게의 국고를 맡은 내시' — 왜 그는 예루살렘 성전까지 왔다가 빈손으로 돌아가며 이사야 53장을 읽고 있었을까?\n• 행 8:26~39 (참조: 신 23:1, 사 56:3~5)\nP153(P110 빌립 집사), P282(에티오피아 내시) · E163 | 고대 누비아(수단·에티오피아 메로에 왕국)에서는 여왕의 어머니가 국정을 총괄하며 '간다게(Kandake / Candace — 파라오처럼 여왕을 부르는 왕실 칭호)'라 불렸습니다. 그 나라 재무장관이었던 그는 참 하나님을 사모하여 수천 킬로미터 사막을 건너 예루살렘 성전까지 찾아왔으나, 신명기 23장 1절(\"고환이 상한 자나 음경이 잘린 자(내시)는 여호와의 총회에 들어오지 못하리라\") 율법 때문에 성전 뜰 안으로 한 발짝도 들어가지 못하고 문전박대를 당한 채 돌아가는 길이었습니다! 그런데 놀랍게도 그가 마차 위에서 읽고 있던 이사야서 두루마리의 이사야 53장(고난받는 종 예수 그리스도) 바로 세 장 뒤인 이사야 56장 3~5절에는 \"고자(내시)도 말하기를 나는 마른 나무라 하지 말라... 내가 내 집에서 아들과 딸보다 나은 기념물과 영원한 이름을 그에게 주리라!\"는 약속이 적혀 있었습니다! 율법의 돌 성전이 내쳤던 이방 내시를 성령님은 광야에서 복음으로 안아주시고 아프리카 대륙 최초의 크리스천으로 세우셨습니다.",
