    "dossierMd": "■ [B162] 사울이 다메섹 도상에서 들은 음성 — '사울아 사울아 네가 어찌하여 나를 박해하느냐 가시채(켄트론)를 뒷발질하기가 네게 고생이니라'\n• 행 9:4~5, 26:14\nP020(사울/바울), P026(예수 그리스도) · E164 | 행 26:14에서 예수님이 히브리(아람) 말로 사울에게 하신 말씀 중 '가시채(켄트론, κέντρον)'는 농부가 밭을 가는 황소가 엉뚱한 길로 가거나 버틸 때 엉덩이를 콕 찌르는 끝에 뾰족한 쇠침이 달린 긴 막대기입니다. 고집불통 황소가 가시채에 찔렸다고 화를 내며 뒷발로 가시채를 세게 걷어차면 어떻게 될까요? 주인은 다치지 않고 황소 자신의 발뒤꿈치만 쇠침에 더 깊이 찔려 피가 날 뿐입니다! 스데반의 빛나는 얼굴과 기도를 보며 양심의 가시채에 찔리면서도 애써 성도들을 박해하며 뒷발질하던 사울의 내면 고통을 주님이 정확히 꿰뚫어 보신 말씀이었습니다.",
