    "dossierMd": "■ [B164] 베드로가 욥바에서 머문 '무두장이(피혁공) 시몬의 집' — 왜 유대인들이 가장 부정하게 여기던 가죽 장인의 집이 바닷가에 있었으며 이방 선교의 출발점이 되었을까?\n• 행 9:43, 10:6, 10:32\nP029(베드로), P281(무두장이 시몬), P154(고넬료) · E165 | 사도행전 9~10장은 베드로의 숙소가 '바닷가에 있는 무두장이(뷔르세우스 — 동물의 죽은 가죽을 벗겨 무두질하는 피혁공) 시몬의 집'임을 무려 세 번이나 강조합니다! 유대 율법에서 매일 짐승의 시체와 피를 만지고 배설물·약품을 써서 심한 악취가 나는 무두장이 직업은 극도로 부정하게 여겨져 마을에서 50규빗 이상 떨어진 바닷가(바닷물로 가죽을 세척함)에 격리되어 살았으며, 미쉬나에서는 아내가 남편의 무두장이 직업을 이유로 이혼을 청구할 수 있을 정도였습니다. 정결 규례에 갇혀 있던 사도 베드로가 먼저 유대 사회의 편견을 깨고 '무두장이 시몬의 집'에 머물렀기에, 그 집 지붕 위에서 부정한 짐승 보자기 환상을 보고 이방인 백부장 고넬료의 집으로 걸어 들어가는 구속사적 장벽 돌파가 일어날 수 있었습니다.",
