    "dossierMd": "■ [B165] 예루살렘 교회의 첫 순교 사도 야고보(목 베임)와 옥에서 천사에게 옆구리를 쳐 깨움 받은 베드로 — 왜 로제(로데)는 너무 기뻐 문을 열어주지 않고 달려 들어갔을까?\n• 행 12:1~17\nP133(야고보), P029(베드로), P284(로데) · E166 | 헤롯 아그립바 1세가 야고보 사도를 칼로 처형하고 베드로까지 군사 네 패(16명, 양팔에 두 군사와 쇠사슬로 묶고 문밖 파수꾼 배치)에게 지키게 했으나, 내일이면 처형당할 베드로는 얼마나 깊은 평안 속에 잠들었는지 천사가 와서 옆구리를 쳐서(파탁사스 — 세게 때려서!) 깨워야 일어났습니다! 그리고 마가 요한의 어머니 마리아의 집 대문 앞에 가서 문을 두드리자, 계집종 로데(Rhoda — '장미꽃'이라는 뜻)가 베드로의 음성을 듣고 너무 기쁜 나머지 문을 열어주지도 않고 그냥 안으로 달려 들어가 \"베드로가 문밖에 서 있더라!\" 외쳤고, 방 안에서 베드로의 석방을 위해 간절히 기도하던 성도들은 정작 \"네가 미쳤다!\"고 반응했습니다. 우리의 불완전한 믿음보다 하나님의 응답이 언제나 더 빠르고 유머러스할 만큼 놀랍다는 초대교회의 생생한 실화입니다.",
