    "dossierMd": "■ [B166] 스스로 신이라 불리는 아첨을 받다 벌레('충')가 먹어 죽은 헤롯 아그립바 1세 — 요세푸스 『유대고대사』의 소름 돋는 교차 기록\n• 행 12:20~23\nP198(P185 헤롯 아그립바 1세) · E166 | 사도행전 12장 21~23절은 헤롯이 날을 택하여 왕복을 입고 단상에 앉아 연설할 때 백성들이 \"신(神)의 소리요 사람의 소리가 아니라!\" 외치자 영광을 하나님께 돌리지 아니하므로 주의 사자가 치니 벌레(스콜렉스 — 회충/기생충에 의한 급성 장천공·복막염)에게 먹혀 죽었다고 기록합니다. 유대 역사가 요세푸스 역시 『유대고대사』(19.8.2)에서 똑같은 사건을 이렇게 기록했습니다: \"아그립바 왕이 가이사랴 축제 둘째 날 전체가 순은(Silver) 실로 정교하게 직조된 눈부신 예복을 입고 이른 아침 원형극장에 들어서자, 아침 햇살이 은실 옷에 반사되어 신비로운 빛을 냈고 아첨꾼들이 그를 신이라 불렀다. 왕이 이를 제지하지 않자 곧바로 극심한 복통이 덮쳐 닷새 만에 숨을 거두었다.\" 성경과 일반 역사가 말씀대로 정확히 일치하는 대표적 현장입니다.",
