    "dossierMd": "■ [B167] 사도 바울의 본업 '장막 만드는 업(스케노포이오스)' — 천 조각이 아니라 길리기아 흑염소 털가죽('킬리키움 Cilicium')을 꿰매는 가죽 장인이었다!\n• 행 18:1~3, 고전 4:12\nP030(바울), P162(아굴라), P161(브리스길라) · E174 | 행 18:3에서 바울이 아굴라·브리스길라 부부와 함께 한 생업인 '장막을 만드는 업(스케노포이오스, σκηνοποιός)'은 바울의 고향인 길리기아(Cilicia) 수도 다소의 세계적 특산품과 직결되어 있습니다! 당시 길리기아 타우루스 산맥에서 자라는 거친 흑염소 털로 짠 방수 천과 가죽을 로마 제국 전역에서 아예 지역 이름을 따서 '킬리키움(Cilicium)'이라 불렀으며, 로마 군대의 군용 야영 텐트, 선박 덮개, 유목민 천막 제작에 필수 자재였습니다. 랍비 가말리엘 문하의 최고 엘리트 학자였던 바울은 성도들에게 재정적 짐을 지우지 않기 위해(살전 2:9 \"밤낮으로 일하면서\"), 뻣뻣한 염소 가죽과 천을 송곳으로 뚫고 꿰매느라 손가락이 갈라지고 피가 맺히는 자비량 노동을 평생 기쁨으로 감당했습니다(행 20:34 \"이 손으로 나와 내 동행들이 쓰는 것을 충당하여\").",
