    "dossierMd": "■ [B168] 고린도에서 바울을 재판한 아가야 총독 '갈리오(Gallio)' — 바울 선교 연대를 확정 짓는 '델피의 갈리오 비문'과 네로 황제의 스승 세네카의 친형!\n• 행 18:12~17\nP030(바울), P190(갈리오 총독) · E174 | 사도행전 18장 12절에 등장하는 아가야 총독 갈리오(루키우스 유니우스 갈리오 안나이아누스)는 당대 로마 최고의 스토아 철학자이자 네로 황제의 스승이었던 세네카(Seneca)의 친형이었습니다! 그리스 델피(Delphi) 아폴로 신전에서 발굴된 '갈리오 비문(Gallio Inscription)'에는 클라우디우스 황제가 제26차 임페라토르 칭호를 받은 시기인 서기 51년 여름~52년 여름 사이에 갈리오가 아가야 총독으로 재임했음이 정확히 새겨져 있어, 신약학에서 바울의 고린도 체류 연대(AD 50~52년)와 모든 바울 서신의 집필 연대를 역산하는 가장 결정적인 '절대 연대 기준점(Anchor Point)'이 되었습니다! 또한 갈리오가 유대인들의 고소를 기각해 준 판결 덕분에 기독교는 향후 10여 년간 로마 제국 전역에서 합법 종교(Religio Licita)의 우산 아래 폭발적으로 전파될 수 있었습니다.",
