    "dossierMd": "■ [B169] 에베소에서 마술사들이 불사른 마술책 값 '은 오만(50,000 데나리온)'과 아데미(아르테미스) 은감실 소동\n• 행 19:18~20, 24~28\nP030(바울), P187(데메드리오) · E176 | 당시 고대 지중해 세계에서 마술 주문의 본산은 에베소여서 주술 암호를 아예 '에베소 문자(Ephesia Grammata)'라고 불렀습니다. 주술의 비밀은 '남에게 절대 공개하지 않는 은밀함'에 있다고 믿었는데, 복음을 받아들인 에베소 성도들은 그 비싼 양피지 마술 비전서들을 중고로 팔지 않고 모든 사람 앞에서 공개적으로 불태워 버렸습니다! 그 책값이 노동자 5만 명의 하루 일당인 은 5만 드라크마/데나리온(오늘날 약 50억~70억 원 상당!)에 달했습니다. 또한 고대 세계 7대 불가사의였던 에베소 아데미(아르테미스) 신전의 축소판 은모형(은감실)을 만들어 팔던 은장색 조합장 데메드리오가 폭동을 일으켰을 때, 에베소 대극장(2만 5천 명 수용, 현재도 유적 존재)을 메운 군중의 함성 너머로 주의 말씀은 더욱 흥왕하여 세력을 얻었습니다.",
