    "visualGuide": "수많은 올리브 등잔불이 켜진 드로아 3층 다락방 창문과 추락한 청년 유두고('행운아'를 넘어 진짜 은혜의 사람)를 끌어안고 살려내는 바울",
    "dossierMd": "■ [B170] 드로아의 청년 유두고가 3층 창틀에 걸터앉아 졸다가 떨어진 이유 — '우리가 유두고가 산 것을 적지 않게 위로를 받았더라'의 원어 반전\n• 행 20:7~12\nP030(바울), P185(유두고) · E177 | 헬라어 이름 '유두고(Εὔτυχος, Eutychos)'의 뜻은 \"행운아 / 운 좋은 사람(Lucky)\"입니다! 주일 저녁(안식 후 첫날), 하루 종일 노동을 마치고 온 성도들이 다락방에 빽빽이 모였고, 의사 누가는 8절에서 \"우리 모인 윗다락에 등불을 많이 켰는데\"라는 과학적 관찰을 남깁니다! 수많은 올리브기름 등잔이 내뿜는 열기와 산소 부족(일산화탄소 증가), 그리고 바울의 밤중까지 이어진 강론 속에서 환기가 되는 3층 창틀에 앉아 있던 청년 유두고가 깊은 잠에 빠져 추락해 죽었습니다(의사 누가가 '죽은지라' 진단!). 그러나 바울이 엘리야·엘리사처럼 그 위에 엎드려 안고 살려냄으로써, 세상적인 우연의 '행운아(유두고)'가 아니라 부활의 주님 품에서 다시 살아난 진짜 은혜의 사람이 되었습니다.",
