    "dossierMd": "■ [B171] 바울이 로마로 압송될 때 탄 알렉산드리아 곡물선과 멜리데(몰타) 섬의 독사 사건 — 왜 원주민들은 바울을 '살인자'라 했다가 단숨에 '신(神)'이라 불렀을까?\n• 행 27:6, 28:1~6\nP030(바울), P195(백부장 율리오) · E182, E183 | 바울 일행 276명이 탔던 배는 이집트 나일강 곡창지대에서 로마 시민들에게 공급할 밀을 실어 나르던 대형 국영 수송선(알렉산드리아 호, 길이 약 45m·배수량 1,000톤급)이었습니다. 유라굴로 광풍을 뚫고 구조된 멜리데(오늘날 지중해 몰타 공화국, 성 바울 만 St. Paul's Bay)에서 바울이 추위에 떠는 사람들을 위해 직접 나뭇가지를 한 아름 거두어 불에 넣었을 때 독사가 열기로 나와 손을 물었습니다. 원주민들은 고대 그리스 정의의 여신 '디케(Dike / 공의, 행 28:4)'가 바다에서 살아남은 살인자를 끝내 심판한다고 생각했으나, 바울이 독사를 불에 떨어버리고 조금도 상하지 않자(막 16:18 성취) 도리어 그를 신이라 불렀고 섬의 추장 보블리오의 부친과 온 섬의 병자들이 치유받았습니다.",
