    "origTitle": "Tertius ('Number Three') the Scribe Allowed to Greet the Roman Church in His Own Name (Rom 16:22)",
    "scriptures": "롬 16:22; 갈 6:11",
    "hook": "바울이 고린도에서 불러준 로마서 대작을 파피루스에 받아 적은 필기 노예 '더디오(셋째)'는 어떻게 성경에 자기 이름으로 문안 인사를 남기게 되었을까?",
    "visualGuide": "고린도 가이오의 집에서 구술하는 바울과 갈대 펜으로 파피루스에 로마서 16장 22절 자신의 문안 인사를 기쁘게 적는 서기관 더디오",
    "dossierMd": "■ [B172] 로마서 16장 22절 '이 편지를 기록하는 나 더디오도 주 안에서 너희에게 문안하노라' — 대서기자(서기관) 노예 더디오와 바울의 친필 서명\n• 롬 16:22, 갈 6:11\nP030(바울), P177(더디오), P294(루포) · E175 | 로마서라는 인류 역사상 가장 위대한 신학 대작을 바울이 고린도 가이오의 집에서 구술(Dictation)할 때, 파피루스 위에 갈대 펜으로 한 글자 한 글자 받아 적은 대서기자(서기관)가 바로 '더디오(Tertius — 라틴어로 셋째라는 뜻, 당시 교육받은 필기 노예들에게 흔히 번호로 붙이던 이름 — 프리무스·세쿤두스·테르티우스!)'였습니다! 고대 서간문에서는 대서기자가 자신의 이름을 본문에 넣는 일이 거의 없었는데, 사도 바울은 노예 서기관 더디오를 단순한 타이피스트로 취급하지 않고 \"이 편지를 기록하는 나 더디오도 주 안에서 너희에게 문안하노라\"(롬 16:22)라며 성경 정경 안에 그의 이름을 주 안의 동역자로 당당히 새겨 넣게 배려했습니다!",
