    "dossierMd": "■ [B174] 고린도전서 9장 24~27절의 달리기와 권투 비유 — 올림픽 못지않게 고린도 시민들을 열광시켰던 '이스트미아 제전(Isthmian Games)'과 시들지 않는 면류관\n• 고전 9:24~27\nP030(바울) · E176 | 바울이 고린도에 머물던 서기 51년 봄은 고린도 지협에서 2년마다 열리는 범그리스 4대 체전 중 하나인 '이스트미아 제전(Isthmian Games)'이 열리던 해였습니다!(자비량 장막 제작자였던 바울도 이 경기장에 몰려든 수만 관중의 천막을 수리하며 경기를 직접 목격했을 것으로 추정됨). 이스트미아 경주 우승자에게 씌워주던 월계관은 금관이 아니라 금방 말라 비틀어지는 '야생 셀러리(파슬리)나 솔잎으로 엮은 화관(썩을 승리자의 관)'이었습니다. 바울은 그 말라버릴 풀잎 관 하나를 얻으려고 선수들이 10개월간 모든 음식을 절제하며 피땀 흘리는 모습을 가리키며, \"그들은 썩을 승리자의 관을 얻고자 하되 우리는 썩지 아니할 영원한 관을 얻고자 하노라!\"고 고린도 성도들의 가슴을 일깨웠습니다.",
