    "dossierMd": "■ [B175] 고린도전서 13장 12절 '우리가 지금은 거울로 보는 것같이 희미하나' — 유리 거울이 아닌 세계 최고 명품 '고린도 청동 거울'의 비밀\n• 고전 13:12\nP030(바울) · E176 | 오늘날의 은도금 평면 유리 거울은 르네상스 이후에야 발명되었고, 1세기 고대 세계의 거울은 모두 청동(구리 합금) 판을 매끄럽게 연마해 얼굴을 비춰 보는 금속 거울이었습니다. 그중에서도 고린도산 청동 거울은 당대 로마 제국 귀부인들이 최고로 치던 명품 특산물이었습니다! 그러나 아무리 세계 최고 기술로 닦은 고린도 명품 청동 거울이라 할지라도 금속 표면의 한계상 얼굴이 어른거리고 희미하게(엔 아이니그마티 — 수수께끼처럼) 보일 수밖에 없었습니다. 바울은 고린도 교인들이 가장 자부심을 느끼던 그 '고린도 청동 거울'을 예로 들며, 이 땅에서의 방언과 지식과 예언은 청동 거울처럼 부분적이고 희미하지만, 사랑의 완성이신 주님을 '얼굴과 얼굴을 대하여(프로소폰 프로스 프로소폰)' 뵐 그날에는 완전해질 것임을 노래했습니다.",
