    "dossierMd": "■ [B176] 고린도후서 2장 14절 '항상 우리를 그리스도 안에서 이기게 하시고(개선 행진을 하게 하시고) 아는 냄새를 나타내시는 하나님' — 로마 장군의 개선식('트리움푸스')\n• 고후 2:14~16\nP030(바울) · E177 | 고린도후서 2장 14절의 '이기게 하시고(트리암뷰온티, θριαμβεύοντι)'는 로마 원로원이 대승을 거둔 장군에게 부여하는 최고 영예인 '로마 개선 행진(Triumphus)'에 우리를 참여시켜 행진하게 하신다는 뜻입니다! 로마 개선식이 열릴 때 거리마다 신전의 제사장들이 향로를 흔들며 피워 올리는 향기로운 연기(향내)는 승리한 군사들에게는 '생명으로부터 생명에 이르는 승리의 향기'였지만, 행렬 맨 뒤에서 처형장을 향해 끌려가는 적군 포로들에게는 '사망으로부터 사망에 이르는 죽음의 냄새'였습니다(고후 2:16). 사도들은 세상 눈에는 고난당하는 포로처럼 보이나, 실제로는 승리하신 대장 예수 그리스도의 개선 행렬 안에서 그리스도의 향기를 온 세상에 퍼뜨리는 존재임을 선포한 것입니다.",
