    "dossierMd": "■ [B177] 갈라디아서 3장 24절 '율법이 우리를 그리스도께로 인도하는 초등교사(파이다고고스)가 되어' — 학교 선생님이 아니라 '가정 보호 노예'였다!\n• 갈 3:24~25\nP030(바울) · E170 | 개역성경의 '몽학선생'이나 개역개정의 '초등교사'라는 번역 때문에 학교에서 지식을 가르치는 교사로 오해하기 쉽지만, 헬라어 원문 '파이다고고스(παιδαγωγός — 아이를 끌고 가는 자)'는 지식을 가르치는 교사(디다스칼로스)가 아니었습니다! 1세기 그리스·로마 귀족 가정에서 주인의 아들이 6~7세가 되면 성인이 될 때까지 그림자처럼 따라붙어 등하교 길의 위험을 막아주고, 나쁜 길로 빠지면 회초리로 엄하게 훈육하며 진짜 스승(디다스칼로스) 앞까지 안전하게 데려다주는 '엄격한 보디가드 겸 훈육 노예'였습니다! 즉, 율법은 우리를 구원하는 구원자가 아니라, 우리의 죄를 깨닫게 하여 참된 스승이요 구원자이신 예수 그리스도 앞으로 손잡고 데려다주는 '파이다고고스'였으며, 그리스도 안에 들어온 우리는 이제 종이 아니라 하나님의 성숙한 상속자 아들이 되었다는 해방의 선언입니다.",
