    "dossierMd": "■ [B180] 에베소서 6장 '하나님의 전신갑주' — 바울은 왜 감옥에서 전신갑주를 묘사할 때 머리 투구부터가 아니라 '진리의 허리띠'부터 순서대로 적었을까?\n• 엡 6:13~17 (참조: 행 28:16)\nP030(바울) · E275 | 로마 가택 연금 중이던 바울의 왼손 손목에는 24시간 교대로 그를 지키는 로마 황실 친위대(프라이토리아니) 군인의 오른손과 길이 45cm짜리 쇠사슬이 연결되어 있었습니다(행 28:16). 바울은 자기 눈앞에 서 있는 그 로마 중장보병이 매일 아침 군장을 착용하는 실제 착용 순서 그대로 하나님의 전신갑주를 묘사했습니다! 로마 병사는 절대 투구나 방패부터 들지 않습니다. 제일 먼저 펄럭이는 튜닉 속옷을 한데 묶어 고정하는 ① 가죽 허리띠(진리의 띠)를 매야만 그 위에 ② 흉갑(의의 호심경)을 걸칠 수 있고, 몸을 숙여 ③ 군화(평안의 복음의 신, 바닥에 미끄럼 방지 징이 박힌 칼리가)를 단단히 묶은 뒤에야 일어서서 왼손에 ④ 대형 방패(믿음의 방패, 가죽을 겹쳐 물을 적셔 불화살을 끄는 투레오스)를 들고 머리에 ⑤ 투구(구원의 투구)를 쓴 뒤 마지막 오른손에 ⑥ 양날 단검(성령의 검 곧 하나님의 말씀, 마카이라)을 뽑아 들었습니다!",
