    "dossierMd": "■ [B181] 빌립보서 4장 18절 '내게는 모든 것이 있고 또 풍부한지라 이는 받으실 만한 향기로운 제물이요' — 로마 감옥에서 쓴 '정식 영수증(아페코)'\n• 빌 4:15~18\nP030(바울), P171(에바브로디도) · E274 | 당시 로마 감옥은 국가가 죄수에게 식사와 의복을 무료로 주지 않아 외부에서 성도나 가족이 사식을 넣어주어야 생존할 수 있었습니다. 빌립보 교회가 에바브로디도 편에 선교 헌금과 옥바라지 물품을 보내왔을 때, 바울이 빌립보서 4장 18절 첫머리에 쓴 \"내게는 모든 것이 있고(아페코 데 판타, Ἀπέχω δὲ πάντα)\"에서 동사 '아페코(Ἀπέχω)'는 1세기 파피루스 상업 문서에서 \"전액 완불로 정히 영수함(Paid in full / Received in full)!\"이라고 도장을 찍을 때 쓰던 공식 회계 영수증 용어였습니다! 바울은 성도들의 귀한 헌금에 대해 정식 영수증을 발행하듯 감사를 표하며, 그 헌금이 바울 개인의 호주머니가 아니라 하나님 보좌로 올라가는 '향기로운 번제물'이 되었다고 축복했습니다.",
