    "dossierMd": "■ [B184] 디도서 1장 12절 '그레데인 중의 어떤 선지자가 말하되 그레데인은 항상 거짓말쟁이요' — 제우스 신의 무덤을 자랑하던 에피메니데스의 역설\n• 딛 1:12\nP030(바울), P159(디도) · E278 | 논리학에서 유명한 '에피메니데스의 역설(거짓말쟁이 역설)'이 성경 디도서 1장 12절에 그대로 인용되어 있습니다! 그레데(크레타) 출신 시인 에피메니데스가 왜 자기 동족을 향해 \"그레데인은 항상 거짓말쟁이\"라고 일갈했을까요? 당시 그리스인들은 올림포스 주신 제우스가 영원히 죽지 않는 불멸의 신이라고 믿었는데, 유독 크레타섬 사람들만 관광 수입을 올리려고 \"우리 섬에 제우스의 무덤이 있다(제우스가 죽었다)!\"고 자랑하고 다녔기 때문입니다! 바울은 우상조차 죽어 무덤에 묻혔다고 거짓과 탐욕을 일삼는 그 섬에 디도를 남겨두어 참되고 변함없으신 살아계신 하나님의 질서를 세우게 했습니다.",
