    "dossierMd": "■ [B186] 야고보서의 저자 '주의 형제 야고보'의 별명이 왜 '낙타 무릎(Camel Knees)'이었을까? — 유세비우스 『교회사』의 증언\n• 약 1:1, 5:16~18\nP133(주의 형제 야고보) · E171 | 예수님의 친동생 야고보는 공생애 동안에는 형 예수님을 믿지 않았으나(요 7:5), 부활하신 예수님이 그에게 개인적으로 찾아가 만나주신 뒤(고전 15:7 \"그 후에 야고보에게 보이셨으며\") 완전히 변화되어 예루살렘 교회의 최고 기둥 지도자가 되었습니다. 역사가 헤게시푸스와 유세비우스(『교회사』 2.23)에 따르면, 그는 자기 형이신 예수님을 한 번도 '내 형'이라 부르지 않고 \"주 예수 그리스도의 종 야고보\"(약 1:1)라 낮추었으며, 매일 성전 돌바닥에 무릎을 꿇고 백성들의 죄를 용서해 달라고 어찌나 오래 기도했던지 양쪽 무릎의 피부가 낙타의 무릎처럼 두껍고 딱딱한 굳은살로 뒤덮여 '낙타 무릎'이라 불렸습니다. 그가 쓴 야고보서 5장 16절의 \"의인의 간구는 역사하는 힘이 큼이니라\"는 바로 그 낙타 무릎에서 나온 고백이었습니다!",
