    "dossierMd": "■ [B193] 에베소 교회에 약속하신 '생명나무의 열매'(계 2:7) — 왜 에베소 아데미 신전의 신성한 나무 우상을 버린 성도들에게 에덴의 진짜 생명나무를 약속하셨을까?\n• 계 2:1~7\nP122(사도 요한), P026(예수 그리스도) · E200 | 에베소의 주신 아데미(아르테미스) 신전은 고대 종려나무/대추야자나무 성소에서 유래하여, 에베소 동전마다 아데미 여신상과 함께 '신성한 생명의 나무'가 새겨져 있었고 신전 경내는 범죄자도 들어오면 체포되지 않는 피난처로 여겨졌습니다. 우상 숭배의 도시 한복판에서 아데미의 가짜 나무와 타협하지 않고 인내한 에베소 성도들에게, 주님은 창세기 3장 이후 닫혀 있던 '하나님의 낙원에 있는 진짜 생명나무의 열매'를 주어 먹게 하리라고 약속하셨습니다.",
