    "dossierMd": "■ [B194] 서머나 교회에 주신 위로 '네가 열흘 동안 환난을 받으리라 죽도록 충성하라 그리하면 생명의 관(스테파노스)을 네게 주리라' — 서머나의 자랑 '아름다운 관'과 폴리캅의 순교\n• 계 2:8~11 (참조: 단 1:12)\nP122(사도 요한), P026(예수 그리스도) · E200 | 서머나(Smyrna — 이름 뜻 자체가 '몰약 Myrrh', 으깨어질수록 향기를 내는 고난의 향품!) 시는 파고스 언덕 꼭대기를 둘러싼 웅장한 건물들이 멀리서 보면 왕관처럼 보여 고대 세계에서 '아시아의 면류관(The Crown of Asia)'이라는 별명을 자랑하던 도시였습니다. 또한 서머나 시민들은 로마 황제 숭배에 가장 광적으로 앞장서서 그리스도인들의 재산을 몰수해 극빈자로 만들었습니다. 주님은 그들에게 다니엘과 세 친구가 바벨론에서 시험받았던 것처럼(단 1:12 열흘간의 시험) 환난은 영원하지 않고 하나님이 정하신 짧은 기간('열흘 동안')뿐이니 죽도록 충성하면 세상의 돌 왕관이 아닌 '영원한 생명의 면류관'을 주시겠다고 약속하셨고, 실제로 사도 요한의 제자였던 서머나 감독 폴리캅(Polycarp)은 서기 155년 \"86년간 주님은 나를 한 번도 모른 척하지 않으셨는데 내가 어찌 내 왕을 모독하리요!\"라고 외치며 화형대에서 순교함으로 이 말씀을 성취했습니다.",
