    "dossierMd": "■ [B195] 버가모 교회가 있는 곳은 왜 '사탄의 권좌(왕좌)가 있는 곳'(계 2:13)이라 불렸을까? — 산꼭대기 제우스 대제단과 로마 최초의 아우구스투스 황제 신전\n• 계 2:12~17\nP122(사도 요한), P026(예수 그리스도) · E200 | 해발 335m 바위산 정상(아크로폴리스)에 세워진 소아시아 수도 버가모(페르가몬)에는 산 중턱 전체를 깎아 만든 거대한 말발굽 모양의 '제우스 대제단(현재 베를린 페르가몬 박물관에 원형 이전 전시!)'이 위압적인 왕좌(Throne) 모양으로 도시를 내려다보고 있었고, 소아시아 최초로 로마 황제 아우구스투스를 살아있는 신으로 숭배하는 황제 신전과 뱀 모양의 의술 신 아스클레피오스 신전까지 자리 잡은 우상 권력의 심장부였습니다! 그 사탄의 보좌 한복판에서도 믿음을 지키다 달군 구리 황소 속에서 첫 순교자가 된 안디바를 주님은 \"내 충성된 증인\"이라 친히 이름을 불러 기억하셨습니다.",
