    "dossierMd": "■ [B197] 두아디라 교회의 '자칭 선지자 이세벨' — 왜 염색업과 동업 조합(길드 Guild)의 도시 두아디라에서 우상의 제물 문제가 치명적이었을까?\n• 계 2:18~29 (참조: 행 16:14)\nP122(사도 요한), P165(두아디라 출신 루디아) · E200 | 빌립보의 자주 장사 루디아의 고향이기도 한 두아디라는 고대 세계에서 직조업, 자색 염색업, 청동 세공업 등 상공업 동업 조합(길드, Guild)이 가장 촘촘하게 발달한 산업 도시였습니다. 당시 상인이 길드에 가입하지 않으면 원료 구매도 판매도 불가능했는데, 문제는 모든 길드 정기 모임이 수호신(아폴로·황제) 신전 안에서 우상 제물을 함께 먹고 음행하는 잔치로 진행되었다는 점입니다! 그때 교회 안의 거짓 여선지자('이세벨')가 \"먹고살려면 길드 신전 잔치에 참석해 우상 제물도 먹고 적당히 타협해도 괜찮다\"고 성도들을 미혹했기에 주님이 불꽃 같은 눈으로 이를 엄중히 경고하신 것입니다.",
