    "title": "'네가 살았다 하는 이름은 가졌으나 죽은 자로다, 일깨지 아니하면 내가 도둑같이 이르리니!'(계 3:1~3) — 난공불락 절벽만 믿고 졸다가 역사상 두 번이나 밤중에 기습 함락된 사데 성의 흑역사!",
