    "visualGuide": "수직 절벽 위 요새만 믿고 파수꾼이 잠들었다가 밤중에 절벽 틈으로 기어오른 적군에게 두 번이나 함락된 사데 아크로폴리스와 흰 옷 입은 남은 자들",
    "dossierMd": "■ [B198] 사데 교회에 하신 말씀 '네가 살았다 하는 이름은 가졌으나 죽은 자로다, 일깨어 도둑같이 이르기 전에 굳게 하라' — 기원전 546년과 214년 두 번이나 절벽 위로 몰래 올라온 적군에게 밤중에 함락된 사데 성의 흑역사!\n• 계 3:1~6\nP122(사도 요한), P026(예수 그리스도) · E200 | 고대 리디아 왕국의 수도(황금의 왕 크로이소스의 수도)였던 사데(Sardis)는 삼면이 수직에 가까운 450m 절벽 위에 세워진 천혜의 난공불락 요새여서, 시민들은 \"우리 성벽은 절대 뚫리지 않는다\"고 자만하여 밤에 성벽 초병조차 제대로 세우지 않았습니다. 그러다 기원전 546년 페르시아 고레스 군대의 병사 한 명이 사데 병사가 절벽 아래로 떨어뜨린 투구를 주우러 내려왔다가 올라가는 비밀 바위 틈새를 눈여겨보았다가 한밤중에 절벽을 타고 올라와 파수꾼 하나 없는 사데 성을 단숨에 함락시켰고, 330년 뒤 안티오쿠스 3세 때도 똑같은 방식으로 밤중에 또 함락되었습니다! 예수님이 사데 교회에게 \"만일 일깨지 아니하면 내가 도둑같이 이르리니!\"(계 3:3)라고 하신 말씀은 사데 시민이라면 누구나 뼈아프게 아는 도시의 역사적 수치(영적 방심과 교만)를 정통으로 찌른 경종이었습니다.",
