    "dossierMd": "■ [B199] 빌라델비아 교회에 약속하신 '내 하나님의 성전에 기둥이 되게 하리니 그가 결코 다시 나가지 아니하리라' — 서기 17년 대지진으로 무너진 빌라델비아에서 홀로 서 있던 기둥!\n• 계 3:7~12\nP122(사도 요한), P026(예수 그리스도) · E200 | 지진 단층대 위에 위치한 빌라델비아(오늘날 알라셰히르)는 서기 17년 소아시아 대지진 때 도시 전체가 처참하게 무너져 내렸고, 그 후로도 수십 년간 여진이 계속되어 시민들이 건물 안에 들어가 살기를 두려워해 도시 밖 들판에 천막을 치고 들락날락하며 불안하게 살았습니다. 그 지진 트라우마의 도시에서 적은 능력을 가지고도 배교하지 않은 빌라델비아 성도들에게, 주님은 \"이기는 자는 아무리 땅이 흔들려도 절대 무너지지 않는 내 하나님의 성전에 영원한 '기둥(스튈로스)'이 되게 하리니, 지진 피해 성 밖으로 도망치듯 결코 다시 나가지 아니하리라!\"(계 3:12)는 가장 맞춤형의 감격스러운 약속을 주셨습니다(실제로 오늘날 알라셰히르 유적지에도 비잔틴 시대 사도 요한 기념 교회의 거대한 돌기둥들만 우뚝 서 있어 이 말씀을 시각적으로 증언합니다!).",
