    "dossierMd": "■ [B210] 사사 입다는 암몬과의 전쟁에서 승리한 뒤 정말로 자기 외동딸을 불에 태워 인신제사(번제)로 바쳤을까, 아니면 평생 성소 처녀로 드렸을까?\n• 삿 11:30~40 (참조: 신 12:31, 출 38:8)\nP243(입다), P243(입다의 딸) · E057 | 구약 최대의 해석 난제 중 하나입니다. 크게 두 가지 정통 해석이 공존합니다: ① 문자적 비극설: 사사 시대의 영적 무지에 빠진 입다가 이방 모압·암몬의 인신제사 풍습을 혼합하여 하나님이 가장 가증히 여기시는(신 12:31; 렘 7:31) 어리석은 서원을 문자적으로 집행한 사사 시대 타락의 비극이라는 해석과, ② 영구 성소 봉헌(평생 독신 헌신)설: 입다의 딸이 두 달 동안 산에 올라가 '죽음'이 아니라 '자기의 처녀로 죽을 것(평생 결혼하지 못해 대가 끊기는 것)'을 애곡했고(삿 11:37~38), 39절에서도 \"입다가 서원한 대로 딸에게 행하니 딸이 남자를 알지 못하니라\"고 결론짓는 점(만약 불에 태워 죽였다면 '남자를 알지 못하니라'는 설명이 불필요함!)에 근거해 실로 회막에서 평생 독신으로 수종드는 여인(출 38:8; 삼상 2:22)으로 구별해 드렸다는 해석입니다. 어느 쪽이든 섣부른 서원의 위험성을 엄중히 경고합니다.",
