    "dossierMd": "■ [B211] 삼손은 근육질의 거구 보디빌더 체형이었을까, 아니면 평범한 체격의 사람이었을까?\n• 삿 16:5~6\nP016(삼손), P317(들릴라) · E058 | 영화나 그림에서는 삼손을 헐크 같은 근육질 거인으로 그리지만, 만약 삼손의 팔뚝과 근육이 외형적으로도 거대했다면 블레셋 방백들이 들릴라에게 은 일천일백 개씩 뇌물을 주며 \"삼손을 꾀어 무엇으로 말미암아 그 큰 힘이 생기는지 알아내라!\"(삿 16:5)고 궁금해했을 리가 없습니다!(\"아, 저 엄청난 근육에서 힘이 나오는구나\" 하고 바로 알았을 것입니다!). 즉, 삼손의 겉모습은 일반 성인 남성과 다를 바 없는 평범한 체격이었는데, 오직 '여호와의 영이 그에게 강하게 임하실 때'(삿 14:6, 19; 15:14)만 인간 상식을 초월한 괴력이 폭발했기에 블레셋 사람들이 그 힘의 비밀 출처를 그토록 캐내려 했던 것입니다!",
