    "dossierMd": "■ [B212] 소년 다윗이 물맷돌로 골리앗을 쓰러뜨린 것은 장난감 새총의 요행이었을까? — 시속 160km의 고대 치명적 저격 무기 '물매(켈라)'!\n• 삼상 17:40, 49, 삿 20:16\nP021(다윗), P249(골리앗) · E018 | 흔히 다윗의 물매를 아이들 고무줄 새총 정도로 가볍게 생각하지만, 고대 근동 전쟁사(앗수르·이집트 부조 및 사사기 20:16 \"왼손잡이 칠백 명은 물매로 돌을 던지면 조금도 틀림이 없는 자들\")에서 '물매(켈라)'는 오늘날의 권총·저격총에 맞먹는 치명적인 원거리 정밀 타격 무기였습니다! 시냇가에서 고른 매끄럽고 밀도 높은 황산바륨 계통 조약돌(직경 5~7cm, 무게 약 150~250g — 야구공보다 무거움!)을 가죽 줄에 넣어 초당 6~7회전으로 돌려 던지면 초속 45m(시속 약 160km 이상!)의 탄속으로 날아가 투구 밖으로 노출된 미간 두개골을 즉사시킬 위력을 가졌습니다. 광야에서 사자와 곰으로부터 양을 지키며 수만 번 물매를 연습했던 다윗의 성실한 일상 준비 위에 만군의 여호와의 이름이 함께하신 승리였습니다.",
