    "dossierMd": "■ [B213] 사울 왕이 엔돌의 신접한 여인을 찾아갔을 때 땅에서 올라온 존재는 진짜 사무엘 선지자의 영이었을까, 아니면 악령의 변장이었을까?\n• 삼상 28:7~19 (참조: 대상 10:13~14)\nP020(사울), P019(사무엘) · E064 | 기독교 역사 속 대표적 난제입니다. 루터·칼빈 등 일부는 악령이 사무엘로 가장한 것이라 보았으나, 본문 문맥을 자세히 보면 놀라운 반전이 있습니다: 정작 강령술을 시도하던 엔돌의 무당 자신이 사무엘이 나타나자 \"크게 소리 지르며(기절초풍하며)\"(삼상 28:12) 놀랐습니다! 왜냐하면 평소 자기가 부리던 속임수나 잡신이 아니라, 하나님께서 사울에게 최후의 심판을 선포하시기 위해 예외적인 주권으로 실제 사무엘(또는 하나님의 엄중한 심판 계시)을 보내셨기 때문입니다! 성경 본문도 '가짜 사무엘'이라 하지 않고 명백히 \"사무엘이 사울에게 이르되\"(15, 16절)라고 기록하며, 그 예언대로 다음 날 길보아 산에서 사울과 아들들이 전사했습니다(단, 역대상 10:13은 사울이 신접한 자에게 물은 것 자체가 여호와께 죽임을 당한 결정적 죄악이었다고 못 박습니다).",
