    "dossierMd": "■ [B214] 웃사가 수레에서 떨어지려는 언약궤를 붙잡았다가 그 자리에서 죽은 것(삼하 6:6~7)은 너무 가혹한 처사가 아니었을까?\n• 삼하 6:3~7, 민 4:15, 대상 15:13\nP021(다윗), 웃사 · E066 | 언약궤가 땅에 떨어질까 봐 선한 의도로 손을 댔는데 왜 하나님이 치셨을까요? 첫째, 하나님은 민수기 4장 15절과 7장 9절에서 언약궤는 절대 수레에 싣지 말고 반드시 고핫 자손 레위인이 금고리에 채를 꿰어 '어깨에 메고' 운반하라고 엄명하셨습니다. 그런데 다윗과 웃사는 하나님의 말씀 대신 블레셋 사람들이 우상 다루듯 썼던 편리한 방식('새 수레', 삼상 6:7)을 그대로 모방했습니다! 둘째, 웃사는 아비나답의 집에서 20년 넘게 언약궤와 함께 살면서 하나님의 거룩하심에 대한 경외감을 잃어버리고 언약궤를 자기 집 가구 다루듯 만진 영적 매너리즘(불경외함)에 빠져 있었습니다. 훗날 다윗은 역대상 15장 13절에서 \"전에는 너희(레위인)가 메지 아니하였으므로 우리 하나님 여호와께서 우리를 찢으셨으니 이는 우리가 규례대로 그에게 구하지 아니하였음이라\"고 정확히 회개했습니다. 하나님의 일은 목적뿐 아니라 방법도 하나님의 말씀대로여야 합니다.",
