    "dossierMd": "■ [B215] 압살롬이 에브라임 수풀에서 상수리나무에 걸렸을 때, 정말 그의 '긴 머리카락'이 나뭇가지에 엉켜 매달린 것일까?\n• 삼하 18:9\nP256(압살롬), P252(요압) · E068 | 흔히 동화책에서 압살롬의 탐스러운 긴 머리카락이 나뭇가지에 칭칭 감겨 매달린 것으로 그리지만, 사무엘하 18장 9절 원문에는 '머리카락(세아르)'이라는 단어가 없고 정확히 \"그의 머리(로쇼, רֹאשׁוֹ — 머리통/목 부분)가 상수리나무 가랑이 사이에 끼이매\"라고 기록되어 있습니다! 노새를 타고 전속력으로 달리다 굵고 빽빽한 상수리나무 Y자 나뭇가지 틈에 머리(물론 그가 자랑하던 무거운 머리숱과 투구가 시야를 가리고 걸림돌이 됨)가 꽉 끼이고 노새만 밑으로 빠져나간 것입니다. 백성들의 마음을 훔치던 그의 가장 큰 외모 자랑거리가 결국 그의 목을 조르는 올무가 되었습니다.",
