    "dossierMd": "■ [B216] 다윗이 인구조사를 한 것이 왜 전염병으로 7만 명이나 죽을 만큼 큰 죄였을까? — 출애굽기 30장 '생명의 속전(반 세겔)' 누락과 교만!\n• 삼하 24:1~15, 대상 21:1, 출 30:12\nP021(다윗), P252(요압) · E070 | 국가가 행정이나 군사를 위해 인구조사를 하는 것 자체가 죄는 아닙니다(민수기에서도 두 번이나 하나님 명령으로 인구조사를 함!). 그렇다면 다윗의 인구조사는 왜 그토록 큰 죄였을까요? 첫째, 전쟁이 다 끝나고 평안해진 노년에 다윗이 \"내 군대가 이렇게 많다!\"며 하나님의 은혜 대신 자신의 군사력을 과시하려는 교만에서 출발했기 때문입니다(불신앙적인 요압조차 \"왕이여 어찌하여 이 일을 기뻐하시나이까\"라며 9개월간 말렸음!). 둘째, 출애굽기 30장 12절은 \"네가 이스라엘 자손의 수를 조사할 때에 조사받은 각 사람은 자기의 생명의 속전(반 세겔)을 여호와께 드릴지니 이는 그들을 계수할 때에 그들 중에 질병(온역)이 없게 하려 함이라\"고 명시했습니다. 즉, 백성의 머릿수를 센다는 것은 \"이 백성의 소유권이 왕인 내게 있다\"고 주장하는 행위이므로 반드시 생명의 속전을 바쳐 하나님의 소유임을 고백해야 했는데, 다윗이 이를 어기고 자기 소유인 양 군대 수를 계수했기에 율법 경고 그대로 온역(전염병)이 임한 것입니다.",
