    "dossierMd": "■ [B217] 솔로몬의 지혜 재판에 등장한 두 여인('창기 두 여자') — 왜 남편도 없이 한집에 단둘이 살던 여인들의 송사를 왕이 직접 재판했을까?\n• 왕상 3:16~28\nP022(솔로몬) · E071 | 당시 사회 밑바닥 계층이었던 창기(조노트) 두 여자는 증인도 없고(\"집에 우리 둘 외에는 아무도 없었나이다\", 18절) 신분도 천하여 하급 지방 성문 재판소에서는 아무도 진실을 가려줄 수 없어 기각당하자 최종 항소심인 왕의 어전까지 올라온 사건이었습니다. 솔로몬은 당대 가장 천대받던 여인들의 억울함까지 귀 기울여 들었으며, \"산 아이를 둘로 나누라!\"는 충격 요법을 통해 혈육의 권리를 주장하는 가짜 어미와 차라리 아이를 포기할지언정 생명만은 살리려는 진짜 어머니의 '타오르는 모성애(히브리어 니크메루 라하메하 — 자궁/창자가 불타듯 뒤틀리다!)'(왕상 3:26)를 단번에 판별해 냈습니다.",
