    "dossierMd": "■ [B218] 솔로몬은 구약에서 분명히 우상 숭배로 타락해 책망받았는데(왕상 11장), 결국 구원받았을까 버림받았을까? — 전도서의 노년 회개와 느헤미야·사무엘하의 증언\n• 삼하 7:14~15, 왕상 11:9~13, 전 12:13\nP022(솔로몬) · E072, E224 | 하나님은 다윗 언약(삼하 7:14~15)에서 솔로몬에 대해 미리 약속하시기를 \"그가 만일 죄를 범하면 내가 사람의 매와 인생의 채찍으로 징계하려니와, 사울에게서 내 은총을 빼앗은 것같이 그에게서 빼앗지는 아니하리라\"고 보증하셨습니다! 솔로몬은 노년에 이방 후궁들의 우상에 미혹되어 나라가 쪼개지는 혹독한 징계(사람의 매)를 받았으나, 유대 정통 전승과 교부들은 그가 생의 마지막 황혼기에 통렬히 회개하며 남긴 참회록이 바로 『전도서』(헛되고 헛되니 모든 것이 헛되도다... 일의 결국을 다 들었으니 하나님을 경외하고 그의 명령들을 지킬지어다)라고 봅니다(또한 대하 11:17에서도 솔로몬 초기의 길을 '다윗과 솔로몬의 길'이라 부르며 마 1:6~7 메시아 족보와 히 11장 다윗·사무엘의 반열과 이어짐).",
