    "dossierMd": "■ [B223] 시편 137편 9절 '네 어린 것들을 바위에 메어치는 자는 복이 있으리로다' — 왜 성경 시편에 이토록 무서운 저주 시(임프레카토리 시편)가 들어 있을까?\n• 시 137:1~9 (참조: 사 13:16, 렘 51:24)\nP046 외 바벨론 포로 시인 · E088 | 바벨론 강가 버드나무에 수금을 걸어 놓고 운 시편 137편의 마지막 구절은 개인의 사적인 분풀이 폭력이 아닙니다! 바벨론 군대가 예루살렘을 함락할 때 유다의 젖먹이 아이들을 어미 품에서 빼앗아 돌에 메어쳐 죽였던 잔혹한 전쟁 범죄에 대해, 이미 하나님께서 이사야 13장 16절과 예레미야 51장 24절에서 \"바벨론이 시온에서 행한 모든 악을 내가 그들의 눈앞에서 그대로 갚으리라\"고 선언하신 하나님의 공의로운 심판 법정(Lex Talionis)이 속히 집행되기를 눈물로 호소하는 탄원 시입니다. 성도는 원수 갚는 것을 내 손으로 하지 않고 오직 공의의 재판장이신 하나님의 손에 맡겨 드림으로(롬 12:19) 억울함을 승화시킵니다.",
