    "dossierMd": "■ [B224] 전도서 11장 1절 '너는 네 떡을 물 위에 던지라 여러 날 후에 도로 찾으리라' — 물에 빵을 던지면 다 불어서 못 먹는데 무슨 뜻일까?\n• 전 11:1~2\nP022(솔로몬) · E224 | 고대 중동에는 두 가지 생생한 배경이 있습니다. 첫째는 해상 무역과 구제: 지중해와 홍해로 나가는 무역선에 곡식(떡)을 실어 멀리 바다 너머로 보내거나, 당장 보답할 길 없는 가난한 이웃에게 아낌없이 구제의 떡을 흘려보내면 여러 날(세월)이 흐른 뒤 반드시 풍성한 열매로 돌아온다는 뜻입니다. 둘째는 나일강·유프라테스강 범람 농법: 강물이 범람했다가 빠지기 시작할 때 아직 물기가 찰랑거리는 진흙탕 물 위로 씨앗(떡의 원료인 밀·보리 종자)을 흩어 뿌리면, 당장은 물속에 버리는 것 같아 보이지만 물이 빠진 뒤 비옥한 토양에서 30배, 60배, 100배의 추수로 도로 찾게 된다는 믿음의 파종 원리입니다!",
