    "dossierMd": "■ [B227] 아기 예수님을 찾아온 '동방박사(마고이)'는 정말 '세 사람'이었고 마구간 구유로 찾아왔을까?\n• 마 2:1~11\nP026(예수 그리스도), P333(동방박사들), P196(헤롯 대왕) · E122 | 성탄절 연극의 단골 오해 두 가지입니다! 첫째, 마태복음 2장에는 동방박사가 '세 명'이라는 말이 전혀 없습니다! 그들이 바친 예물이 황금·유향·몰약 세 가지여서 후대에 세 사람(가스파르·멜키오르·발타사르)이라는 전설이 붙었을 뿐, 당시 파르티아(페르시아·바벨론)의 제사장 겸 천문학자 계급인 '마고이(Μάγοι, 다니엘이 바벨론 박수장으로 세워 놓은 메시아 대망 전통의 후예들!)'가 호위병과 낙타 행렬을 거느리고 온 대규모 사절단이었습니다(그래서 마 2:3에 헤롯 왕뿐 아니라 \"온 예루살렘이 보고 소동한지라\"고 기록됨!). 둘째, 그들이 도착했을 때 예수님은 갓 태어난 마구간 구유 속 아기(브레포스)가 아니라, 이미 시간이 흘러 '집(오이키아)'에 들어가 계신 최대 두 살 미만의 '어린아이(파이디온)'(마 2:11, 16) 상태였습니다!",
