    "dossierMd": "■ [B228] 예수님은 정말 서기 1년(AD 1년)에 태어나셨을까? 왜 예수님의 실제 탄생 연도는 '기원전(BC) 4~6년경'일까?\n• 마 2:1, 2:19, 눅 2:1~2\nP026(예수 그리스도), P196(헤롯 대왕) · E024 | 오늘날 우리가 쓰는 서기(AD, Anno Domini — 주님의 해) 연호는 서기 525년 로마의 수도사 디오니시우스 엑시구스가 로마 건국 기원(AUC)을 예수님 탄생 기준 연도로 바꾸어 계산하면서 헤롯 대왕의 사망 연도를 약 4~6년 늦게 착오 계산한 데서 비롯되었습니다. 유대 역사가 요세푸스의 기록과 월식(Lunar Eclipse) 천문 기록을 통해 헤롯 대왕이 기원전 4년(BC 4년) 봄 유월절 직전에 사망했음이 확증되었으므로, 헤롯 대왕 생전에 베들레헴에 태어나신 예수님의 실제 역사적 탄생 연도는 기원전 5~6년경(BC 6~4년)입니다.",
