    "dossierMd": "■ [B229] 산상수훈의 '오른편 뺨을 치거든 왼편도 돌려대며, 속옷을 가지고자 하는 자에게 겉옷까지 주라'(마 5:39~40)에 숨겨진 1세기 로마·유대 법정 코드\n• 마 5:39~41\nP026(예수 그리스도) · E131 | 오른손잡이가 마주 선 상대방의 '오른편 뺨'을 때리려면 주먹이 아니라 '오른손 손등(Backhand slap)'으로 후려쳐야만 맞습니다! 당시 유대 미쉬나 법에서 손바닥으로 때리는 것보다 손등으로 뺨을 치는 것은 노예나 하등 인간을 모욕할 때 쓰는 극도의 인격 모독 행위(벌금도 두 배!)였습니다. 그때 비굴하게 도망치거나 똑같이 주먹을 날리는 대신 '왼편 뺨'을 당당히 돌려대면, 상대방은 더 이상 손등으로 모욕할 수 없고 동등한 인격체로 마주해야 합니다! 또한 다음 절의 '오 리(1로마 마일 = 1,000보)를 가게 하거든 그 사람과 십 리를 동행하라'(41절)는 로마 점령군 병사가 식민지 유대 민간인을 잡아 군장 배낭을 딱 1마일(오 리)까지만 강제로 메게 할 수 있었던 '로마 군사 징발법(앙가레이아)'을 배경으로 합니다. 첫 오 리는 억지 노예로 끌려가는 길이지만, 스스로 자원하여 다음 오 리(십 리)를 더 걸어줄 때 성도는 로마 제국의 피해자가 아니라 로마 군인조차 감동시키는 하나님 나라의 자유인이 됩니다!",
