    "dossierMd": "■ [B231] 마태복음 12장 31~32절 '성령을 모독하는 죄(성령 훼방죄)는 사하심을 얻지 못하겠고' — 내가 혹시 순간적으로 나쁜 생각을 해서 용서받지 못할 죄를 지은 것은 아닐까?\n• 마 12:24~32, 막 3:28~30\nP026(예수 그리스도) · E135 | 양심 여린 성도들이 가장 많이 불안해하는 구절입니다. 그러나 마가복음 3장 30절은 예수님이 왜 이 말씀을 하셨는지 그 이유를 명확히 밝혀줍니다: \"이는 그들(바리새인들)이 말하기를 '그가 더러운 귀신이 들렸다' 함이러라!\" 즉, 성령 훼방죄는 연약한 성도가 순간적인 의심이나 말실수를 한 것이 아니라, 눈앞에서 성령의 능력으로 귀신이 쫓겨나고 맹인이 눈을 뜨는 명백한 하나님의 역사를 보고도 끝까지 마음을 완악하게 닫고 \"저건 사탄(바알세불)의 짓이다!\"라며 구원자 예수 그리스도와 성령의 사역 자체를 죽을 때까지 고의적·최종적으로 거부하는 불신앙을 뜻합니다. 지금 \"내가 혹시 성령을 근심하게 한 건 아닐까?\" 애통해하며 회개하는 마음 자체가 이미 성령님이 내 안에 살아 역사하고 계신다는 가장 확실한 증거입니다!",
