    "visualGuide": "다섯 행각이 있는 예루살렘 베데스다 쌍둥이 연못 유적과 물에 들어갈 필요 없이 말씀 한마디로 자리를 들고 일어나게 하시는 예수님",
    "dossierMd": "■ [B232] 베데스다 연못의 '물이 움직일(동할) 때 천사가 내려와 휘젓는다'는 구절(요 5:3하~4)은 왜 성경에 괄호 [ ] 처리가 되어 있을까?\n• 요 5:2~9\nP026(예수 그리스도) · E133 | 요한복음 5장 3절 하반절~4절(\"물의 움직임을 기다리니 이는 천사가 가끔 못에 내려와 물을 움직이게 하는데...\")에 [ ] 괄호가 쳐져 있는 이유는, 초기 가장 오래된 헬라어 사본들(시내산 사본, 바티칸 사본 등)에는 이 설명이 없고 후대 필사본에 7절에서 병자가 말한 \"물이 움직일 때에 나를 못에 넣어 주는 사람이 없어\"라는 배경을 독자들에게 설명해 주려는 필사자의 난외 주석(민간 신앙 배경 설명)이 본문 안으로 들어왔기 때문입니다. 실제로 베데스다 연못은 간헐천이나 북쪽 저수조에서 수문을 열어 물을 흘려보낼 때 수면이 부글거리며 붉은 광물질이 올라오는 현상이 있었는데, 미신적인 기다림에 매여 38년간 누워 있던 병자에게 진짜 생수의 주인이신 예수님이 찾아오셔서 물에 들어갈 필요도 없이 말씀 한마디로 고쳐주셨습니다!",
