    "dossierMd": "■ [B233] 막달라 마리아는 정말 '창녀(몸을 파는 여인)' 출신이었을까? — 서기 591년 교황 그레고리우스 1세의 설교가 만든 1,400년의 역사적 누명!\n• 눅 8:1~3, 요 20:1~18\nP140(막달라 마리아), P026(예수 그리스도) · E136, E156 | 영화나 뮤지컬에서는 늘 막달라 마리아를 '창녀 출신 여인'으로 묘사하지만, 성경 66권 어디에도 막달라 마리아가 창녀나 간음한 여인이었다는 기록은 단 한 줄도 없습니다! 성경은 오직 그녀를 \"일곱 귀신이 나간 자\"(눅 8:2)이자 갈릴리 어업 중심지 막달라(미그달 눈야 — 물고기의 망대) 출신의 부유한 여인으로서 '자기들의 소유(재산)로 예수님과 제자들을 섬기던 핵심 후원자'(눅 8:3)이며 십자가와 부활의 제1목격자로 기록합니다! 왜 이런 누명이 씌워졌을까요? 서기 591년 로마 교황 그레고리우스 1세가 설교하면서 누가복음 7장의 '갈릴리의 죄인 여인'과 요한복음 12장의 '베다니 마리아'와 누가복음 8장의 '막달라 마리아' 세 명의 전혀 다른 여인을 한 사람으로 합쳐서 설교하는 바람에 서구 교회에서 1,400년 동안 억울한 오해를 받았던 것입니다!",
