    "visualGuide": "다가올 미래를 위해 현재의 수수료 이익을 과감히 내려놓는 청지기와 천국을 위해 재물을 선용하는 성도의 지혜",
    "dossierMd": "■ [B234] 누가복음 16장의 '불의한 청지기 비유' — 주인의 장부를 조작해 빚을 깎아준 사기꾼 청지기를 왜 주인이 '지혜롭다'고 칭찬했을까?\n• 눅 16:1~9\nP026(예수 그리스도) · E148 | 성도들이 읽을 때마다 가장 당황하는 비유입니다. 당시 1세기 유대 사회에서 부자 지주는 율법상 동족에게 고리대금(이자)을 받을 수 없었기 때문에, 청지기(관리인)가 소작인들에게 땅과 곡식을 빌려줄 때 원금에 자기 몫의 높은 수수료(또는 숨겨진 이자, 기름은 100말 중 50말, 밀은 100석 중 20석)를 얹어서 차용증을 쓰게 하는 것이 관행이었습니다. 해고 통보를 받은 청지기는 채무자들을 불러 자기가 챙기려 했던 수수료(또는 주인의 고리대금 이자분)를 과감히 삭감해 주어 채무자들에게는 큰 은혜를 베풀고 주인도 마을에서 '자비로운 지주'라는 칭송을 듣게 만들어 취소할 수 없게 만들었습니다! 예수님은 청지기의 불의함 자체를 칭찬하신 것이 아니라, 세상 사람들도 자신의 다가올 미래(해고 후의 삶)를 준비하기 위해 현재 가진 재물로 저토록 발 빠르게 결단하는데, 하물며 영원한 하늘 집을 바라보는 빛의 자녀들이 이 땅의 재물(불의의 재물 = 세상의 한시적 화폐)을 이웃 구제와 하나님 나라를 위해 지혜롭게 써야 하지 않겠느냐는 역설적 교훈을 주신 것입니다.",
