    "dossierMd": "■ [B243] 고린도전서 11장에서 여자들이 기도할 때 머리에 썼던 '권세 있는 표(수건/베일)'와 고린도전서 14장 '여자는 교회에서 잠잠하라'의 진짜 문화적 문맥\n• 고전 11:5~10, 14:34~35 (참조: 행 18:26, 롬 16:1)\nP030(바울), P161(브리스길라), P175(P119 뵈뵈) · E176 | 바울은 여성 사역 자체를 금한 적이 없습니다! 오히려 브리스길라를 아굴라보다 먼저 호명하며 동역자로 세웠고(롬 16:3), 겐그레아 교회의 여성 일꾼(집사) 뵈뵈에게 로마서 전달이라는 중책을 맡겼으며(롬 16:1), 고린도전서 11장 5절에서도 여성이 교회에서 공적으로 '기도하거나 예언(말씀 선포)하는 것' 자체를 당연한 전제로 인정하고 있습니다! 다만 당시 고린도 도시에서는 아프로디테 신전의 신전 창기들이 머리를 풀어 헤치거나 밀고 다녔기에 경건한 기독교 여성들은 정숙함의 표시로 머리에 스카프(베일)를 쓰라고 권면한 것이며, 14장 34절의 \"잠잠하라\" 역시 예배 중에 남녀가 분리되어 앉던 회당 구조에서 정규 교육을 받지 못했던 일부 기혼 여성들이 예배 도중 남편에게 큰 소리로 질문하며 예배 질서를 어지럽히자 \"질문할 것이 있거든 집에서 자기 남편에게 물으라\"(35절)고 질서를 잡아준 상황적 지침이었습니다.",
