    "visualGuide": "고린도전서 15장의 부활 교리 구조도(그리스도의 부활 첫 열매 → 성도의 영광스러운 몸의 부활 확증)",
    "dossierMd": "■ [B244] 고린도전서 15장 29절 '만일 죽은 자들이 도무지 다시 살아나지 못하면 죽은 자들을 위하여 세례를 받는 자들이 무엇을 하겠느냐?' — 바울은 대리 세례를 권장한 것일까?\n• 고전 15:29\nP030(바울) · E176 | 이 구절을 근거로 일부 이단(몰몬교 등)이 죽은 조상을 위한 대리 세례를 행하지만, 바울의 헬라어 인칭대명사 변화를 보면 정반대임이 드러납니다! 바울은 1~28절과 30절 이하에서는 계속 \"우리(1인칭)\"라고 말하다가, 오직 29절에서만 \"그들(3인칭 — '세례를 받는 그들이 무엇을 하겠느냐')\"이라고 자기 자신 및 사도들과 철저히 거리를 둡니다! 즉, 당시 고린도 지역 일부에서 세례받기 직전 급사한 교우를 대신해 세례받던 기이한 풍습을 거론하며, \"너희 중에는 부활이 없다고 주장하면서도 정작 죽은 자를 위해 세례받는 모순된 행동까지 하는 자들이 있지 않느냐?\"라고 부활 부정론자들의 자가당착을 논박한 논증일 뿐, 성경 어디에서도 대리 세례를 가르치거나 승인하지 않습니다.",
