    "visualGuide": "돈을 우상으로 섬기다 찔리는 탐심과 하나님이 주신 재물을 나누어 주어 영원한 터를 쌓는 선한 청지기의 대조",
    "dossierMd": "■ [B245] 디모데전서 6장 10절 — 성경은 '돈이 일만 악의 뿌리'라고 했을까, 아니면 '돈을 사랑함이 일만 악의 뿌리'라고 했을까?\n• 딤전 6:10, 6:17~19\nP030(바울), P158(디모데) · E278 | 세상에서 가장 흔히 오용되는 성경 구절입니다! 성경은 결코 '돈(재물) 자체가 악의 뿌리'라고 말하지 않습니다(아브라함, 욥, 요셉, 바나바, 루디아의 재물은 하나님의 나라를 세우는 귀한 도구였습니다). 디모데전서 6장 10절 원문은 정확히 \"돈을 사랑함이(필라르귀리아, φιλαργυρία — 은과 화폐를 우상처럼 탐하고 사랑하는 탐심) 일만 악의 뿌리가 되나니\"라고 기록하며, 17~19절에서는 부한 자들에게 재물에 소망을 두지 말고 선한 일을 많이 하며 나누어 주기를 좋아하라고 권면합니다.",
