    "hook": "손수건만 얹어도 남의 병을 고치던 대사도 바울이 왜 정작 자기 몸의 질병('육체의 가시')은 고침 받지 못했으며 그 거절이 어떻게 더 큰 응답이 되었을까?",
    "visualGuide": "침침한 눈으로 파피루스 끝에 큼직한 친필 글자를 적어 내려가며 '내가 약한 그때에 강함이라' 미소 짓는 사도 바울",
    "dossierMd": "■ [B246] 바울이 고린도후서 12장 7~9절에서 세 번이나 옮겨달라고 기도했으나 '내 은혜가 네게 족하도다' 응답받은 '육체의 가시(스콜롭스)'는 무엇이었을까?\n• 고후 12:7~9, 갈 4:13~15, 6:11\nP030(바울) · E177 | 헬라어 '스콜롭스(σκόλοψ)'는 장미 가시 같은 작은 가시가 아니라, 살을 꿰뚫는 '뾰족한 나무 말뚝 / 창끝'을 뜻합니다. 갈라디아서 4장 15절(\"너희가 할 수만 있었더라면 너희의 눈이라도 빼어 나에게 주었으리라\")과 6장 11절(\"내 손으로 너희에게 이렇게 큰 글자로 쓴 것을 보라\")의 단서를 종합할 때, 다메섹의 강렬한 빛과 밤빌리아 저지대의 말라리아 열병 후유증으로 인한 심각한 만성 안질(안과 질환과 극심한 편두통)이었을 가능성이 가장 높습니다. 수많은 병자를 손수건만 얹어도 고쳤던 사도 바울이 정작 자기 몸의 말뚝 같은 질병은 평생 안고 살아야 했던 역설은, 바울이 너무 받은 계시가 커서 자만하지 않게 하시려는 하나님의 안전장치이자 \"나의 약한 데서 하나님의 능력이 온전히 머물게 하시는\" 은혜의 통로였습니다.",
