    "hook": "바울이 '내가 모든 것을 할 수 있느니라'고 외친 장소는 화려한 승리 무대였을까 아니면 배고픔과 쇠사슬의 로마 감옥이었을까?",
    "visualGuide": "로마 감옥의 쇠사슬 속에서도 비천과 풍부 모든 환경에 자족하며 기쁨의 서신을 쓰는 바울의 참된 능력",
    "dossierMd": "■ [B247] 빌립보서 4장 13절 '내게 능력 주시는 자 안에서 내가 모든 것을 할 수 있느니라' — 내가 원하는 성공을 다 이룬다는 주문일까, 아니면 감옥 속 '자족(Autarkeia)'의 비결일까?\n• 빌 4:11~13\nP030(바울) · E274 | 스포츠 선수나 수험생들이 '만사형통 성공 구호'로 가장 많이 인용하는 구절이지만, 바로 앞 구절인 11~12절 문맥을 함께 읽어야 진짜 뜻이 빛납니다! \"내가 비천에 처할 줄도 알고 풍부에 처할 줄도 알아 모든 일 곧 배부름과 배고픔과 풍부와 궁핍에도 처할 줄 아는 일체의 비결을 배웠노라. 내게 능력 주시는 자 안에서 내가 (이 모든 환경 속에서 흔들리지 않고 자족하는) 모든 것을 할 수 있느니라!\" 바울이 이 글을 쓴 곳은 화려한 성공 무대가 아니라 로마의 감옥이었습니다! 즉, 이 구절은 \"내가 원하는 욕망을 다 성취한다\"는 뜻이 아니라, 가난해도 비굴해지지 않고 부요해도 교만해지지 않으며 감옥 속에서도 기뻐할 수 있는 전천후 영적 내공이 오직 그리스도께로부터 공급된다는 고백입니다.",
