    "dossierMd": "■ [B248] 베드로전서 3장 19절 '그가 또한 영으로 가서 옥에 있는 영들에게 선포하시니라' — 예수님이 십자가에서 죽으신 뒤 지옥에 가서 불신자들에게 패자부활전 전도를 하셨다는 뜻일까?\n• 벧전 3:18~20\nP029(베드로), P026(예수 그리스도), P003(노아) · E282 | 중세 신학이나 일부 오해처럼 \"죽은 뒤에 지옥에서 두 번째 구원 기회(전도)가 있다\"는 뜻이 절대 아닙니다(히 9:27 \"한번 죽는 것은 사람에게 정하신 것이요 그 후에는 심판이 있으리니\"). 여기서 '선포하시니라(에케륀센, ἐκήρυξεν)'는 복음을 전도하다(유앙겔리조)가 아니라, 승리한 왕이 적진에 가서 '최종 승리를 공식 포고하다(Herald victory)'라는 뜻입니다! 즉, 노아 시대에 불순종하던 악한 영들(또는 그리스도의 영이 노아를 통해 당대 불순종하던 자들에게 이미 선포하셨던 것)에 대하여, 예수님께서 십자가 죽음과 부활로 사망과 어둠의 권세를 완전히 깨뜨리시고 주권적 승리를 공식 선언하셨다(골 2:15)는 승전보입니다.",
