    "title": "요한복음 21장 18~19절 예수님의 예언('늙어서는 네 팔을 벌리리니')과 사도 베드로가 로마 네로 박해 때 '십자가에 거꾸로 매달려' 순교한 초기 교회사('유세비우스 교회사') 기록!",
