    "dossierMd": "■ [B249] 사도 베드로가 로마 네로 박해 때 십자가에 '거꾸로 매달려' 순교했다는 전승('쿼바디스 도미네')의 역사적 근거는?\n• 요 21:18~19\nP029(베드로), P026(예수 그리스도) · E157, E282 | 예수님이 디베랴 바닷가에서 베드로에게 \"네가 젊어서는 스스로 띠 띠고 원하는 곳으로 다녔거니와 늙어서는 네 팔을 벌리리니 남이 네게 띠 띠우고 원하지 아니하는 곳으로 데려가리라 (이 말씀을 하심은 베드로가 어떠한 죽음으로 하나님께 영광을 돌릴 것을 가리키심이러라)\"(요 21:18~19)고 예언하셨습니다('두 팔을 벌린다'는 것은 당시 초대교회에서 십자가 처형을 가리키는 관용어!). 그 예언대로 서기 64~67년경 로마 네로 황제의 박해 때 바티칸 언덕 경기장에서 체포된 베드로는, 초대 교부 오리게네스와 유세비우스(『교회사』 3.1)의 역사 기록에 따르면 \"나 같은 죄인이 어찌 감히 내 주 예수님과 똑같은 모습으로 십자가에 매달릴 수 있겠습니까? 나를 거꾸로 매달아 주십시오!\"라고 자원하여 십자가에 거꾸로 못 박혀 순교함으로 세 번 부인의 실패를 넘어 마지막까지 주님께 영광을 돌렸습니다.",
