    "title": "요한계시록 13장 18절 짐승의 수 '666' — 바코드·베리칩 음모론 바로잡기와 히브리 게마트리아('네론 카이사르 = 666') 및 하나님의 완전수 '7'에 못 미치는 인간 교만의 극치 '666'!",
    "origTitle": "The Number of the Beast 666: Hebrew Gematria (Nero Caesar) & the Triple Imperfection of Six Falling Short of Seven",
    "scriptures": "계 13:16~18",
    "hook": "왜 '666'은 물리적 바코드나 기계 칩이 아니라 하나님을 대적하는 세상 권력('네로 황제')과 불완전한 인간 교만의 삼중 극치를 뜻할까?, 히브리어 게마트리아 숫자 합산표(네론 카이사르 = 666)와 어린양의 인(이마에 기록된 아버지의 이름",
    "visualGuide": "계 14:1)의 영적 소속 대조도",
    "dossierMd": "■ [B250] 요한계시록 13장 18절의 짐승의 수 '666' — 바코드나 베리칩일까, 아니면 히브리어·헬라어 게마트리아(숫자 암호)와 '불완전수 6의 삼중 극치'일까?\n• 계 13:16~18\nP122(사도 요한) · E248 | 시대마다 바코드, 신용카드, 컴퓨터, 특정 정치가를 '666'이라 주장하는 시한부 종말론이 기승을 부렸으나 모두 비성경적 오해입니다! 계시록 13장 18절은 분명히 \"이것은 사람의 수니 그의 수는 육백육십육(666)이니라\"고 밝힙니다. 첫째, 고대 히브리어와 헬라어는 알파벳 글자마다 숫자 값을 매기는 '게마트리아(Gematria)'를 썼는데, 당시 그리스도인들을 가장 잔혹하게 박해하며 스스로 신이라 부르던 '네로 황제(네론 카이사르, נרון קסר)'를 히브리 자음 숫자로 합산하면 정확히 50(נ) + 200(ר) + 6(ו) + 50(נ) + 100(ק) + 60(ס) + 200(ר) = 666이 됩니다! 둘째, 성경의 상징수 체계에서 하나님의 완전수이자 안식수인 '7'에 하나가 모자란 '6'은 하나님을 대적하는 인간의 교만과 불완전함을 뜻합니다. 즉, 성부·성자·성령 삼위일체 하나님의 완전함(777)을 흉내 내려 하나 끝내 7에 이르지 못하는 사탄·적그리스도·거짓선지자 악의 삼위일체의 영원한 미완성과 파멸을 상징하는 영적 표식(경배의 대상과 가치관의 소속)입니다!",
