    "hook": "왜 하나님이 거하시는 성막의 맨 바깥 지붕을 황금이나 비단이 아니라 거칠고 볼품없는 검은 해달 가죽으로 덮으라고 하셨을까?",
    "visualGuide": "성막 지붕 4겹 단면도(맨 위 해달 가죽 → 붉은 물들인 숫양 가죽 → 염소털 → 맨 안쪽 그룹 수놓은 화려한 앙장)와 예수님의 인성·신성 비유",
    "dossierMd": "■ [B251] [성막 지붕 4중 덮개] 성소 안쪽 천장은 청색·자색·홍색 실과 그룹 수로 눈부신데, 왜 밖에서 보이는 맨 위 덮개는 볼품없는 '해달의 가죽(타하쉬)'이었을까?\n• 출 26:1~14\nP013, P230(브살렐) · E014 | 광야 성막 지붕은 총 4겹으로 덮였습니다. 맨 안쪽 ① 제1덮개(앙장)는 청색·자색·홍색 실과 가늘게 꼰 베실에 그룹을 수놓은 화려한 휘장이었고, ② 제2덮개는 염소털 천막, ③ 제3덮개는 붉은 물들인 숫양의 가죽, 그리고 맨 바깥 ④ 제4덮개는 홍해의 듀공(바다소)이나 사막 오소리/해달 가죽인 검고 거친 '타하쉬 가죽'이었습니다! 밖에서 구경꾼이 성막을 보면 시커먼 가죽 텐트(사 53:2 \"고운 모양도 없고 풍채도 없는\" 예수님의 인성!)로 보이지만, 회개하고 성소 문 안으로 들어간 예배자가 고개를 들면 머리 위로 찬란한 하늘 영광과 천사(그룹)들이 펼쳐지는 반전의 구조였습니다.",
