    "dossierMd": "■ [B252] [성막 물두멍] 왜 성막 기구 중 유일하게 '놋 물두멍(세수 대야)'만은 가로·세로·높이 치수(규빗) 제한이 없고 '여인들의 놋거울'로 만들었을까?\n• 출 30:18~21, 38:8\nP013, P014 · E014 | 언약궤·떡상·분향단·번제단은 모두 몇 규빗인지 정확한 치수가 정해져 있었으나, 제사장들이 수족을 씻는 '물두멍(키요르)'만은 성경에 치수 제한이 전혀 없습니다! 왜냐하면 우리의 더러움을 씻어주시는 말씀과 보혈의 씻음(엡 5:26 물로 씻어 말씀으로 깨끗하게 하사)의 은혜는 측량할 수 없이 무한하기 때문입니다! 더구나 이 물두멍의 재료는 회막 문에서 수종드는 여인들이 자기 얼굴을 꾸미며 치장하던 애장품인 '놋거울(청동 거울, 출 38:8)'을 자발적으로 바쳐 녹여 만든 것이었습니다. 내 외모를 비추던 교만의 거울이 깨어져 녹아질 때, 하나님의 말씀에 내 영혼을 비추어 씻는 거룩한 물두멍이 됩니다.",
