    "dossierMd": "■ [B253] [분향단의 거룩한 향] 성소 분향단에서 피운 향('소합향·나감향·풍자향·유향')을 왜 개인의 사치나 방향제로 만들면 백성 중에서 끊어지리라고 금하셨을까?\n• 출 30:34~38, 계 8:3~4\nP010(아론) · E014, E209 | 지성소 휘장 바로 앞 금향단에서 아침저녁으로 피워 올린 거룩한 향은 ① 소합향(스탁테) — 나무에서 저절로 흘러나오는 첫 수액(자원하는 기도), ② 나감향(오니카) — 홍해 조개껍데기를 불에 태우고 갈아서 내는 향(고난 속에서 드리는 기도), ③ 풍자향(갈바눔) — 진통·해독 작용을 하는 수지(치유와 회개의 기도), ④ 유향(레보나) — 하얀 나무 눈물 방울(순결한 찬양)을 같은 비율로 섞고 소금(변치 않는 언약)을 쳐서 만든 '성도의 기도'(계 8:3~4)였습니다. 기도는 오직 하나님 한 분께만 올려드려야 할 거룩한 향이기에, 기도를 사람에게 보이려는 자기 과시용 향수(외식하는 기도, 마 6:5)로 쓰지 말라는 엄중한 경고였습니다.",
