    "dossierMd": "■ [B255] [백향목과 우슬초] 솔로몬이 식물학 강의를 할 때 왜 '레바논의 백향목으로부터 담에 나는 우슬초까지'(왕상 4:33)라고 말했을까?\n• 왕상 4:33, 레 14:4, 시 51:7\nP022(솔로몬), P025 · E071 | 고대 근동에서 해발 2,000m 고산지대에서 높이 40m, 둘레 10m까지 치솟아 자라는 '레바논의 백향목(에레즈)'은 식물계의 가장 거대하고 영광스러운 최고봉(교만과 왕권의 상징)이었고, 반대로 돌담 틈새에서 한 뼘 크기로 자라는 '우슬초(에조브)'는 식물계의 가장 작고 보잘것없는 최소 단위의 풀이었습니다(즉, \"백향목부터 우슬초까지\" = \"식물계의 A부터 Z까지 전부\"라는 관용어!). 그런데 놀랍게도 나병 환자를 정결케 하는 예식(레 14:4)과 붉은 암송아지 잿물 예식(민 19:6)에서는 가장 높은 백향목 조각과 가장 낮은 우슬초를 홍색 실로 하나로 묶어 피와 물을 뿌리게 하셨습니다! 가장 높은 하늘 영광(백향목)에서 가장 낮은 구유와 십자가(우슬초)까지 내려오신 예수 그리스도의 겸손이 우리의 나병 같은 죄를 정결케 하십니다.",
