    "dossierMd": "■ [B256] [종려나무 — 타마르] 시편 92편 12절 '의인은 종려나무같이 번성하며' — 겉줄기가 아닌 속 중심('생장점')으로 자라며 사막 깊은 수맥을 찾는 대추야자나무!\n• 시 92:12~14, 요 12:13\nP025 · E221, E152 | 성경의 '종려나무(히브리어 타마르 תָּמָר, 헬라어 포이닉스)'는 오늘날 중동의 대추야자나무(Date Palm)입니다. 일반 활엽수는 껍질 바로 안쪽 형성층으로 수분을 끌어올려 겉껍질에 상처가 나거나 불에 그슬리면 죽지만, 단자엽 식물인 종려나무는 줄기 정중앙 가장 깊은 속 중심부(심장부 관다발)로 수분을 끌어올리기 때문에 겉줄기가 사막 모래폭풍에 깎이고 불에 그슬려도 죽지 않고 하늘을 향해 최대 30m까지 곧게 뻗어 올라갑니다! 또한 뿌리가 사막 지하 수십 미터 암반 아래의 생수 수맥까지 직접 내려가 연결되어 있어, 뜨거운 사막 한가운데서도 늙어도(수명 100~200년!) 여전히 진액이 풍족하고 빛이 청청하여 가장 달콤한 열매(꿀, 성경의 '젖과 꿀' 중 꿀의 상당수가 대추야자 시럽!)를 맺습니다.",
