    "dossierMd": "■ [B257] [감람나무 — 자이트] 노아의 홍수 끝부터 겟세마네와 로마서 11장 '돌감람나무 접붙임'까지 이어지는 천 년 수명의 올리브나무 생태학!\n• 롬 11:17~24, 시 128:3\nP030(바울), P025 · E175 | 지중해 연안의 감람나무(올리브나무, 자이트)는 수명이 천 년을 넘어가며, 고목이 되어 윗줄기를 베어내도 그루터기 뿌리 주변에서 어린 새순('네체르' — 이사야 11:1 \"이새의 뿌리에서 한 싹(네체르)이 나며\", 나사렛 지명의 어원!)들이 빙 둘러 돋아나 부모 나무를 감싸며 자랍니다(시 128:3 \"네 식탁에 둘러앉은 자식들은 어린 감람나무들 같으리로다\"). 또한 감람나무가 노화되어 열매가 줄어들면 야생 돌감람나무 가지를 참감람나무 원줄기에 접붙여 수세를 회복시키기도 했는데, 바울은 로마서 11장 17~24절에서 이 원예법을 역전시켜 \"원래 유실수도 못 되던 이방인 돌감람나무 가지인 우리가 오직 하나님의 은혜로 언약의 참감람나무 뿌리의 진액을 함께 받는 자가 되었다\"고 감격적으로 설파했습니다.",
