    "dossierMd": "■ [B259] [가라지 — 지자니아] 마태복음 13장 24~30절의 가라지 비유 — 왜 이삭이 패기 전에는 밀과 가라지를 뽑지 말고 추수 때까지 그냥 두라고 하셨을까?\n• 마 13:24~30\nP026(예수 그리스도) · E137 | 성경의 '가라지(헬라어 지자니아, ζιζάνια)'는 팔레스타인 밀밭에 자라는 독보리(다넬, Lolium temulentum — 유대인들은 이를 '가짜 밀 / 변절한 밀'이라 불렀음)입니다! 이 독보리는 자라나는 줄기와 잎사귀 모양이 진짜 밀과 99% 똑같아서, 농부조차 처음에는 도저히 구별할 수 없고 오직 땅속에서 밀의 뿌리와 독보리의 뿌리가 서로 그물처럼 엉켜 자랍니다(이때 억지로 뽑으려 하면 진짜 밀의 뿌리까지 다 뽑혀 죽음!). 그러다 추수 때가 되어 알곡이 여물면, 진짜 밀 이삭은 알곡의 무게 때문에 겸손하게 고개를 숙이는 반면, 속이 텅 비고 독성 곰팡이가 든 가라지는 빳빳하게 고개를 쳐들고 검은색으로 변해 단번에 구별됩니다! 로마법에도 남의 밭에 원한을 품고 이 독보리(지자니아) 씨를 뿌리는 테러 범죄를 처벌하는 조항이 실제로 존재했습니다.",
