    "dossierMd": "■ [B260] [쥐엄나무 열매 — 케라티온] 돌아온 탕자가 돼지 치며 배를 채우고자 했던 '쥐엄나무 열매'(눅 15:16)는 어떤 열매이며 유대 속담에서 무엇을 뜻했을까?\n• 눅 15:16\nP026(예수 그리스도) · E148 | 헬라어 '케라티온(κεράτιον — 작은 뿔 모양이라는 뜻)'은 지중해 연안에서 자라는 상록수인 캐롭나무(Carob tree, 쥐엄나무)의 길고 구부러진 검붉은 콩깍지 모양 열매입니다(씨앗 하나의 무게가 늘 일정하게 약 0.2g이어서 고대 보석상들이 금과 보석 무게를 재는 추로 썼고, 여기서 보석 단위 '캐럿 Carat'이 유래했습니다!). 가축 사료나 극빈자의 구황식품으로 쓰였으며, 유대 탈무드(와이이크라 랍바 35:6)에는 \"이스라엘 백성이 쥐엄나무 열매를 먹어야 할 지경에 이르면 비로소 회개하고 하나님께 돌아온다!\"라는 유명한 속담이 있었습니다! 예수님이 탕자가 \"돼지가 먹는 쥐엄나무 열매로 배를 채우고자 하되 주는 자가 없는지라 이에 스스로 돌이켜...\"라고 말씀하실 때, 유대 청중들은 그 속담을 떠올리며 탄식했을 것입니다.",
