    "dossierMd": "■ [B261] [유향과 몰약] 아기 예수님께 동방박사가 바친 '황금·유향·몰약' 중 유향(Frankincense)과 몰약(Myrrh)은 어떻게 채취하며 왜 각각 제사장과 고난의 상징일까?\n• 마 2:11, 요 19:39\nP026(예수 그리스도), P106 · E122, E155 | 두 향품 모두 아라비아 남부(시바)와 동아프리카 사막의 가시나무 줄기에 날카로운 칼로 깊은 상처(칼집)를 낼 때 나무가 스스로 상처를 치유하려고 흘려보내는 '나무의 눈물(수지, Resin)'이 굳어진 보물입니다! ① 유향(히브리어 레보나 — '하얗다'는 뜻)은 하얀 우유빛 눈물로 흘러나와 굳으며, 불에 태울 때 가장 향기로운 연기가 하늘로 치솟아 올라 성소 분향단과 제사장의 중보 사역(예수님의 신성과 대제사장직)에 쓰였고, ② 몰약(히브리어 모르 — '쓰다/고통'이라는 뜻, 마리아·마라와 같은 어원!)은 붉은 피 같은 눈물로 흘러나와 방부제·진통제 및 왕실 시신을 감싸는 장례 향품(예수님의 고난과 대속의 죽음)으로 쓰였습니다.",
