    "dossierMd": "■ [B262] [나드 향유 옥합] 마리아가 깨뜨린 '지극히 비싼 향유 곧 순전한 나드 한 근(삼백 데나리온)' — 히말라야 고산에서 온 향유와 왜 옥합 목을 깨뜨렸을까?\n• 막 14:3~9, 요 12:3~8\nP142(마리아), P026(예수 그리스도) · E151 | '순전한 나드(스파이크나드, Nardostachys jatamansi)'는 팔레스타인에서는 전혀 나지 않고, 수천 킬로미터 떨어진 인도 북부 히말라야 해발 3,000~5,000m 고산지대에서만 자라는 식물의 뿌리에서 극소량 추출하여 낙타 대상을 통해 수입한 최고급 왕실 향유였습니다! 이를 담은 '옥합(알라바스트론 — 이집트 나일강 유역 알라바스터 설화석고 병)'은 향기가 날아가지 않도록 입구를 밀랍으로 완전히 밀봉해 긴 목 형태로 만들었습니다. 마리아는 몇 방울만 아껴 쓰려고 마개를 연 것이 아니라, 옥합의 긴 목을 아예 단번에 깨뜨려(쉰트리프사사) 마지막 한 방울까지 예수님의 머리와 발에 다 쏟아부어 주님의 장례를 준비했습니다(300데나리온 = 1년 연봉이자 당시 유대 처녀의 평생 결혼 지참금!).",
