    "dossierMd": "■ [B263] [소금 언약] 레위기 2장 13절 '네 모든 소제물에 소금을 치라 네 하나님의 언약의 소금을 빼지 말지니' — 왜 불변하는 약속을 '소금 언약'이라 불렀을까?\n• 레 2:13, 민 18:19, 막 9:50\nP013, P014 · E208 | 고대 근동에서는 쉽게 상하고 부패하는 고기나 음식과 달리, 천 년이 지나도 절대 썩지 않고 주변의 부패까지 막아주는 '소금(멜라흐)'을 영원불변함의 상징으로 여겼습니다. 그래서 왕과 신하, 혹은 친구 사이에 영원히 변치 않을 조약을 맺을 때 함께 소금을 찍어 먹으며 '소금 언약(베리트 멜라흐 — 절대 파기되거나 변질될 수 없는 영원한 언약)'(민 18:19; 대하 13:5)이라 불렀습니다. 하나님이 모든 제물에 꿀이나 누룩(쉽게 발효·변질됨)은 넣지 말고 오직 소금을 치라고 하신 것은, 우리를 향한 하나님의 구원 언약과 성도의 헌신이 영원히 변질되지 않아야 함을 뜻합니다.",
