    "visualGuide": "반짝이는 직선형 은나팔 두 개(하초츠라)와 모리아산 숫양의 구부러진 뿔로 만든 양각나팔(쇼파르)의 실물 비교 및 희년 선포",
    "dossierMd": "■ [B265] [나팔(쇼파르) vs 은나팔(하초츠라)] 성경의 두 가지 나팔 — 왜 모리아산 숫양의 뿔로 만든 '쇼파르' 소리가 울릴 때 여리고 성이 무너지고 희년이 선포되었을까?\n• 레 25:9~10, 민 10:1~10, 수 6:4\nP013, P015 · E015, E211 | 구약성경에는 두 종류의 나팔이 구분되어 나옵니다. ① 제사장들이 은을 두드려 곧게 만든 '은나팔 두 개(하초츠라, 민 10:2)'는 회중 소집과 진영 출발 신호용이었고, ② 구부러진 숫양의 뿔로 만든 '양각나팔(쇼파르, שׁוֹפָר)'은 시내산 강림(출 19:19), 여리고 성 함락(수 6:4), 나팔절(레 23:24), 그리고 50년마다 모든 빚이 탕감되고 노예가 해방되는 대속죄일 희년 선포(레 25:9)에 불었습니다! 유대 전승에 따르면 왜 하필 '숫양의 뿔(쇼파르)'을 불어야 했을까요? 아브라함이 모리아산에서 이삭 대신 수풀에 뿔이 걸린 숫양을 번제로 드렸던(창 22:13) 그 대속의 은혜를 하나님 앞에 기억나게 하는 '구속과 해방과 재림(살전 4:16 하나님의 나팔 소리)의 소리'였기 때문입니다!",
