    "dossierMd": "■ [B266] [유대인의 경문(테필린)과 메주자] 왜 바리새인들은 이마와 왼팔에 차는 작은 가죽 상자('경문 갑, 필락테리온')를 남들보다 넓게 만들어 과시했을까?\n• 신 6:4~9, 마 23:5\nP013, P026(예수 그리스도) · E050, E153 | 신명기 6장 8~9절(\"너는 또 그것을 네 손목에 매어 기호를 삼으며 네 미간에 붙여 표로 삼고 또 네 집 문설주와 바깥문에 기록할지니라\") 말씀을 문자 그대로 지키기 위해 유대인들은 양피지에 쉐마 본문 등 네 구절을 적어 넣은 작은 검은 가죽 상자(테필린 / 헬라어 필락테리온 '경문')를 아침 기도 때마다 심장과 가까운 왼팔 팔뚝과 생각의 중심인 이마(미간)에 감았고, 집 문설주에는 작은 통(메주자)을 달았습니다. 원래는 내 마음(심장)과 생각(미간)과 가정을 말씀으로 다스리라는 뜻이었으나, 바리새인들은 남들에게 경건해 보이려고 그 가죽 상자 크기를 일부러 큼직하게 만들고(그 경문 띠를 넓게 하며, 마 23:5) 부적처럼 자랑하다 예수님께 외식이라 책망받았습니다.",
