    "visualGuide": "갈릴리 고라신 회당에서 발굴된 아람어 명문 현무암 '모세의 자리(이스라엘 박물관 소장)' 실물과 말씀의 행함을 강조하시는 예수님",
    "dossierMd": "■ [B267] [회당의 '모세의 자리(카테드라 모세오스)'] 마태복음 23장 2절에서 예수님이 말씀하신 '서기관들과 바리새인들이 모세의 자리에 앉았으니'는 비유였을까, 실제 돌 의자였을까?\n• 마 23:2\nP026(예수 그리스도) · E153 | 단순한 비유가 아니라 1세기 유대 회당 안에 실제로 놓여 있던 최고 권위의 석조 의자(돌 보좌)였습니다! 갈릴리 고라신(Chorazin) 회당 유적지와 디로스 회당 등에서 현무암 통돌을 정교하게 깎아 만들고 아람어 비문을 새긴 실제 1세기 양식의 '모세의 자리(Seat of Moses, 현재 이스라엘 박물관 소장!)'가 발굴되었습니다! 회당 예배 때 율법 학자와 최고 권위자가 이 돌 의자에 앉아 토라를 해석하며 백성을 가르쳤기에(오늘날 주교좌성당을 뜻하는 Cathedral과 대학 석좌교수 Chair의 어원이 바로 이 헬라어 카테드라!), 예수님은 그 권위의 의자에 앉아 말만 번지르르하게 하고 행하지 않는 지도자들을 향해 \"그들이 말하는 바(모세 율법 본문)는 행하고 지키되 그들이 하는 행위는 본받지 말라!\"(마 23:3)고 명하신 것입니다.",
