    "visualGuide": "선미 고물 갑판 구조)와 풍랑을 꾸짖으시는 예수님",
    "dossierMd": "■ [B268] [갈릴리 배('예수님의 배')] 1986년 갈릴리 호수 극심한 가뭄 때 진흙 속에서 기적적으로 발굴된 '1세기 예수님 시대의 실제 갈릴리 목선(The Jesus Boat)'!\n• 막 4:37~38, 눅 5:3\nP026(예수 그리스도), P029(베드로) · E129, E138 | 1986년 갈릴리 호수 수위가 역사상 최저로 낮아졌을 때, 막달라 북쪽 기노살 해변 진흙 속에서 탄소연대측정 결과 정확히 서기 1세기(BC 40~AD 50년경, 예수님과 베드로가 타셨던 바로 그 시대!)의 실제 갈릴리 고기잡이 배가 발굴되었습니다! 길이 8.27m, 폭 2.3m, 깊이 1.25m로 성인 남성 13~15명(예수님과 열두 제자!)이 타기에 딱 맞는 크기였으며, 백향목과 참나무 등 무려 12종류의 서로 다른 나무 조각을 짜 맞추어 만든 서민 어부의 배였습니다! 특히 배 뒷부분(고물, 선미)에는 그물을 치거나 쉴 수 있는 작은 갑판 공간이 있어, 풍랑 속에서 예수님이 \"고물에서 베개를 베고 주무시더니\"(막 4:38)라는 마가복음의 기록이 얼마나 정확한 현장 묘사였는지를 실물로 입증했습니다.",
