    "dossierMd": "■ [B276] [독수리 — 네쉐르] 신명기 32장 11절과 출애굽기 19장 4절 — 독수리는 정말 새끼를 절벽에서 떨어뜨린 뒤 '자기 날개 위'로 받아 올릴까? (어미 새는 화살을 대신 맞는다!)\n• 출 19:4, 신 32:11, 사 40:31\nP013, P041 · E013, E084 | 일반 맹금류는 날카로운 '발톱'으로 먹이나 물건을 낚아채지만, 만약 어미 독수리가 떨어지는 새끼를 발톱으로 잡으면 새끼가 발톱에 찔려 죽습니다. 그래서 어미 독수리는 높은 바위 절벽 보금자리를 어지럽혀 새끼를 허공으로 밀어낸 뒤, 새끼가 힘을 다해 날갯짓하다 지쳐 추락할 때 새끼 밑으로 총알같이 급강하하여 자신의 넓고 튼튼한 '날개 등 위'로 새끼를 사뿐히 받아 올립니다! 왜 발로 잡지 않고 날개 위에 태울까요? 땅에서 사냥꾼이 활을 쏘면 밑에 있는 어미 독수리가 자기 몸으로 먼저 화살을 맞아야만 날개 위의 새끼가 안전하기 때문입니다! 하나님이 \"내가 독수리 날개로 너희를 업어 내게로 인도하였음을 너희가 보았느니라\"(출 19:4)고 하신 것은, 십자가에서 사탄의 불화살을 몸으로 다 맞으시고 우리를 날개 위에 업어 구원하신 주님의 사랑을 그린 것입니다.",
