    "title": "시편 22편 6절 '나는 벌레(히브리어 톨라아트 — 성막 홍색 실 염료를 내는 케르메스 진홍빛 벌레!)요 사람이 아니라' — 나무에 자기 몸을 못 박듯 붙어 죽으며 붉은 피를 쏟아 새끼들을 살리고 사흘 만에 하얗게 변하는 케르메스 벌레의 신비!",
    "origTitle": "The Crimson Worm (Tola'at Shani) in Psalm 22:6 Fixing Itself to a Tree to Die Bleeding Red for Its Young and Turning White",
    "scriptures": "시 22:6; 사 1:18; 출 26:1",
    "hook": "왜 십자가에 달리신 메시아는 시편 22편 6절에서 일반 지렁이('림마')가 아니라 성막의 홍색 염료를 만드는 '톨라아트(진홍빛 케르메스 벌레)'로 자신을 부르셨을까?",
    "visualGuide": "상수리나무 줄기에 몸을 고정하고 죽으며 진홍빛 염료로 새끼들을 덮어 살리고 사흘 뒤 눈처럼 하얀 밀랍으로 변하는 '톨라아트' 벌레와 십자가 보혈",
    "dossierMd": "■ [B279] [진홍빛 벌레 — 톨라아트 샤니] 시편 22편 6절에서 십자가의 메시아가 왜 자신을 '나는 벌레(톨라)요 사람이 아니라'라고 부르셨을까? — 성막 홍색 실 염료를 내는 '케르메스 암컷 벌레'의 생태학!\n• 시 22:6, 사 1:18, 출 26:1\nP025, P026(예수 그리스도) · E027 | 다윗이 십자가 고난을 예언한 시편 22편 6절에서 메시아는 자신을 \"나는 벌레요(웨아노키 톨라아트, וְאָנֹכִי תוֹלַעַת) 사람이 아니라\"고 고백합니다. 여기서 쓰인 히브리어 '톨라 / 톨라아트(תּוֹלַעַת)'는 땅속 지렁이가 아니라, 성막의 '홍색 실(톨라아트 샤니)'과 대제사장 에봇의 진홍빛 염료를 채취하던 팔레스타인 상수리나무 서식 곤충 '케르메스 홍색 벌레(Kermes ilicis / Crimson Worm)'를 가리키는 고유 단어입니다! 이 케르메스 암컷 벌레는 알을 낳을 때가 되면 일생에 단 한 번 나무 줄기(십자가 나무!)에 자기 몸을 단단히 고정해 달라붙은 뒤, 자기 몸을 보호막 삼아 알을 낳고 그 자리에서 죽으면서 온몸에서 붉은 진홍빛 액체(피 같은 염료)를 쏟아내어 나무 줄기와 갓 부화한 새끼들을 붉게 물들이고 자기 죽은 몸을 새끼들의 첫 양식으로 내어줍니다! 그리고 암컷 벌레가 죽은 지 사흘째가 되면 붉었던 껍질이 눈처럼 하얀 밀랍 가루로 변해 땅에 떨어집니다(사 1:18 \"너희의 죄가 주홍 같을지라도 눈과 같이 희어질 것이요 진홍 같이 붉을지라도(카톨라!) 양털 같이 희게 되리라\"). 창조주께서 작은 벌레 하나의 생태 속에까지 십자가 대속의 복음을 새겨 두신 것입니다!",
