    "dossierMd": "■ [B280] [성전 세겔 — 두로(티레)의 은화] 왜 유대인들은 하나님의 성전에 바치는 반 세겔 성전세를 로마 동전으로는 못 내고 하필 이방 우상 '멜카르트 신'이 새겨진 '두로 세겔'로만 내야 했을까? — 환전상들의 폭리 비하인드!\n• 마 17:24~27, 21:12\nP026(예수 그리스도), P029(베드로) · E144, E152 | 출애굽기 30장 13절에 따라 20세 이상 유대 남성은 매년 '성소의 세겔로 반 세겔'을 성전세로 바쳐야 했습니다. 당시 성전 당국(대제사장 안나스·가야바 가문)은 오직 순도 94~97% 이상의 최고 순은으로 주조된 페니키아 항구 도시 '두로(Tyre)의 은화(두로 세겔 / 반 세겔)'로만 성전세를 납부하도록 강제했습니다! 아이러니하게도 그 두로 은화 앞면에는 페니키아의 바알 우상인 '멜카르트(헤라클레스) 신의 얼굴'과 독수리가 버젓이 새겨져 있었는데도, 대제사장들은 은의 순도가 높다는 핑계로 우상 동전만 고집하며 성전 뜰에 환전상을 차려놓고 순례객들이 가져온 일반 동전을 두로 세겔로 바꿀 때마다 4~8%의 막대한 환전 수수료(콜뤼보스)를 챙겼습니다! 예수님이 베드로에게 갈릴리 바다에서 낚은 물고기 입속에서 찾아 내게 하신 '한 세겔(스타테르 — 정확히 예수님과 베드로 두 사람 몫의 반 세겔 × 2!)'(마 17:27)이 바로 이 두로 세겔 은화였으며, 수난주간에는 이 탐욕스러운 환전상들의 상을 뒤엎으셨습니다.",
