    "dossierMd": "■ [B281] [제사장 아론의 축도 — 민수기 6장 24~26절] 기원전 600년 예루살렘 힌놈 골짜기 무덤에서 발굴된 성경 최고(最古) 본문 유물 '케테프 힌놈 은판 두루마리'와 3행(15단어) 피라미드 구조!\n• 민 6:22~27\nP013, P010(아론) · E047 | 1979년 예루살렘 남서쪽 힌놈 골짜기(Ketef Hinnom) 동굴 무덤에서 사해 사본보다 무려 400년 이상 앞선 기원전 7세기 말(예레미야·요시야 왕 시대!)의 초소형 순은 두루마리 2점이 발굴되었습니다. 이를 정밀하게 펼쳤더니 고대 히브리 문자로 민수기 6장 24~26절(아론의 축도: \"여호와는 네게 복을 주시고 너를 지키시기를 원하며...\")이 세부 표현까지 다르지 않게 새겨져 있어 전 세계 성서고고학계를 뒤흔들었습니다(현존하는 가장 오래된 성경 본문 유물)! 더구나 이 축도는 히브리어 원문 구조상 1행: 3단어(15글자) → 2행: 5단어(20글자) → 3행: 7단어(25글자)로 점점 넓어지는 완벽한 폭포수 피라미드 운율을 이루며, 세 문장 모두 주어가 '여호와(YHWH — 성부·성자·성령 삼위 하나님의 은혜·사랑·평강)'로 시작합니다!",
