    "dossierMd": "■ [B282] [대제사장 판결 흉패의 12보석] 왜 대제사장은 어깨의 두 호마노에 12지파 이름을 새기고, 또 심장 위 가슴 흉패의 12보석에 각 지파 이름을 새겨 달았을까?\n• 출 28:9~29\nP010(아론), P026(예수 그리스도) · E014 | 대제사장이 성소에 들어갈 때 이스라엘 12지파의 이름은 두 곳에 새겨져 있었습니다. ① 먼저 가장 무거운 짐을 짊어지는 양쪽 어깨 견대 위의 두 호마노 보석(출 28:12)에 6지파씩 이름을 새겨 \"대제사장의 능력의 어깨 위에 자기 백성을 짊어진다\"(눅 15:5 잃은 양을 찾아 어깨에 메고 오는 목자!)는 것을 보여주었고, ② 둘째로 심장(가슴) 바로 위 판결 흉패에 서로 색깔과 빛깔이 다 다른 12개의 보석(홍보석·황옥·녹주옥 등, 출 28:17~21)에 한 지파씩 이름을 새겨 \"대제사장의 뜨거운 사랑의 심장 위에 각 성도의 고유한 이름과 개성을 보석처럼 품고 하나님 앞에 선다\"는 것을 보여주었습니다!",
