    "dossierMd": "■ [B283] [요한계시록 1장 12~16절 — 일곱 금 촛대 사이를 거니시는 인자] 왜 예수님의 음성은 '많은 물소리' 같고 입에서는 '좌우에 날 선 검'이 나올까?\n• 계 1:12~16, 히 4:12\nP026(예수 그리스도), P122(사도 요한) · E200 | 로마 제국의 박해 아래 두려워 떨던 소아시아 교회들에게 부활·승천하신 예수님은 연약한 목수의 모습이 아니라 왕 중의 왕이자 대제사장의 영광스러운 예복(발에 끌리는 옷과 가슴의 금띠)을 입으시고 일곱 금 촛대(지상 교회들) 한가운데를 친히 거닐며 돌보시는 분으로 나타나셨습니다. 로마 황제가 군대의 칼로 위협할 때, 진짜 최종 심판권과 생사여탈권을 가지신 예수님의 입에서 나오는 '좌우에 날 선 예리한 검(롬파이아 디스토모스 — 살아있는 하나님의 말씀, 히 4:12)'만이 모든 어둠의 세력을 단번에 굴복시킵니다.",
