    "dossierMd": "■ [B284] [요한계시록 4장 — 보좌 주위의 스물네 장로와 네 생물] 왜 네 생물은 '사자 · 송아지 · 사람 · 독수리'의 얼굴을 가졌으며 이것이 4복음서와 이스라엘 광야 4대 진영 깃발과 어떻게 일치할까?\n• 계 4:4~8 (참조: 민 2장, 겔 1:10)\nP122(사도 요한), P026(예수 그리스도) · E240 | 하늘 보좌(신구약 전체 하나님 백성을 대표하는 12지파 + 12사도 = 24장로)를 호위하는 네 생물의 모습은 구약 민수기 2장의 이스라엘 광야 4대 진영 깃발 전승 및 신약 4복음서가 증언하는 예수 그리스도의 4중 사역과 완벽히 일치합니다! ① 사자(유다 진영 / 마태복음): 다윗의 뿌리요 유다 지파의 사자이신 '만왕의 왕' 예수님, ② 송아지(에브라임 진영 / 마가복음): 묵묵히 멍에를 메고 대속 제물로 피 흘려 섬기신 '고난받는 종' 예수님, ③ 사람의 얼굴(르우벤 진영 / 누가복음): 죄인과 약자의 친구로 오신 완전한 '참 사람(인자)' 예수님, ④ 날아가는 독수리(단 진영 / 요한복음): 태초부터 계신 말씀이자 하늘 보좌로 비상하시는 '하나님의 아들(신성)' 예수님!",
