    "visualGuide": "포효하는 유다 지파의 사자의 그림자가 십자가 대속의 상처를 지닌 채 보좌 중앙에 서 계신 어린양의 모습으로 포개지는 구속사 반전 일러스트",
    "dossierMd": "■ [B285] [요한계시록 5장 — 일곱 인으로 봉한 두루마리와 '일찍이 죽임을 당한 것 같은 어린양'] 왜 사도 요한은 '유다 지파의 사자(Lion)'가 이겼다는 말을 듣고 돌아보았는데 정작 보좌 중앙에는 '피 흘린 어린양(Lamb)'이 서 계셨을까?\n• 계 5:1~12\nP026(예수 그리스도), P122(사도 요한) · E241 | 성경 전체에서 가장 위대한 반전의 장면입니다! 아무도 역사의 구원 두루마리를 펴지 못해 요한이 크게 울 때, 장로가 말합니다: \"울지 말라 유대 지파의 사자(레온, Lion) 다윗의 뿌리가 이기었으니!\"(계 5:5). 요한이 포효하는 사자를 보려고 고개를 돌렸는데, 정작 보좌 한가운데 서 계신 분은 맹수 사자가 아니라 '일찍이 죽임을 당한 것 같은(도살당한 상처가 그대로 남아 있는) 작은 어린양(아르니온, Ἀρνίον — 새끼 양!)'(계 5:6)이셨습니다! 하나님 나라의 승리는 상대를 물어뜯는 사자의 무력으로 이긴 것이 아니라, 십자가에서 스스로 죽임을 당하신 어린양의 희생과 사랑으로 이긴 승리이기 때문입니다!",
