    "visualGuide": "네 말의 질주 너머로 제단 아래 순교자들에게 흰 두루마리를 입히시며 눈물을 닦아주시는 하나님의 주권적 통제",
    "dossierMd": "■ [B286] [요한계시록 6장의 네 말(백마·붉은 말·검은 말·청황색 말)과 제단 아래 순교자들의 탄원] 왜 세 번째 검은 말 탄 자는 저울을 들고 '밀 한 되에 한 데나리온이요 감람유와 포도주는 해치지 말라'(계 6:6)고 외쳤을까?\n• 계 6:1~11\nP122(사도 요한) · E242 | 묵시록의 4기사 중 기근과 경제 파탄을 상징하는 세 번째 검은 말 탄 자가 손에 저울을 들고 외친 \"밀 한 되(코이닉스 — 성인 남성 하루 최소 생존 식량 약 1리터)에 한 데나리온(하루 일당 전부!)이요 보리 석 되에 한 데나리온\"은 평시 물가의 약 8~12배가 폭등한 극심한 인플레이션과 기근을 뜻합니다! 그런데 놀랍게도 기근 중에도 부자들의 기호품인 '감람유와 포도주는 해치지 말라'는 음성(일부 해석은 도미티아누스 황제가 서기 92년 소아시아의 포도원을 갈아엎으려다 철회한 실제 역사적 사건 반영, 동시에 심판이 아직 100% 전면 멸망이 아닌 제한적 재앙임을 보여줌)이 들려오며, 제단 아래 순교자들에게는 흰 두루마리와 안식이 주어집니다.",
