    "title": "이단들이 가장 악용하는 요한계시록 7장의 '십사만 사천(144, 000 = 12×12×1000)' 완벽 반박 — 4절에서 '귀로 들은 상징수 144, 000'이 9절에서 '눈으로 본 각 나라와 방언의 능히 셀 수 없는 큰 무리'인 성경적 증거!",
    "origTitle": "Refuting Cult Distortions of the 144000: Hearing the Symbolic Census (12x12x1000) and Seeing the Countless Multitude from Every Nation (Rev 7:4 & 9)",
    "scriptures": "계 7:1~17; 14:1~5",
    "hook": "왜 요한계시록 7장에서는 먼저 4절에서 '인 맞은 자의 수를 들으니 144, 000'이라 한 직후 9절에서 '내가 보니 아무도 능히 셀 수 없는 큰 무리'라고 밝혔으며 왜 12지파 명단에서 우상 숭배 지파인 단(Dan) 지파가 빠졌을까?, [귀로 들음: 12(구약)×12(신약)×1000(완전수) = 144",
    "visualGuide": "000 영적 군대 점호] = [눈으로 봄: 온 열방의 셀 수 없는 흰 옷 입은 큰 무리] 정통 성경 해석 도표",
    "dossierMd": "■ [B287] [요한계시록 7장의 '십사만 사천(144,000)'과 '능히 셀 수 없는 큰 무리'] 이단(신천지·여호와의 증인)이 가장 왜곡하는 '144,000'의 진짜 성경적 의미와 지파 명단의 비밀!\n• 계 7:1~17, 14:1~5\nP122(사도 요한), P026(예수 그리스도) · E250 | 이단들이 \"우리 단체에 들어와 144,000명 정원 안에 들어야 구원받는다\"고 속이는 대표적 구절입니다! 그러나 본문을 바로 읽으면 단번에 파쇄됩니다. 첫째, 144,000 = 12(구약 12지파) × 12(신약 12사도) × 1,000(완전 충만수)로서 물리적 제한 인원이 아니라, 환난 속에서도 하나님이 단 한 명도 잃어버리지 않고 완벽히 인(도장) 쳐서 보호하시는 '구원받은 하나님의 전(全) 교회 공동체의 영적 완전수'입니다! 둘째, 요한이 먼저 4절에서 \"인 침을 받은 자의 수를 들으니 십사만 사천\"이라고 귀로 들은 뒤(Heard), 9절에서 눈을 들어 실제로 보았을 때(Saw) 그들이 누구였습니까? \"각 나라와 족속과 백성과 방언에서 아무도 능히 셀 수 없는 큰 무리가 흰 옷을 입고 손에 종려 가지를 들고 서 있더라!\"(계 7:9) — 계시록 5장에서 '사자라고 듣고 어린양을 본 것'과 똑같은 요한 특유의 [듣기(상징적 군대 점호 144,000) → 보기(실제 열방의 셀 수 없는 구원 무리)] 문학 구조입니다! 셋째, 7장 5~8절의 12지파 명단에는 유다 지파가 맨 앞에 오고 우상 숭배의 원흉이었던 '단(Dan) 지파'와 '에브라임 지파'가 빠져 있으며 대신 요셉과 레위가 들어가 있어, 혈통적 이스라엘이 아닌 우상과 타협하지 않는 영적 하나님의 백성을 뜻함을 명확히 보여줍니다.",
