    "dossierMd": "■ [B290] [요한계시록 11장의 '두 증인'] 굵은 베옷을 입고 1,260일 동안 예언하는 '두 감람나무와 두 촛대'는 왜 모세와 엘리야의 권능을 함께 나타낼까?\n• 계 11:3~12 (참조: 슥 4:11~14, 신 19:15)\nP122(사도 요한), P013, P031 · E255 | 율법에서 증언이 법적 효력을 가지려면 최소 '두 증인'(신 19:15)이 필요하듯, 계시록 11장의 '두 증인'은 마지막 때까지 세상에 복음을 증언하는 선교적 교회 공동체를 상징합니다. 이들이 하늘을 닫아 비 오지 못하게 하는 권능(선지자 엘리야)과 물을 피로 변하게 하는 권능(율법 수여자 모세 — 변화산에서 예수님과 함께 나타났던 구약의 두 대표자!)을 행하는 것은, 교회가 구약의 모든 율법과 선지자의 성취이신 예수 그리스도의 권세를 위임받아 사역이 끝나는 날까지 결코 죽지 않는 불사(不死)의 사명자임을 보여줍니다.",
