    "dossierMd": "■ [B291] [요한계시록 12장의 '해를 옷 입은 여인과 붉은 용'] 여인이 광야로 도망하여 양육받는 '일천이백육십 일(1,260일 = 42달 = 한 때와 두 때와 반 때, 3년 반)'의 구속사적 의미!\n• 계 12:1~6, 12:14 (참조: 단 7:25, 왕상 17:1)\nP122(사도 요한) · E257 | 해와 달과 열두 별의 관을 쓴 여인(메시아를 낳은 구약 언약 공동체에서 신약 교회로 이어지는 하나님의 백성)이 붉은 용(사탄)의 박해를 피해 광야에서 보호받는 기간인 '1,260일 / 마흔두 달 / 한 때와 두 때와 반 때(3년 반)'는 완전수 '7년'의 정확히 절반(3.5년)입니다! 구약에서 엘리야 시대에 아합·이세벨 치하의 가뭄이 3년 6개월(약 5:17)이었고 안티오쿠스 에피파네스의 성전 모독 박해가 3년 반이었듯, 이 숫자는 \"교회가 이 땅 광야에서 겪는 환난의 시간은 결코 영원(7)하지 않으며, 하나님께서 반으로 뚝 잘라 제한해 놓으신 한시적 기간(3.5)뿐이고 그 기간 내내 독수리의 두 날개로 먹이시고 보호하신다!\"는 절대 안전의 보증입니다.",
