    "dossierMd": "■ [B292] [요한계시록 14장의 '어린양의 노래와 모세의 노래'] 왜 유리바다 가에 선 승리자들은 구약 출애굽의 '모세의 노래'와 신약의 '어린양의 노래'를 한 곡으로 합창할까?\n• 계 15:2~4 (참조: 출 15:1~18)\nP013, P026(예수 그리스도), P122(사도 요한) · E012, E261 | 출애굽기 15장에서 홍해 바다가 갈라지고 애굽 군대가 수장된 뒤 모세와 이스라엘 백성들이 홍해 해변에 서서 불렀던 구약 첫 구원의 찬송이 '모세의 노래'였습니다. 그리고 인류 역사의 마지막 날, 불이 섞인 유리바다 가에 선 모든 구원받은 성도들은 구약의 모세의 노래와 신약 십자가 구원의 '어린양의 노래'를 하나로 합쳐 부릅니다! 구약의 출애굽 구원과 신약의 십자가 구원이 처음부터 끝까지 단 하나의 구속 드라마였음을 보여주는 천상의 대합창입니다.",
