    "dossierMd": "■ [B293] [요한계시록 16장 16절 — '아마겟돈(Harmagedon)'] 최후의 전쟁터 '아마겟돈'은 실제 지명일까, 아니면 '므깃도 산(하르 므깃도)'이 품은 구약 역사의 상징일까?\n• 계 16:16 (참조: 삿 5:19, 왕하 23:29)\nP122(사도 요한) · E264 | 헬라어 '아마겟돈(Ἁρμαγεδών)'은 히브리어 '하르 므깃도(הַר מְגִדּוֹ — 므깃도의 산)'의 음역입니다! 그런데 실제로 갈릴리 남쪽 이스르엘 평야에 가보면 '므깃도'는 산이 아니라 평야의 요충지 언덕(텔 므깃도)이며 그 바로 옆에 갈멜산 능선이 이어져 있습니다. 왜 요한은 므깃도를 '산(하르)'이라 불렀을까요? 므깃도와 기손강 평야는 사사 드보라와 바락이 폭우로 가나안 철 병거 900대를 수장시킨 곳(삿 5:19)이자, 기드온이 미디안을 격파한 곳이며, 바로 위 갈멜산(므깃도의 산!)은 엘리야가 바알과 아세라 거짓 선지자 850명을 단번에 심판한 영적 대결전이 펼쳐진 장소였기 때문입니다! 즉, 아마겟돈은 중동의 특정 부동산 좌표가 아니라, 하나님을 대적하는 세상 모든 악의 세력이 갈멜산과 므깃도에서처럼 하나님의 말씀 앞에 일거에 심판받는 최후의 영적 결전을 뜻합니다.",
