    "dossierMd": "■ [B295] [요한계시록 19장 11~16절 — 백마 탄 왕의 피 뿌린 옷] 왜 백마를 타고 오시는 예수님의 옷은 적군의 피가 아니라 전쟁이 시작되기도 전에 이미 '피 뿌린 옷'(계 19:13)을 입고 계실까?\n• 계 19:11~16 (참조: 사 63:1~3)\nP026(예수 그리스도), P122(사도 요한) · E297 | 계시록 19장 13절에서 하늘이 열리고 백마를 타고 내려오시는 예수님('하나님의 말씀')은 아직 지상의 짐승 군대와 전투를 시작하기도 전인데 이미 '피 뿌린 옷(히마티온 베밤메논 하이마티)'을 입고 계십니다! 이 피는 누구의 피일까요? 적군의 피가 아니라, 2천 년 전 골고다 십자가에서 우리를 구원하시려고 주님 자신이 친히 흘리신 대속의 보혈입니다! 주님은 재림의 날에도 골고다 십자가에서 흘리신 그 승리의 보혈로 물든 예복을 입으시고, 다리에 '만왕의 왕이요 만주의 주라'는 이름을 쓰시고 마침내 심판과 구원을 완성하러 오십니다.",
