    "dossierMd": "■ [B299] [요한계시록 21장 19~20절 — 새 예루살렘 성벽의 열두 기초석 보석] 땅속 어두운 지하에 묻히는 '기초석'을 왜 시멘트나 화강암이 아니라 벽옥·남보석·녹보석 등 최고급 12보석으로 쌓았을까?\n• 계 21:19~20\nP122(사도 요한) · E030, E300 | 세상 건축에서는 보이지 않는 땅속 기초석에는 가장 투박하고 값싼 돌을 쓰고, 눈에 잘 띄는 윗부분에만 화려한 장식을 붙입니다. 그러나 하나님 나라의 도성 새 예루살렘은 가장 밑바닥에서 성을 떠받치는 열두 기초석(어린양의 열두 사도와 성도들의 헌신) 자체가 대제사장 흉패의 보석들과 같은 가장 찬란한 열두 보석으로 노출되어 빛납니다! 세상에서 보이지 않는 기초석처럼 묵묵히 교회를 떠받치며 헌신한 성도들의 수고가 하나님 나라에서는 가장 영광스러운 보석으로 빛나게 됨을 보여줍니다.",
