    "title": "[대단원 완결] 새 예루살렘 성의 열두 대문은 왜 다이아몬드나 루비가 아니라 '각 문마다 한 개의 진주(열두 진주문)'(계 21:21)로 되어 있을까? — 살아있는 생명체가 상처와 아픔을 감싸 안아 빚어낸 유일한 보석 '진주(그리스도의 십자가 상처로 열린 구원의 문)'!",
