    "dossierMd": "■ [B300] [대단원 완결: 요한계시록 21장 21절 — '그 열두 문은 열두 진주니 각 문마다 한 개의 진주로 되어 있고'] 왜 천국 성문은 다이아몬드나 루비가 아니라, 살아있는 생명체가 아픔을 품어 만든 유일한 보석 '진주(마르가리테스)'일까?\n• 계 21:21\nP026(예수 그리스도), P122(사도 요한) · E030, E300 | 『꿈디도 성경 비하인드스토리 300선』의 마지막 300번째 이야기입니다! 다이아몬드·사파이어·에메랄드 등 세상의 모든 광물성 보석은 땅속 바위에서 캐내어 정으로 깎아 만듭니다. 그러나 세상의 모든 보석 중 유일하게 '살아있는 생명체(진주조개)'가 자기 몸속을 파고든 날카로운 모래알이나 이물질의 찢어지는 상처와 아픔을 견뎌내며, 수년 동안 자신의 생명 진액(진주층)으로 그 상처를 겹겹이 감싸 안아 빚어낸 눈물의 결정체가 바로 '진주(마르가리테스, μαργαρίτης)'입니다! 왜 우리가 천국에 들어가는 새 예루살렘의 열두 대문이 하나같이 '통진주(한 문이 한 진주)'로 되어 있을까요? 죄인인 우리가 하나님 나라에 들어갈 수 있는 유일한 문(요 10:9 \"나는 양의 문이라\")은, 우리의 죄라는 날카로운 가시와 창 자국을 자신의 몸으로 다 받아내시고 보혈과 사랑의 진액으로 우리를 감싸 안아 구원하신 예수 그리스도의 십자가 상처(진주문)이기 때문입니다! 천국 문을 통과하는 영원한 그날까지, 성도는 그 진주문 앞에서 우리를 위해 아픔을 품으신 어린양 예수님께 영원히 감사와 찬양을 올려드리게 될 것입니다. \"아멘 주 예수여 오시옵소서!\"(계 22:20)",
